local config = {
  ui_story_5031_50310101_1_dialog_content = "歡迎各位來賓光臨<color=#FFB400>魔手·比爾馬戲團</color>，我是本場演出的主持人——<color=#FFB400>虹霞</color>。",
  ui_story_5031_50310101_2_dialog_content = "在這絢麗的夜晚，每一位來到綠榴石號上的客人，都是我們馬戲團最尊貴的來賓。",
  ui_story_5031_50310101_3_dialog_content = "請您卸下煩惱與憂愁，盡情欣賞這精彩的表演。",
  ui_story_5031_50310101_4_dialog_content = "就由我們魔手·比爾馬戲團，為您帶來顛覆常識與想像的絕倫表演。",
  ui_story_5031_50310101_5_dialog_content = "這美妙的時刻屬於你和我，屬於全世界——！",
  ui_story_5031_50310101_6_dialog_content = "有請，我們的天空之演奏家，掌握了空中飛人至高技藝的三姐妹，梅爾特——",
  ui_story_5031_50310101_7_dialog_content = "薩布莉——",
  ui_story_5031_50310101_8_dialog_content = "菲爾姆——",
  ui_story_5031_50310101_9_dialog_content = "隆重登場——！",
  ui_story_5031_50310101_10_dialog_content = "那，那個。虹霞姐......現在空中飛人的設備不是正在保養調試嗎？",
  ui_story_5031_50310101_11_dialog_content = "是呀是呀，就算是我們也沒辦法直接飛到半空中進行表演吧～",
  ui_story_5031_50310101_12_dialog_content = "嘻嘻，其實菲爾姆最近有在跟馬戲團的大力士鍛鍊力量喔。",
  ui_story_5031_50310101_13_dialog_content = "說不定可以把梅爾姐和薩布姐直接丟到半空中呢。",
  ui_story_5031_50310101_14_dialog_content = "不，不要吧......太危險了。可能會傷到其他人的......",
  ui_story_5031_50310101_15_dialog_content = "我說老大，你也說句話嘛。",
  ui_story_5031_50310101_16_dialog_content = "明明道具都沒就緒，我們根本沒辦法彩排呀。",
  ui_story_5031_50310101_17_dialog_content = "而且憑我們三個的實力，完全不需要彩排的嘛！",
  ui_story_5031_50310101_18_dialog_content = "薩布......這樣對傑諾團長說話太凶啦。",
  ui_story_5031_50310101_19_dialog_content = "嗯？我正忙著。",
  ui_story_5031_50310101_20_dialog_content = "艾維斯的補給已經都送過來了，演出設備正在做最後調試。",
  ui_story_5031_50310101_21_dialog_content = "妳們三個不想彩排就隨便找個地方休息吧。",
  ui_story_5031_50310101_22_dialog_content = "虹霞，叫那個說能和動物溝通的臨時演員上來。",
  ui_story_5031_50310101_23_dialog_content = "讓她代替那個吃刨冰吃壞肚子的馴獸師表演試試。",
  ui_story_5031_50310101_24_dialog_content = "收到～",
  ui_story_5031_50310101_25_dialog_content = "菲雅小姐，妳準備好了嗎？",
  ui_story_5031_50310101_26_dialog_content = "再，再稍等一下！",
  ui_story_5031_50310101_27_dialog_content = "來，比卡，請到這邊。",
  ui_story_5031_50310101_28_dialog_content = "嗨。",
  ui_story_5031_50310101_29_dialog_content = "照我說的，跳起的同時翻個跟頭吧。",
  ui_story_5031_50310101_30_dialog_content = "嗨！",
  ui_story_5031_50310101_31_dialog_content = "拜託了，就乖乖聽我的話一次嘛，那個很兇的團長還在下面看著呢！",
  ui_story_5031_50310101_32_dialog_content = "嗨！！",
  ui_story_5031_50310101_33_dialog_content = "嗚！你冷靜點，我道歉還不好嗎，別再咬我啦！",
  ui_story_5031_50310101_34_dialog_content = "停停停！！",
  ui_story_5031_50310101_35_dialog_content = "馴獸師怎麼回事，下台處理！不要耽誤排練！",
  ui_story_5031_50310101_36_dialog_content = "傑諾團長！",
  ui_story_5031_50310101_37_dialog_content = "幹嘛？和小動物聊好了嗎？",
  ui_story_5031_50310101_38_dialog_content = "那些動物根本不聽話啊！完全一副被慣壞的樣子！",
  ui_story_5031_50310101_39_dialog_content = "什麼？不聽話？",
  ui_story_5031_50310101_40_dialog_content = "是啊！還很兇地一直想咬我。",
  ui_story_5031_50310101_41_dialog_content = "哦，那不是滿正常的。",
  ui_story_5031_50310101_42_dialog_content = "正常？？",
  ui_story_5031_50310101_43_dialog_content = "牠們在魔手馬戲團裡一直享有想工作就工作，不想工作就隨意行動的權利。",
  ui_story_5031_50310101_44_dialog_content = "什麼什麼？",
  ui_story_5031_50310101_45_dialog_content = "你們的馬戲團怎麼和我在書上看過的完全不一樣。",
  ui_story_5031_50310101_46_dialog_content = "我看書上說，你們應該是對動物們很兇，讓牠們因為恐懼而乖乖聽話進行表演吧？",
  ui_story_5031_50310101_47_dialog_content = "妳那是什麼偏見？",
  ui_story_5031_50310101_48_dialog_content = "我可從來不知道這種事，為什麼要對牠們很兇？牠們可是航行路上的重要夥伴。",
  ui_story_5031_50310101_49_dialog_content = "妳看這比卡身上毛絨絨的觸感，多麼治癒。",
  ui_story_5031_50310101_50_dialog_content = "嗨～～",
  ui_story_5031_50310101_51_dialog_content = "反正我的馬戲團不會這樣對待小動物。",
  ui_story_5031_50310101_52_dialog_content = "之前的馴獸師都能帶著動物進行表演，請妳多找找自己的原因。",
  ui_story_5031_50310101_53_dialog_content = "你，你說什麼！！",
  ui_story_5031_50310101_54_dialog_content = "嗚，我，我可是堂堂神奇動物專家，對神奇動物親和力突破天際的菲雅！",
  ui_story_5031_50310101_55_dialog_content = "怎麼可能會輸給，怎麼可能會輸......",
  ui_story_5031_50310101_56_dialog_content = "放心吧，PlayerName，芭蕾舞表演對我來說沒什麼難度。",
  ui_story_5031_50310101_57_dialog_content = "沒想到居然能看到卡蓮表演芭蕾。",
  ui_story_5031_50310101_58_dialog_content = "我聽巨像裡其他白夜城的光靈說，卡蓮可是讓芭蕾老師都驚歎的天才呢。",
  ui_story_5031_50310101_59_dialog_content = "真的嗎，薇絲這麼一說我也非常期待了。",
  ui_story_5031_50310101_60_dialog_content = "PlayerName——！",
  ui_story_5031_50310101_61_dialog_content = "菲雅？妳不是要表演馴獸嗎？怎麼跑來這裡了？",
  ui_story_5031_50310101_62_dialog_content = "嗚......嗚，那群可惡的神奇動物太氣人了，牠們居然可以想不工作就不工作。",
  ui_story_5031_50310101_63_dialog_content = "我一想起自己......自己還要被師父各種使喚就......嗚啊啊啊啊！",
  ui_story_5031_50310101_64_dialog_content = "別，別哭啊菲雅！",
  ui_story_5031_50310101_65_dialog_content = "千萬別忘了，妳可是偉大的神奇動物專家。",
  ui_story_5031_50310101_66_dialog_content = "嗚，明明都是神奇動物專家了，我為什麼還要整天被師父使喚來使喚去啦！",
  ui_story_5031_50310101_67_dialog_content = "不要想那些事了，妳要拿出那種對我胡攪蠻纏的氣勢！",
  ui_story_5031_50310101_68_dialog_content = "什麼啦！！",
  ui_story_5031_50310101_69_dialog_content = "哦不對，是要回想起我們共同經歷的重重難關，和妳偉大的目標——！",
  ui_story_5031_50310101_70_dialog_content = "嗚......我們共同的經歷......我們偉大的目標......",
  ui_story_5031_50310101_71_dialog_content = "<color=#e8d9bb>剛抵達好泊城時</color>",
  ui_story_5031_50310101_72_dialog_content = "卡蓮，謝謝妳邀請我和薇絲來好泊城。",
  ui_story_5031_50310101_73_dialog_content = "這個地方真是不錯呢，安靜閒適的氛圍讓人非常放鬆。",
  ui_story_5031_50310101_74_dialog_content = "大家能一起來真是太好了。",
  ui_story_5031_50310101_75_dialog_content = "不用客氣，我想大家最近應該也很辛苦，一起來適當放鬆一下也會更有利於身心。",
  ui_story_5031_50310101_76_dialog_content = "我上一次來好泊城還是很小的時候，不過當時這裡就給我留下了很深刻的印象。",
  ui_story_5031_50310101_77_dialog_content = "沒想到多年後，城市變得愈發繁榮，想必現任的領主也是一位賢明之士吧。",
  ui_story_5031_50310101_78_dialog_content = "<size=33>發現了......</size>",
  ui_story_5031_50310101_79_dialog_content = "會是像舒瓦茲大人那樣賢明的君主嗎？",
  ui_story_5031_50310101_80_dialog_content = "看到居民臉上的幸福神情，我也開始好奇這裡的統治者是什麼樣的人了呢。",
  ui_story_5031_50310101_81_dialog_content = "嗯......和城主大人他，應該還不太一樣吧。",
  ui_story_5031_50310101_82_dialog_content = "出於禮節，應當去拜訪一下領主，我們就一起去吧。",
  ui_story_5031_50310101_83_dialog_content = "我剛剛還看到街上貼著海報，在一艘巨大的航船上好像有什麼嘉年華和馬戲表演。",
  ui_story_5031_50310101_84_dialog_content = "我們也可以去問問那位領主詳細的情況。",
  ui_story_5031_50310101_85_dialog_content = "說到放鬆，參加一些很有夏天感覺的活動，肯定是最有效的放鬆方式啦！",
  ui_story_5031_50310101_86_dialog_content = "好！我也想請教請教他這座好泊城裡還有什麼好玩或者好吃的東西呢～",
  ui_story_5031_50310101_87_dialog_content = "看來薇絲已經很久沒出來玩，快按捺不住興奮的心情了吧。",
  ui_story_5031_50310101_88_dialog_content = "<size=33>鎖定目標——PlayerName！</size>",
  ui_story_5031_50310101_89_dialog_content = "那我們出——<size=50>嗷！</size>",
  ui_story_5031_50310101_90_dialog_content = "痛痛痛，腰好痛！",
  ui_story_5031_50310101_91_dialog_content = "（這個似曾相識的場景......）",
  ui_story_5031_50310101_92_dialog_content = "妳別再過來了，我真的會叫人來喔！",
  ui_story_5031_50310101_93_dialog_content = "動手——",
  ui_story_5031_50310101_94_option_content = "強制......嗷！！",
  ui_story_5031_50310101_95_dialog_content = "我的腰！！",
  ui_story_5031_50310101_96_dialog_content = "囉囉囉！",
  ui_story_5031_50310101_97_dialog_content = "幹得好凱羅，我們按原計畫撤退進森林裡！",
  ui_story_5031_50310101_98_dialog_content = "菲雅只是......菲雅只是想要一個朋友而已......",
  ui_story_5031_50310101_99_dialog_content = "囉......",
  ui_story_5031_50310101_100_dialog_content = "別人都說只有神奇動物會喜歡菲雅，菲雅也想證明自己能和光靈、空裔成為朋友......",
  ui_story_5031_50310101_101_dialog_content = "嘿嘿......那PlayerName，你就是我的第一位朋友啦！",
  ui_story_5031_50310101_102_dialog_content = "PlayerName你願意做菲雅的朋友，菲雅太高興啦！",
  ui_story_5031_50310101_103_dialog_content = "師父你看著吧，菲雅可是交到朋友了！",
  ui_story_5031_50310101_104_dialog_content = "果，果然是妳！菲雅！！",
  ui_story_5031_50310101_105_dialog_content = "為什麼要躲在垃圾桶裡伏擊我啊！",
  ui_story_5031_50310101_106_dialog_content = "嘿嘿，抓到了你了喔！PlayerName！",
  ui_story_5031_50310101_107_dialog_content = "菲雅？",
  ui_story_5031_50310101_108_dialog_content = "......總之就是這樣，她就是菲雅。",
  ui_story_5031_50310101_109_dialog_content = "原來她就是你之前遇到的小小神奇動物專家嗎？",
  ui_story_5031_50310101_110_dialog_content = "我倒是聽說過神奇動物專家那群人，但沒想到會有年紀這麼小的。",
  ui_story_5031_50310101_111_dialog_content = "好久不見啦，小菲雅。",
  ui_story_5031_50310101_112_dialog_content = "好久不見～薇絲姐姐。",
  ui_story_5031_50310101_113_dialog_content = "卡蓮姐姐，我是神奇動物專家菲雅。",
  ui_story_5031_50310101_114_dialog_content = "剛剛出師不久，還只是個不成熟的神奇動物專家，可能會給您添麻煩，希望您能多多指教。",
  ui_story_5031_50310101_115_dialog_content = "我是來自白夜城的卡蓮。妳給人的感覺很像是拉斐爾呢。",
  ui_story_5031_50310101_116_dialog_content = "有機會來把她介紹給妳吧，說不定妳們會很聊得來。",
  ui_story_5031_50310101_117_dialog_content = "稍等一下。",
  ui_story_5031_50310101_118_dialog_content = "喂喂，妳幹嘛突然裝得這麼乖。",
  ui_story_5031_50310101_119_dialog_content = "哪，哪有，菲雅一直很乖很溫柔的好嗎！PlayerName不許在別人面前說菲雅的壞話喔！",
  ui_story_5031_50310101_120_dialog_content = "是是，我對菲雅小姐能「溫柔」多久拭目以待囉。",
  ui_story_5031_50310101_121_dialog_content = "不過話說回來，妳為什麼跑來這裡了？凱羅呢？",
  ui_story_5031_50310101_122_dialog_content = "噓，菲雅這次可是和凱羅一起在執行師父的「<color=#FFB400>祕密任務</color>」喔。",
  ui_story_5031_50310101_123_dialog_content = "凱羅已經在附近的水域開始調查啦。",
  ui_story_5031_50310101_124_dialog_content = "什麼祕密任務，該不會又是之前那種亂七八糟的刁難人的任務吧？",
  ui_story_5031_50310101_125_dialog_content = "而且凱羅上次變得那麼大，游來游去不會很顯眼嗎？",
  ui_story_5031_50310101_126_dialog_content = "嗯哼，這就是小看凱羅了喔，牠現在已經掌握了在兩種型態之間變化的能力呢。",
  ui_story_5031_50310101_127_dialog_content = "師父說牠繼續努力練習的話......說不定還能變成人形？",
  ui_story_5031_50310101_128_dialog_content = "想想有點可怕啊。",
  ui_story_5031_50310101_129_dialog_content = "不用怕，你不惹到凱羅的話就不用怕～",
  ui_story_5031_50310101_130_dialog_content = "總之先別管牠啦！這次可是事關重大，關係到一隻「<color=#FFB400>珍奇物種</color>」的神奇動物呢！",
  ui_story_5031_50310101_131_dialog_content = "那個，雖然不是有意要偷聽。",
  ui_story_5031_50310101_132_dialog_content = "不過菲雅妹妹的聲音還是有點大了。",
  ui_story_5031_50310101_133_dialog_content = "既然特地找到PlayerName，想必是那個剛剛提到的「祕密任務」需要幫忙吧？",
  ui_story_5031_50310101_134_dialog_content = "唔，菲雅不小心太大聲了。",
  ui_story_5031_50310101_135_dialog_content = "不過既然是PlayerName的朋友，那麼卡蓮姐姐和薇絲姐姐也一定值得信賴。",
  ui_story_5031_50310101_136_dialog_content = "那菲雅會把情況一五一十和大家說清楚的。",
  ui_story_5031_50310101_137_dialog_content = "其實在前幾天——",
  ui_story_5031_50310101_138_dialog_content = "什麼！真的可以去好泊城嗎？",
  ui_story_5031_50310101_139_dialog_content = "嘿嘿，聽說那裡風景宜人，好吃的東西也很多。",
  ui_story_5031_50310101_140_dialog_content = "沒想到師父很疼愛菲雅呢，知道我很辛苦想讓我好好放鬆一下。",
  ui_story_5031_50310101_141_dialog_content = "那裡的沙灘好像也很出名呀，菲雅都還沒準備泳衣呢。",
  ui_story_5031_50310101_142_dialog_content = "不，妳想得也太美了吧......",
  ui_story_5031_50310101_143_dialog_content = "有這種好事我肯定會一馬當先。",
  ui_story_5031_50310101_144_dialog_content = "都說了是任務，肯定不是去玩啦。",
  ui_story_5031_50310101_145_dialog_content = "給妳旅費，快點出發吧。",
  ui_story_5031_50310101_146_dialog_content = "欸！怎麼這麼少啊！",
  ui_story_5031_50310101_147_dialog_content = "等，等等啊師父，你怎麼就要走了！？",
  ui_story_5031_50310101_148_dialog_content = "唉，我就知道那個可惡的師父沒有這麼好心。",
  ui_story_5031_50310101_149_dialog_content = "嗯，說了半天完全在抱怨師父呢，關鍵的資訊一點都沒說。",
  ui_story_5031_50310101_150_dialog_content = "接下來就要說了！",
  ui_story_5031_50310101_151_dialog_content = "這次的目標是一隻名叫「<color=#FFB400>海雲鯨</color>」的神奇動物。",
  ui_story_5031_50310101_152_dialog_content = "師父始終追蹤著牠所擁有的特殊光能，似乎是來到了附近水域。",
  ui_story_5031_50310101_153_dialog_content = "然而最近這股光能突然消失了。",
  ui_story_5031_50310101_154_dialog_content = "因為消失得太突然，無影無蹤，所以肯定不是離開了，而是遇到了什麼事情！",
  ui_story_5031_50310101_155_dialog_content = "情況豈不是非常不妙。",
  ui_story_5031_50310101_156_dialog_content = "沒錯，師父說這只「珍奇物種」的力量甚至比蒼獅龍還要強大。",
  ui_story_5031_50310101_157_dialog_content = "傳說中，牠擁有讓暗鬼膽寒，足以驅散暗能的強大光能。",
  ui_story_5031_50310101_158_dialog_content = "而且牠的壽命很長，不太可能是自然死亡。",
  ui_story_5031_50310101_159_dialog_content = "所以師父擔心牠是不是被別有用心的人捕獲了。",
  ui_story_5031_50310101_160_dialog_content = "雖然牠本性善良，但如果力量被壞人利用，可能會造成非常可怕的後果。",
  ui_story_5031_50310101_161_dialog_content = "如果情況真的如妳所說......那我們也不能坐視不管。",
  ui_story_5031_50310101_162_dialog_content = "妳現在有什麼頭緒嗎？",
  ui_story_5031_50310101_163_dialog_content = "唔，完全沒有！師父也是交代完之後就匆匆忙忙出門了。",
  ui_story_5031_50310101_164_dialog_content = "所以妳在好泊城裡就像個無頭蒼蠅一樣亂轉，發現我之後就在這裡伏擊了？",
  ui_story_5031_50310101_165_dialog_content = "PlayerName真是太聰明啦！老實說師父給菲雅的旅費已經見底了。",
  ui_story_5031_50310101_166_dialog_content = "如果PlayerName沒出現的話都不知道該怎麼辦才好呢。",
  ui_story_5031_50310101_167_dialog_content = "我就知道。",
  ui_story_5031_50310101_168_dialog_content = "不如先試著收集情報吧，我們正要去拜訪這裡的領主。",
  ui_story_5031_50310101_169_dialog_content = "說不定能從他口中瞭解到些情況。",
  ui_story_5031_50310101_170_dialog_content = "好！那就聽卡蓮姐姐的，我們出發！",
  ui_story_5031_50310101_171_dialog_content = "喂——妳走在最前面是知道路嗎？",
  ui_story_5031_50310101_172_dialog_content = "還真是有活力呀。",
  ui_story_5031_50310201_1_dialog_content = "<color=#FFB400>艾維斯</color>閣下，那些忠於您的士兵已經做好準備。",
  ui_story_5031_50310201_2_dialog_content = "正如您的計畫，我們會以為綠榴石號搬運補給品和煙火作為掩護。",
  ui_story_5031_50310201_3_dialog_content = "嗯，我知道了。",
  ui_story_5031_50310201_4_dialog_content = "辛苦你了，帕托隊長。也許這次，我能信任的只有你......",
  ui_story_5031_50310201_5_dialog_content = "是，請儘管交給屬下。能為艾維斯閣下效力是我的榮幸。",
  ui_story_5031_50310201_6_dialog_content = "唉，若不是機會轉瞬即逝，我也不會讓你們這樣鋌而走險。",
  ui_story_5031_50310201_7_dialog_content = "報，報告！艾維斯大人，帕托隊長！",
  ui_story_5031_50310201_8_dialog_content = "混帳，我不是說過任何人都不許進來嗎？",
  ui_story_5031_50310201_9_dialog_content = "是，是的，屬下知錯。但是有一位貴客前來拜訪......",
  ui_story_5031_50310201_10_dialog_content = "什麼貴客？這樣慌慌張張的，丟了我們摩德利家族親兵的臉。",
  ui_story_5031_50310201_11_dialog_content = "報告，是，是卡蓮殿下來訪！",
  ui_story_5031_50310201_12_dialog_content = "什麼？白夜城的卡蓮殿下？",
  ui_story_5031_50310201_13_dialog_content = "照卡蓮的說法，好泊城是在暗潮危機前正式歸屬於白夜城，接受白夜城的保護。",
  ui_story_5031_50310201_14_dialog_content = "那他們在之前，都是依靠自己的力量保護家園嗎？",
  ui_story_5031_50310201_15_dialog_content = "文獻記載，好泊城曾經有許多暗鬼出沒，生活在這裡的人們與暗鬼持續爭奪著這片土地。",
  ui_story_5031_50310201_16_dialog_content = "持久的戰爭中，此地的統治者，擁有強大光能的「<color=#FFB400>摩德利</color>」家族與其他家族合力。",
  ui_story_5031_50310201_17_dialog_content = "經過無數次艱苦卓絕的戰鬥，最終趕走了所有暗鬼。",
  ui_story_5031_50310201_18_dialog_content = "之後……",
  ui_story_5031_50310201_19_dialog_content = "之後這片土地，就如同被「<color=#FFB400>光之神</color>」庇佑，極少有暗鬼滋擾。",
  ui_story_5031_50310201_20_dialog_content = "人民安居樂業，城市發展欣欣向榮。",
  ui_story_5031_50310201_21_dialog_content = "卡蓮殿下，我很榮幸您對好泊城的過去如此瞭解。",
  ui_story_5031_50310201_22_dialog_content = "也很感謝您和白夜城的保護，畢竟光靠「<color=#FFB400>神之庇護</color>」可無法在暗潮危機中存活。",
  ui_story_5031_50310201_23_dialog_content = "在下是艾維斯·摩德利，也就是摩德利家族的後裔，也是好泊城的現任領主。",
  ui_story_5031_50310201_24_dialog_content = "（好奇怪，這個人身上......光能怎麼會這麼弱？）",
  ui_story_5031_50310201_25_dialog_content = "你好，艾維斯閣下，希望我的突然到來不會給你造成困擾。",
  ui_story_5031_50310201_26_dialog_content = "當然不會，不過若是殿下能提前告知，在下也能早做準備恭迎您。",
  ui_story_5031_50310201_27_dialog_content = "不必如此，我正是不希望勞師動眾才直接登門拜訪的，希望艾維斯閣下也能不如此拘禮。",
  ui_story_5031_50310201_28_dialog_content = "畢竟我們一行人只是普通的遊客，行至此地散散心。",
  ui_story_5031_50310201_29_dialog_content = "我明白卡蓮殿下的意思了，那麼想必這位就是傳聞中的空裔和薇絲小姐吧。",
  ui_story_5031_50310201_30_dialog_content = "你好，我是PlayerName。",
  ui_story_5031_50310201_31_dialog_content = "我是薇絲，沒想到艾維斯閣下不光知道PlayerName，連我的事也清楚呢。",
  ui_story_5031_50310201_32_dialog_content = "那，那個！",
  ui_story_5031_50310201_33_dialog_content = "嗯？這位是？",
  ui_story_5031_50310201_34_dialog_content = "我是神奇動物專家菲雅！也是PlayerName、卡蓮姐姐、薇絲姐姐的朋友喔！",
  ui_story_5031_50310201_35_dialog_content = "呵呵，我明白了，神奇動物專家，菲雅小姐。",
  ui_story_5031_50310201_36_dialog_content = "我已經準備好宴席，就請讓我盡地主之誼，請大家一起用餐吧。",
  ui_story_5031_50310201_37_dialog_content = "嗯......薇絲小姐是對「<color=#FFB400>綠榴石號</color>」上舉行的活動很有興趣嗎？",
  ui_story_5031_50310201_38_dialog_content = "實不相瞞，其實正是我向擁有「綠榴石號」的「<color=#FFB400>魔手·比爾馬戲團</color>」發出的邀請。",
  ui_story_5031_50310201_39_dialog_content = "希望他們能在這個盛夏時分為好泊城的人民帶來一場盛大的活動，留下別樣的回憶。",
  ui_story_5031_50310201_40_dialog_content = "居然整艘船都是馬戲團嗎，的確有種非常浪漫的感覺呢......",
  ui_story_5031_50310201_41_dialog_content = "是的，如果幾位有興趣的話，也可以考慮參加。",
  ui_story_5031_50310201_42_dialog_content = "它的現任團長是我的幼時好友，雖然許久未見，但他的能力值得信賴。",
  ui_story_5031_50310201_43_dialog_content = "肯定也能將嘉年華組織得有聲有色。",
  ui_story_5031_50310201_44_dialog_content = "啊......航船！",
  ui_story_5031_50310201_45_dialog_content = "那個，請問一下！可以讓領主閣下的朋友帶我們在船的內部參觀一下嗎？",
  ui_story_5031_50310201_46_dialog_content = "嗯？",
  ui_story_5031_50310201_47_dialog_content = "<size=33>菲雅！妳為什麼突然問這種奇怪的問題啊？</size>",
  ui_story_5031_50310201_48_dialog_content = "我突然想起凱羅之前告訴我，好泊城港口停著一艘很巨大又奇怪的船。",
  ui_story_5031_50310201_49_dialog_content = "如果「海雲鯨」消失的話，也有很大可能是被人抓了關在這種船裡啦！",
  ui_story_5031_50310201_50_dialog_content = "抱歉，這個恐怕不行。",
  ui_story_5031_50310201_51_dialog_content = "欸，為什麼？",
  ui_story_5031_50310201_52_dialog_content = "詳細的理由我也不知道，但這恐怕是他們馬戲團的一些規則。",
  ui_story_5031_50310201_53_dialog_content = "昨天我曾因為想和團長<color=#FFB400>傑諾</color>商討作為報酬的補給品的詳細事宜。",
  ui_story_5031_50310201_54_dialog_content = "本以為他會帶我稍微參觀一下船的內部，但他也只願意和我在船艙走廊裡商議。",
  ui_story_5031_50310201_55_dialog_content = "我當時也因為好奇提出希望能參觀一下這艘宏偉的航船。",
  ui_story_5031_50310201_56_dialog_content = "不過他用「馬戲團的規矩，只有馬戲團的人才能進入船艙深處」回絕我了。",
  ui_story_5031_50310201_57_dialog_content = "作為好友和贊助商的我都如此，各位恐怕很難進去了。",
  ui_story_5031_50310201_58_dialog_content = "諸位是有什麼想進入船艙內部的原因嗎？我可以試著再向團長傑諾去協調。",
  ui_story_5031_50310201_59_dialog_content = "其實菲雅她啊......",
  ui_story_5031_50310201_60_dialog_content = "啊哈哈！其實菲雅只是好奇啦，菲雅是從小地方來的，很好奇船裡面是什麼樣的。",
  ui_story_5031_50310201_61_dialog_content = "<size=33>我們這是祕密任務！不可以把珍奇物種的情報到處說啦！</size>",
  ui_story_5031_50310201_62_dialog_content = "我能理解菲雅小姐的心情，畢竟那麼巨大的船並不多見。",
  ui_story_5031_50310201_63_dialog_content = "也應該有很多參加嘉年華的人都是出於好奇心吧。",
  ui_story_5031_50310201_64_dialog_content = "嗯，我會和傑諾溝通試試的。",
  ui_story_5031_50310201_65_dialog_content = "真的嗎！太感謝您啦！",
  ui_story_5031_50310201_66_dialog_content = "不用客氣，不過別報太大希望喔，畢竟連贊助商的請求傑諾都一口回絕了。",
  ui_story_5031_50310201_67_dialog_content = "但甲板上也會舉行嘉年華和美食比賽，以及馬戲表演等等熱鬧的活動。",
  ui_story_5031_50310201_68_dialog_content = "相信也可以滿足菲雅小姐的好奇心。",
  ui_story_5031_50310201_69_dialog_content = "咳......咳咳！",
  ui_story_5031_50310201_70_dialog_content = "艾維斯大人！",
  ui_story_5031_50310201_71_dialog_content = "我沒事，帕托。",
  ui_story_5031_50310201_72_dialog_content = "可能是卡蓮和諸位的光臨讓我太高興，聊得興起甚至都忘記吃藥了。",
  ui_story_5031_50310201_73_dialog_content = "艾維斯閣下......",
  ui_story_5031_50310201_74_dialog_content = "感謝你的盛情款待，艾維斯閣下。",
  ui_story_5031_50310201_75_dialog_content = "哪裡哪裡，希望大家沒有因為我剛剛的不適而掃興。",
  ui_story_5031_50310201_76_dialog_content = "怎麼會，艾維斯閣下還請保重身體。",
  ui_story_5031_50310201_77_dialog_content = "我們準備去綠榴石號上瞭解一下嘉年華的情況，領主閣下就不用遠送了。",
  ui_story_5031_50310201_78_dialog_content = "......我明白了，我現在去準備一下獻給您的禮物，稍後會趕去綠榴石號上。",
  ui_story_5031_50310201_79_dialog_content = "這是君臣之禮，而非繁文縟節，希望卡蓮殿下一定收下。",
  ui_story_5031_50310201_80_dialog_content = "既然閣下執意如此，那我也就不推脫了。",
  ui_story_5031_50310201_81_dialog_content = "我們走吧，大家。",
  ui_story_5031_50310201_82_dialog_content = "……",
  ui_story_5031_50310201_83_dialog_content = "艾維斯閣下。",
  ui_story_5031_50310201_84_dialog_content = "帕托，命令手下馬上準備行動。",
  ui_story_5031_50310201_85_dialog_content = "這......莫非是白夜城的人已經察覺到什麼了？",
  ui_story_5031_50310201_86_dialog_content = "不，現在還無法判斷，但我會關注他們。",
  ui_story_5031_50310201_87_dialog_content = "無論如何，今天必須行動。",
  ui_story_5031_50310201_88_dialog_content = "艾維斯閣下，請恕在下愚笨，您不能直接向團長傑諾尋求幫助嗎？",
  ui_story_5031_50310201_89_dialog_content = "他應該是您的幼時好友吧。",
  ui_story_5031_50310201_90_dialog_content = "事情沒那麼簡單，也不能僅憑舊時的感情就去信任他。",
  ui_story_5031_50310201_91_dialog_content = "我昨天就提出希望能參觀綠榴石號深處，被他斷然回絕了。",
  ui_story_5031_50310201_92_dialog_content = "根據我的調查，他現在效忠於名為「<color=#FFB400>真理結社</color>」的組織。",
  ui_story_5031_50310201_93_dialog_content = "貿然透露我們的目標......很容易導致整個計畫流產。",
  ui_story_5031_50310201_94_dialog_content = "我現在已經不知道，那個曾經的好友還是否可信......",
  ui_story_5031_50310201_95_dialog_content = "我明白了，艾維斯閣下，就請交給屬下吧。",
  ui_story_5031_50310201_96_dialog_content = "嗯，我也會繼續試探傑諾，到底還是不是我認識的那個「他」......",
  ui_story_5031_50310201_97_dialog_content = "艾維斯領主感覺是個不錯的人呢，這麼熱情的款待我們，對我和薇絲也非常親切。",
  ui_story_5031_50310201_98_dialog_content = "是呀，感覺比一些貴族要友善很多，也沒什麼貴族架子。",
  ui_story_5031_50310201_99_dialog_content = "嗯，摩德利家族和許多貴族不同。他們對自己的人民十分愛護，也深受人民的愛戴。",
  ui_story_5031_50310201_100_dialog_content = "作為統治者來說，應該算是非常優秀的一族。不過可惜......",
  ui_story_5031_50310201_101_dialog_content = "啊，難道是因為他的光能力量很弱？",
  ui_story_5031_50310201_102_dialog_content = "看來你也察覺到了，艾維斯剛剛突然咳嗽不止，那不是簡單的感冒之類的疾病。",
  ui_story_5031_50310201_103_dialog_content = "連同他臉上那痕跡一樣......是一種叫做「<color=#FFB400>摩德利失能症</color>」的疾病。",
  ui_story_5031_50310201_104_dialog_content = "沒想到他面部的痕跡是這樣造成的。",
  ui_story_5031_50310201_105_dialog_content = "那，這種病很嚴重嗎？",
  ui_story_5031_50310201_106_dialog_content = "其實我對這種疾病也不是非常瞭解，只是曾經在研習歷史時接觸過相關知識。",
  ui_story_5031_50310201_107_dialog_content = "我抱著好奇心進一步查閱資料時，發現關於摩德利失能症和他們家族的記載少之又少。",
  ui_story_5031_50310201_108_dialog_content = "只知道這種疾病會使患病人的光能力量迅速減弱，並長期保持在很低的水準。",
  ui_story_5031_50310201_109_dialog_content = "如果原本擁有強大的光能還好，但如果光能與常人無異，發病後就會影響正常生活。",
  ui_story_5031_50310201_110_dialog_content = "而且病情嚴重時，甚至會危及生命。",
  ui_story_5031_50310201_111_dialog_content = "這麼可怕嗎！？",
  ui_story_5031_50310201_112_dialog_content = "嗯，不過這種病非常特殊，只在好泊城地區發現過，有學者認為是一種地區病。",
  ui_story_5031_50310201_113_dialog_content = "但好泊城的人民堅持認定，這種病是他們「<color=#FFB400>英雄血脈</color>」的證明。",
  ui_story_5031_50310201_114_dialog_content = "那些曾參與過驅逐暗鬼的先祖們，以無比的勇氣承擔了暗鬼的詛咒，患上了這種病。",
  ui_story_5031_50310201_115_dialog_content = "而傳承他們血脈的後人，也會有機率患上這種病症。",
  ui_story_5031_50310201_116_dialog_content = "好在據說這些年患病者也在逐年減少。",
  ui_story_5031_50310201_117_dialog_content = "唔，原來如此原來如此。",
  ui_story_5031_50310201_118_dialog_content = "妳幹嘛一副聽懂了的樣子。",
  ui_story_5031_50310201_119_dialog_content = "我，我當然聽懂了啊。不要以為菲雅年紀小就是笨蛋了。",
  ui_story_5031_50310201_120_dialog_content = "不管怎麼說，那位領主應該最清楚自己的宿命。",
  ui_story_5031_50310201_121_dialog_content = "就像菲雅命中注定一定會成為神奇動物專家一樣。",
  ui_story_5031_50310201_122_dialog_content = "延續無數代的榮耀和傳承，其中一定十分複雜和厚重。",
  ui_story_5031_50310201_123_dialog_content = "單單從外人的眼光來看是難以做出評判的。",
  ui_story_5031_50310201_124_dialog_content = "菲雅說得也有道理呢。",
  ui_story_5031_50310201_125_dialog_content = "菲雅說話還挺像回事的，雖然說了和沒說的意思差不多。",
  ui_story_5031_50310201_126_dialog_content = "嘿嘿，總之先別管那麼多了，我們現在的目標是綠榴石號吧，快走快走～",
  ui_story_5031_50310201_127_dialog_content = "趕快衝過去拯救「珍奇物種」，完成任務菲雅就有時間和大家一起玩啦。",
  ui_story_5031_50310201_128_dialog_content = "別拽別拽，妳怎麼就認定自己能進到綠榴石號的內部啊！",
  ui_story_5031_50310201_129_dialog_content = "就憑菲雅的迷人魅力不就可以了嗎？",
  ui_story_5031_50310201_130_dialog_content = "什麼迷人魅力......妳裝成個小動物混進去表演還有點可能性。",
  ui_story_5031_50310201_131_dialog_content = "嗚——！",
  ui_story_5031_50310201_132_dialog_content = "你這又是在變相說菲雅矮對不對！",
  ui_story_5031_50310201_133_dialog_content = "過來，給我過來！",
  ui_story_5031_50310201_134_dialog_content = "幹嘛啦菲雅！妳拽的太用力了。",
  ui_story_5031_50310201_135_dialog_content = "我要把你丟進海裡，讓凱羅把你當成球一樣頂在頭上！",
  ui_story_5031_50310201_136_dialog_content = "什麼？凱羅是什麼海豹嗎？妳這樣凱羅會傷心的！",
  ui_story_5031_50310201_137_dialog_content = "我才不管——",
  ui_story_5031_50310201_138_dialog_content = "呼......看著他們吵鬧的樣子，我也感覺放鬆下來了。",
  ui_story_5031_50310201_139_dialog_content = "是呀，好久都沒這麼輕鬆過了。",
  ui_story_5031_50310201_140_dialog_content = "等一下！",
  ui_story_5031_50310201_141_dialog_content = "別，別鬧了！怎麼了，卡蓮？",
  ui_story_5031_50310201_142_dialog_content = "在這種海邊......怎麼會有暗鬼。",
  ui_story_5031_50310201_143_dialog_content = "大家小心，這些暗鬼看起來樣子怪怪的，我們準備戰鬥！",
  ui_story_5031_50310202_1_dialog_content = "嘎……",
  ui_story_5031_50310202_2_dialog_content = "這些暗鬼怎麼這麼弱......",
  ui_story_5031_50310202_3_dialog_content = "幾位，沒有受傷吧。",
  ui_story_5031_50310202_4_dialog_content = "您，您是卡蓮殿下！都怪我們的失職，居然險些讓暗鬼傷了您！",
  ui_story_5031_50310202_5_dialog_content = "不必這麼驚慌，我們不是手無寸鐵的市民，能夠保護自己。",
  ui_story_5031_50310202_6_dialog_content = "但你們還是需要時刻警惕，危險可能潛伏在暗處。",
  ui_story_5031_50310202_7_dialog_content = "是！謹遵卡蓮殿下的教導，我們一定加強巡邏，查明最近海岸邊暗鬼出現的原因。",
  ui_story_5031_50310202_8_dialog_content = "很好，去執行你的使命吧，衛兵。",
  ui_story_5031_50310202_9_dialog_content = "是！",
  ui_story_5031_50310202_10_dialog_content = "卡蓮姐姐好酷——！一言一行都帶著王者風範呢！",
  ui_story_5031_50310202_11_dialog_content = "當然了，卡蓮可是白夜城城主的女兒喔，未來一定是優秀的統治者。",
  ui_story_5031_50310202_12_dialog_content = "謝謝......不過我還不夠成熟呢。",
  ui_story_5031_50310202_13_dialog_content = "不聊這個了，前面就是之前提過的「綠榴石號」了，我們快點過去吧。",
  ui_story_5031_50310202_14_dialog_content = "請想參加美食比賽的遊客這邊請～",
  ui_story_5031_50310202_15_dialog_content = "這就是船上了嗎？人來人往的好熱鬧。",
  ui_story_5031_50310202_16_dialog_content = "PlayerName，我們先試著收集一下情報吧。",
  ui_story_5031_50310202_17_dialog_content = "很有道理。",
  ui_story_5031_50310202_18_dialog_content = "妳好，我想問一下關於嘉年華的......",
  ui_story_5031_50310202_19_dialog_content = "唷——歡迎幾位貴客光臨「魔手·比爾馬戲團」！",
  ui_story_5031_50310202_20_dialog_content = "看起來幾位應該是第一次來到本馬戲團吧，還請不要客氣，這邊請。",
  ui_story_5031_50310202_21_dialog_content = "不過不可以在船上做奇怪的事呢，如果亂來的話我就不客氣了——",
  ui_story_5031_50310202_22_dialog_content = "梅爾特姐姐，傑諾團長派我們一起來做迎賓工作，妳可不能偷懶喔～",
  ui_story_5031_50310202_23_dialog_content = "來～來～那邊好像過來一位很合妳口味的小哥喔，試著打個招呼吧。",
  ui_story_5031_50310202_24_dialog_content = "呀！薩，薩布莉，不要推我啦......",
  ui_story_5031_50310202_25_dialog_content = "嘿嘿，不過他真的很像欸，妳湊近一些看看嘛。",
  ui_story_5031_50310202_26_dialog_content = "嗯？像什麼呀，妳們在說什麼？",
  ui_story_5031_50310202_27_dialog_content = "就是梅爾姐收藏的那張影鎮小報上面的人嘛！",
  ui_story_5031_50310202_28_dialog_content = "妳們在說什麼？",
  ui_story_5031_50310202_29_dialog_content = "等等，真的好像呀，你該不會就是那個空裔吧？",
  ui_story_5031_50310202_30_dialog_content = "啊，沒錯，我是空裔......妳們為什麼會認得我？",
  ui_story_5031_50310202_31_dialog_content = "——！！",
  ui_story_5031_50310202_32_dialog_content = "薩布姐，梅爾姐怎麼跑了呀？",
  ui_story_5031_50310202_33_dialog_content = "我們要先把這人抓了嗎？",
  ui_story_5031_50310202_34_dialog_content = "什麼？？",
  ui_story_5031_50310202_35_dialog_content = "哈哈，這下有趣了，不可以亂來喔菲爾姆，先去追梅爾姐，這邊就交給虹霞姐吧。",
  ui_story_5031_50310202_36_dialog_content = "喂——妳們怎麼又要偷懶呀。",
  ui_story_5031_50310202_37_dialog_content = "真是抱歉，那三個孩子是臨時來幫忙的。",
  ui_story_5031_50310202_38_dialog_content = "幾位是來參加嘉年華的吧～",
  ui_story_5031_50310202_39_dialog_content = "我是馬戲團的主持人兼職迎賓員兼職保全人員主職實習輪機師虹霞～",
  ui_story_5031_50310202_40_dialog_content = "好，好長的頭銜啊。",
  ui_story_5031_50310202_41_dialog_content = "嘿嘿，大家也都說虹霞很厲害呢。",
  ui_story_5031_50310202_42_dialog_content = "大姐姐妳好～菲雅想問一下怎麼去船裡——嗚！",
  ui_story_5031_50310202_43_dialog_content = "妳這樣直接問的話，人家怎麼可能老老實實讓你過去。",
  ui_story_5031_50310202_44_dialog_content = "那，那要怎麼辦嘛。",
  ui_story_5031_50310202_45_dialog_content = "你好，我們想詢問一下如何參加嘉年華。",
  ui_story_5031_50310202_46_dialog_content = "嘉年華的話，還在準備中喔，客人們只要留在船上，等待召開的訊號就可以了。",
  ui_story_5031_50310202_47_dialog_content = "諸位客人可以先去我們的美食比賽區域～",
  ui_story_5031_50310202_48_dialog_content = "那邊馬上會展開激烈的較量，另外還有許多有趣的攤位喔。",
  ui_story_5031_50310202_49_dialog_content = "只要往那邊走就是了～",
  ui_story_5031_50310202_50_dialog_content = "謝謝妳，我們先去隨便逛逛了。",
  ui_story_5031_50310202_51_dialog_content = "剛剛那幾個馬戲團的人，感覺好奇妙呢。",
  ui_story_5031_50310202_52_dialog_content = "特別是那個三姐妹，似乎對PlayerName很感興趣的樣子。",
  ui_story_5031_50310202_53_dialog_content = "是嗎......我倒是希望不要被奇奇怪怪的人纏上。",
  ui_story_5031_50310202_54_dialog_content = "畢竟我身邊發生過的麻煩事太多了，現在還是希望能和大家一起放鬆一下。",
  ui_story_5031_50310202_55_dialog_content = "唔，菲雅到底要怎麼樣才能進到船裡面嘛。",
  ui_story_5031_50310202_56_dialog_content = "明明剛剛差點成功說服那位看起來很好說話的大姐姐了。",
  ui_story_5031_50310202_57_dialog_content = "妳直接說出來的話，很有可能就被直接丟下船了喔？",
  ui_story_5031_50310202_58_dialog_content = "別忘了艾維斯說過，只有馬戲團的內部成員才能進入。",
  ui_story_5031_50310202_59_dialog_content = "總之我們先試著在船上調查一下吧，說不定會有什麼發現。",
  ui_story_5031_50310202_60_dialog_content = "等等，那邊稍遠些的攤位裡......好像有很多熟悉的面孔。",
  ui_story_5031_50310202_61_dialog_content = "在這苦夏難耐之日，請各位品嚐世界上獨一無二的消暑佳品。",
  ui_story_5031_50310202_62_dialog_content = "現在還有最新推出的口味「<color=#FFB400>好泊城風行限量口味</color>」。",
  ui_story_5031_50310202_63_dialog_content = "只要一次性購買十杯刨冰，本店還會送上印有空裔圖案的保溫手提袋。",
  ui_story_5031_50310202_64_dialog_content = "好的，這位美麗的女士，請拿好您的十杯刨冰和保溫袋。",
  ui_story_5031_50310202_65_dialog_content = "那是我發明的刨冰欸！克萊肯居然還用上了你的形象！",
  ui_story_5031_50310202_66_dialog_content = "薇絲......妳還記得去年和克萊肯簽過「<color=#FFB400>技術轉讓協議</color>」吧？",
  ui_story_5031_50310202_67_dialog_content = "我猜，這可能就是那份協議造成的後果。",
  ui_story_5031_50310202_68_dialog_content = "唔，唔......太甜了。",
  ui_story_5031_50310202_69_dialog_content = "不如薇絲做的刨冰味道富有層次感呢。",
  ui_story_5031_50310202_70_dialog_content = "我，我也想要一杯！",
  ui_story_5031_50310202_71_dialog_content = "我說你們！怎麼馬上就跑去買了。",
  ui_story_5031_50310202_72_dialog_content = "薇絲可是還沉浸在刨冰事業被奪走的悲傷之中呢。",
  ui_story_5031_50310202_73_dialog_content = "我，我沒事......只要大家都能吃到好吃的刨冰，我就，我就......",
  ui_story_5031_50310202_74_dialog_content = "我要去讓克萊肯把技術轉讓回來！！",
  ui_story_5031_50310202_75_dialog_content = "<color=#e8d9bb>片刻後</color>",
  ui_story_5031_50310202_76_dialog_content = "嗚！冰冰的。",
  ui_story_5031_50310202_77_dialog_content = "不能一口氣吃太多喔，會頭疼的。",
  ui_story_5031_50310202_78_dialog_content = "薇絲還在和克萊肯談嗎，沒事吧。",
  ui_story_5031_50310202_79_dialog_content = "PlayerName！",
  ui_story_5031_50310202_80_dialog_content = "嗯？這個熟悉的聲音？",
  ui_story_5031_50310202_81_dialog_content = "PlayerName，沒想到真的是你。",
  ui_story_5031_50310202_82_dialog_content = "弗勞爾？你怎麼也在這裡。",
  ui_story_5031_50310202_83_dialog_content = "嗯？你不是來參加「怪之鍋爭奪戰」嗎？就是馬上要舉行的美食比賽喔。",
  ui_story_5031_50310202_84_dialog_content = "對了，還要感謝你上次幫我烤制麵包。",
  ui_story_5031_50310202_85_dialog_content = "之後我想了很多，然後決定參加比賽繼續磨煉自己的廚藝，讓這份美味傳遍大陸。",
  ui_story_5031_50310202_86_dialog_content = "啊，倒是不用感謝我，美食比賽什麼的我也是剛剛才聽說......「<color=#FFB400>怪之鍋</color>」？",
  ui_story_5031_50310202_87_dialog_content = "等一下！難道是紅油沙漠的料理鐵人——",
  ui_story_5031_50310202_88_dialog_content = "「暗鬼肉質品鑒家」——強尼叔叔！沒錯！他所使用過的「怪之鍋」！",
  ui_story_5031_50310202_89_dialog_content = "卡蓮姐姐，強尼叔叔是誰呀？",
  ui_story_5031_50310202_90_dialog_content = "好像是某本在紅油沙漠很流行的食譜的作者，詳細的我也不是很清楚。",
  ui_story_5031_50310202_91_dialog_content = "唉，為什麼你會對這種東西如此著迷啊......",
  ui_story_5031_50310202_92_dialog_content = "他可不是普通的美食作家！他曾經用這口鍋做出過風靡大陸的美食呢！",
  ui_story_5031_50310202_93_dialog_content = "莫莫莫莫非強尼叔叔也會來參加怪之鍋爭奪戰嗎？",
  ui_story_5031_50310202_94_dialog_content = "啊不對，他很大可能還在雲遊四方，難道說「怪之鍋爭奪戰」是指！",
  ui_story_5031_50310202_95_dialog_content = "沒錯！第一名的獎品就是這口「怪之鍋」！！",
  ui_story_5031_50310202_96_dialog_content = "雖然不知道他本人會不會來，但他使用過的傳說之炊具就足以讓各路英雄聚首！",
  ui_story_5031_50310202_97_dialog_content = "我要參加！讓我參加！！",
  ui_story_5031_50310202_98_dialog_content = "只要把這口鍋送給薇絲，就能讓巨像上所有的人獲得幸福了！",
  ui_story_5031_50310202_99_dialog_content = "嗚哇！PlayerName你突然這麼大聲幹嘛！激動過頭了吧。",
  ui_story_5031_50310202_100_dialog_content = "抱歉了弗勞爾，我們和PlayerName私下聊一下。",
  ui_story_5031_50310202_101_dialog_content = "卡蓮，菲雅，別拽我啊。",
  ui_story_5031_50310202_102_dialog_content = "我！弗勞爾，等我！！我會回來的！！",
  ui_story_5031_50310202_103_dialog_content = "好的，我會等著你！",
  ui_story_5031_50310202_104_dialog_content = "PlayerName，我就在這裡一直等著你回來！",
  ui_story_5031_50310202_105_dialog_content = "PlayerName，稍微冷靜點了嗎。",
  ui_story_5031_50310202_106_dialog_content = "抱歉，剛剛有點失態了。",
  ui_story_5031_50310202_107_dialog_content = "唉，被慾望衝昏頭腦的PlayerName哥哥呀。",
  ui_story_5031_50310202_108_dialog_content = "你們怎麼跑到這裡了，總算找到你們啦！",
  ui_story_5031_50310202_109_dialog_content = "薇絲！和克萊肯談得怎麼樣？",
  ui_story_5031_50310202_110_dialog_content = "失......失敗了，不過我給大家帶了不少免費刨冰！",
  ui_story_5031_50310202_111_dialog_content = "一起狠狠吃光，洗刷這份屈辱吧！嚼嚼嚼。",
  ui_story_5031_50310202_112_dialog_content = "看來薇絲真的很生氣啊......嚼嚼。",
  ui_story_5031_50310202_113_dialog_content = "嗚——頭好疼！",
  ui_story_5031_50310202_114_dialog_content = "妳一口氣吃太多了吧......嗚，我也開始頭疼了。",
  ui_story_5031_50310202_115_dialog_content = "嗯？遠處那個向下的樓梯，該不會就是進入下層船艙的入口吧？",
  ui_story_5031_50310202_116_dialog_content = "欸？讓菲雅看看。",
  ui_story_5031_50310202_117_dialog_content = "好像真的是呢......那要不要......？",
  ui_story_5031_50310202_118_dialog_content = "總感覺擅自進去不太好吧？",
  ui_story_5031_50310202_119_dialog_content = "如果是抓了海雲鯨的壞人，可不會老老實實讓我們進去檢查喔。",
  ui_story_5031_50310202_120_dialog_content = "總之先敲敲門吧。",
  ui_story_5031_50310202_121_dialog_content = "砰～砰～那個，打擾了，我要進來了喔。",
  ui_story_5031_50310202_122_dialog_content = "妳是在用嘴巴「敲門」嗎？",
  ui_story_5031_50310202_123_dialog_content = "<color=#e8d9bb>嘎吱——</color>",
  ui_story_5031_50310202_124_dialog_content = "呀！！",
  ui_story_5031_50310202_125_dialog_content = "誰？",
  ui_story_5031_50310202_126_dialog_content = "我，我們只是路過的一般遊客！",
  ui_story_5031_50310202_127_dialog_content = "莫非諸位已經準備好捨棄一切希望，踏入此門？",
  ui_story_5031_50310202_128_dialog_content = "否則還是速速離去吧。",
  ui_story_5031_50310202_129_dialog_content = "……啊？",
  ui_story_5031_50310202_130_dialog_content = "我說下層區域不對遊客開放！",
  ui_story_5031_50310202_131_dialog_content = "請回吧。",
  ui_story_5031_50310202_132_dialog_content = "啊，抱歉！我們馬上就走。",
  ui_story_5031_50310202_133_dialog_content = "唔唔，果然沒辦法那麼輕易就潛入進去呀。",
  ui_story_5031_50310202_134_dialog_content = "到底怎麼辦呢。",
  ui_story_5031_50310202_135_dialog_content = "<color=#e8d9bb>砰——！</color>",
  ui_story_5031_50310202_136_dialog_content = "「各位船上的來賓，嘉年華的比賽活動已經籌備完成。」",
  ui_story_5031_50310202_137_dialog_content = "「有意參加的來賓，請到指定位置聽從講解，報名參加。」",
  ui_story_5031_50310202_138_dialog_content = "「參賽者不光有機會獲得成為馬戲團一員的體驗活動和高額白夜幣獎金。」",
  ui_story_5031_50310202_139_dialog_content = "「完成重重考驗的第一名還有機會獲得團長親手獻上的豪華大獎。」",
  ui_story_5031_50310202_140_dialog_content = "成為馬戲團一員的話......說不定有機會進入船艙內部？",
  ui_story_5031_50310202_141_dialog_content = "聽起來是個好主意。",
  ui_story_5031_50310202_142_dialog_content = "走，我們過去看看。",
  ui_story_5031_50310202_143_dialog_content = "怎麼會這麼多人啊！",
  ui_story_5031_50310202_144_dialog_content = "嘖，這些庶民怎麼像是蜜蜂一樣都擠過來了。",
  ui_story_5031_50310202_145_dialog_content = "我可是貴族，審判官馬太，庶民都離我遠一點。",
  ui_story_5031_50310202_146_dialog_content = "……",
  ui_story_5031_50310202_147_dialog_content = "吵吵鬧鬧的，一邊去啊！",
  ui_story_5031_50310202_148_dialog_content = "嘖，洛維你這個不肯吭聲的傢伙也讓我覺得煩躁了。",
  ui_story_5031_50310202_149_dialog_content = "卡蓮，那邊好像有兩個白夜城的人呢。",
  ui_story_5031_50310202_150_dialog_content = "好像是審判庭的人......不用管他們。",
  ui_story_5031_50310202_151_dialog_content = "薇絲～卡蓮和PlayerName也在呀，這位小朋友是？",
  ui_story_5031_50310202_152_dialog_content = "貢露長官！啊，這位是......",
  ui_story_5031_50310202_153_dialog_content = "我是神奇動物專家菲雅，請多指教喔！",
  ui_story_5031_50310202_154_dialog_content = "真乖真乖，嗯嗯，空裔可別教壞了小朋友喔。",
  ui_story_5031_50310202_155_dialog_content = "關我什麼事啊！",
  ui_story_5031_50310202_156_dialog_content = "貢露長官怎麼來這裡了？",
  ui_story_5031_50310202_157_dialog_content = "我不光是自己來的喔，還有妳的可愛學妹——",
  ui_story_5031_50310202_158_dialog_content = "琪......琪個，大家好，我是琪爾......之前是薇絲的同學。",
  ui_story_5031_50310202_159_dialog_content = "琪個？",
  ui_story_5031_50310202_160_dialog_content = "好久沒見了呢！好像自從我和PlayerName一起行動就很少見面啦。",
  ui_story_5031_50310202_161_dialog_content = "那個「琪個」是琪爾她的說話習慣，她比較內向，這樣會放鬆一些。",
  ui_story_5031_50310202_162_dialog_content = "別看琪爾害羞的樣子，在學校裡可是被稱為「工程學的天才」喔！",
  ui_story_5031_50310202_163_dialog_content = "原來如此，總感覺厲害的人都會有點奇怪的小地方。",
  ui_story_5031_50310202_164_dialog_content = "那，貢露長官和琪爾小姐也是來玩的嗎？",
  ui_story_5031_50310202_165_dialog_content = "錯了錯了～如果來玩的話肯定要換一身更可愛的衣服呀。",
  ui_story_5031_50310202_166_dialog_content = "空裔還真是遲鈍呀，就連薇絲都沒注意到嗎？",
  ui_story_5031_50310202_167_dialog_content = "這艘艦船這麼巨大......想必其機械結構也非常複雜先進。",
  ui_story_5031_50310202_168_dialog_content = "我可是得知情報的第一時間就拉上琪爾準備過來調查呢。",
  ui_story_5031_50310202_169_dialog_content = "嗯～不過好像沒辦法深入船艙內部呀，只是在外面調查獲取不了多少有用的情報。",
  ui_story_5031_50310202_170_dialog_content = "所以我們現在決定，參加比賽喔！",
  ui_story_5031_50310202_171_dialog_content = "那，薇絲要去幫貢露長官她們嗎？",
  ui_story_5031_50310202_172_dialog_content = "不用了～我可不想拆散巨像小隊，聽說規則已經考慮到不同隊伍人數的情況了。",
  ui_story_5031_50310202_173_dialog_content = "而且琪爾的實力也完全不遜於薇絲喔～",
  ui_story_5031_50310202_174_dialog_content = "我，我會試著努力的......",
  ui_story_5031_50310202_175_dialog_content = "那麼～我們兩個就先去準備啦，一會再見。",
  ui_story_5031_50310202_176_dialog_content = "唔唔，強勁的對手不斷增加了。",
  ui_story_5031_50310202_177_dialog_content = "怎麼還沒開始比賽的解說呀！",
  ui_story_5031_50310202_178_dialog_content = "嗯？好像有兩個人走上台了。",
  ui_story_5031_50310202_179_dialog_content = "是艾維斯領主和剛剛一身黑衣的人？",
  ui_story_5031_50310202_180_dialog_content = "咳，咳咳。",
  ui_story_5031_50310202_181_dialog_content = "歡迎你們，各位親愛的好泊城居民以及遠道而來的賓客們。",
  ui_story_5031_50310202_182_dialog_content = "我是好泊城的領主，艾維斯·摩德利。",
  ui_story_5031_50310202_183_dialog_content = "艾維斯大人！",
  ui_story_5031_50310202_184_dialog_content = "艾維斯·摩德利！艾維斯·摩德利！",
  ui_story_5031_50310202_185_dialog_content = "謝謝大家，很榮幸能在這個盛夏之時邀請到了海上傳奇——",
  ui_story_5031_50310202_186_dialog_content = "享有盛名的魔手·比爾馬戲團，為大家帶來別開生面的嘉年華比賽以及表演。",
  ui_story_5031_50310202_187_dialog_content = "我是魔手·比爾馬戲團的團長，傑諾·蓋拉格，感謝大家光臨馬戲團。",
  ui_story_5031_50310202_188_dialog_content = "為避免舞弊，我們會在每次挑戰之前再公布規則。",
  ui_story_5031_50310202_189_dialog_content = "完成所有挑戰的人，不光有機會參與到馬戲表演，體驗成為一日演員。",
  ui_story_5031_50310202_190_dialog_content = "還有機會得到本人準備的珍貴禮物。",
  ui_story_5031_50310202_191_dialog_content = "人們常常認為，馬戲團裡收藏著許多珍奇怪異的東西。",
  ui_story_5031_50310202_192_dialog_content = "事實上魔手·比爾馬戲團也正是如此。",
  ui_story_5031_50310202_193_dialog_content = "我們在大海上航行，以苦修的方式探求馬戲之奧義，同時從大海獲得啟迪。",
  ui_story_5031_50310202_194_dialog_content = "而大海則會賜予我們無數奇珍異寶——也就是本次嘉年華的至高獎賞。",
  ui_story_5031_50310202_195_dialog_content = "這珍奇的寶物，大家可以盡情想像，盡情期待，它絕不會讓你失望。",
  ui_story_5031_50310202_196_dialog_content = "哦哦哦！聽起來很值錢的樣子。",
  ui_story_5031_50310202_197_dialog_content = "這下發財了！",
  ui_story_5031_50310202_197X1_dialog_content = "大海賜予的......珍奇寶物，菲雅知道了！",
  ui_story_5031_50310202_197X2_dialog_content = "那一定是海雲——唔！",
  ui_story_5031_50310202_197X3_dialog_content = "噓！小聲點，妳是希望牠的真實身分被人知道，然後引來更多對手嗎？",
  ui_story_5031_50310202_197X4_dialog_content = "唔，知道了，那我們就靠實力贏得比賽救出海雲鯨！",
  ui_story_5031_50310202_198_dialog_content = "一個人擔任評委，可能難以服眾。",
  ui_story_5031_50310202_199_dialog_content = "在此我想邀請備受好泊城人民尊敬的領主，艾維斯同時擔任裁判。",
  ui_story_5031_50310202_200_dialog_content = "領主大人！領主大人！",
  ui_story_5031_50310202_201_dialog_content = "這......傑諾，我們之前沒商量過這件事吧？",
  ui_story_5031_50310202_202_dialog_content = "有什麼不好嗎？偶爾放下那些讓人煩惱的政務，你也有享受快樂的權利。",
  ui_story_5031_50310202_203_dialog_content = "領主大人！領主大人！",
  ui_story_5031_50310202_204_dialog_content = "......好，我知道了。",
  ui_story_5031_50310202_205_dialog_content = "大家，縱情享受吧！",
  ui_story_5031_50310301_0_dialog_content = "唔，這條綁帶要從這裡穿過去......",
  ui_story_5031_50310301_0X1_dialog_content = "咦？這，這裡怎麼還有一條綁帶呀！",
  ui_story_5031_50310301_0X2_dialog_content = "這條，呃，是要從另一邊穿過去嗎？",
  ui_story_5031_50310301_0X3_dialog_content = "薇絲，辛苦妳了。",
  ui_story_5031_50310301_0X4_dialog_content = "沒事啦，卡蓮妳再堅持一下喔，我再研究下，馬上就好了。",
  ui_story_5031_50310301_0X5_dialog_content = "嗯，我不著急的，妳慢慢來。",
  ui_story_5031_50310301_0X6_dialog_content = "唔，這裡，是這樣吧！",
  ui_story_5031_50310301_0X7_dialog_content = "嘶，好像也不太對？",
  ui_story_5031_50310301_0X8_dialog_content = "......薇絲。",
  ui_story_5031_50310301_0X9_dialog_content = "嗯？怎麼啦，弄疼妳了嗎？",
  ui_story_5031_50310301_0X10_dialog_content = "沒有，只是......我有一個有些冒昧的問題想問妳。",
  ui_story_5031_50310301_0X11_dialog_content = "欸？冒昧的問題？",
  ui_story_5031_50310301_0X12_dialog_content = "嗯......我想問問妳，覺醒新力量......是種什麼樣的感覺？",
  ui_story_5031_50310301_0X13_dialog_content = "這個呀，這算什麼冒昧的問題嘛～",
  ui_story_5031_50310301_0X14_dialog_content = "妳右邊的胳膊抬起來一下喔。",
  ui_story_5031_50310301_0X15_dialog_content = "啊，好的。",
  ui_story_5031_50310301_0X16_dialog_content = "唔，但是這個問題的確有點難以回答呢。",
  ui_story_5031_50310301_0X17_dialog_content = "不是我不願意回答，而是那種感覺並不是那麼容易描述。",
  ui_story_5031_50310301_0X18_dialog_content = "我理解。",
  ui_story_5031_50310301_0X19_dialog_content = "就我自己的感受來說，我覺得更像是一種潛能被激發出來吧。",
  ui_story_5031_50310301_0X20_dialog_content = "對光能的感受與從前相比會有很大區別，但也伴隨著風險。",
  ui_story_5031_50310301_0X21_dialog_content = "風險？",
  ui_story_5031_50310301_0X22_dialog_content = "嗯，因為在那個過程中，我像是墜入深淵般沉睡，一度以為自己永遠醒不過來了。",
  ui_story_5031_50310301_0X23_dialog_content = "我不斷努力思考和回想曾經時的自己，生怕稍微放鬆就會失去自我。",
  ui_story_5031_50310301_0X24_dialog_content = "我也看到了很多神奇的場景，就像是真的身臨其境一樣。",
  ui_story_5031_50310301_0X25_dialog_content = "那些幻覺就像是真的一樣，就像是對我的考驗。",
  ui_story_5031_50310301_0X26_dialog_content = "幸好，我最後抓住了意識之海中的一縷光芒，堅持到了最後。",
  ui_story_5031_50310301_0X27_dialog_content = "原來如此。一種潛在力量的激發嗎......",
  ui_story_5031_50310301_0X28_dialog_content = "嗯，我是這樣認為的。",
  ui_story_5031_50310301_0X29_dialog_content = "其實也有很多光靈的力量，都是在危急關頭覺醒的。",
  ui_story_5031_50310301_0X30_dialog_content = "我想我的情況也類似吧。",
  ui_story_5031_50310301_0X31_dialog_content = "但是就連現在，我都無法完全熟練掌握它呢。",
  ui_story_5031_50310301_0X32_dialog_content = "畢竟薇絲妳覺醒新力量的時間還不長，假以時日妳一定可以駕馭它的。",
  ui_story_5031_50310301_0X33_dialog_content = "嗯！說得也是呢～",
  ui_story_5031_50310301_0X34_dialog_content = "如果卡蓮也想嘗試一下的話，也許可以先從讓意識下沉試試？",
  ui_story_5031_50310301_0X35_dialog_content = "意識下沉？",
  ui_story_5031_50310301_0X36_dialog_content = "嗯，這是我每次想要使用這種力量的時候都會做的，但不是每次都能成功。",
  ui_story_5031_50310301_0X37_dialog_content = "原來如此，我明白了。",
  ui_story_5031_50310301_0X38_dialog_content = "我之後會試試的，謝謝妳，薇絲。",
  ui_story_5031_50310301_0X39_dialog_content = "沒事！",
  ui_story_5031_50310301_0X40_dialog_content = "好，這樣最後一條綁帶也終於綁對了！",
  ui_story_5031_50310301_0X41_dialog_content = "呼，貴族的衣服穿起來還真是麻煩呢。",
  ui_story_5031_50310301_0X42_dialog_content = "而且這件衣服的材料看起來也很特別，我在啟光的時候從來沒見過。",
  ui_story_5031_50310301_0X43_dialog_content = "我也是第一次見這種材質，也許是好泊城特產的織物吧。",
  ui_story_5031_50310301_0X44_dialog_content = "畢竟各種禮服也是好泊城的特產之一。",
  ui_story_5031_50310301_0X45_dialog_content = "真是辛苦妳了，薇絲。",
  ui_story_5031_50310301_0X46_dialog_content = "沒事沒事，但是卡蓮妳穿著真的很好看喔！",
  ui_story_5031_50310301_0X47_dialog_content = "我們快出去找PlayerName和小菲雅吧，一定會讓他們眼前一亮的！",
  ui_story_5031_50310301_1_dialog_content = "卡蓮怎麼還沒回來......",
  ui_story_5031_50310301_2_dialog_content = "女孩子換衣服就是要很久啦，而且感覺那套禮服穿起來很複雜呢。",
  ui_story_5031_50310301_2X1_dialog_content = "就算有薇絲姐姐的幫助，應該也要穿很久。",
  ui_story_5031_50310301_3_dialog_content = "也是，感覺很多貴族的衣服都要別人幫忙才能穿好吧。",
  ui_story_5031_50310301_4_dialog_content = "菲雅，妳也去幫卡蓮一下吧？",
  ui_story_5031_50310301_5_dialog_content = "哈？你是把菲雅當成你的僕人嗎？指使我做這做那的！",
  ui_story_5031_50310301_6_dialog_content = "現在乖巧一點，卡蓮和薇絲才會更努力地幫你尋找「海雲鯨」喔？",
  ui_story_5031_50310301_7_dialog_content = "好，好吧，菲雅雖然沒幫人穿過衣服，我去試試。",
  ui_story_5031_50310301_8_dialog_content = "PlayerName，你就別逗菲雅啦。",
  ui_story_5031_50310301_9_dialog_content = "抱歉，讓大家久等了......",
  ui_story_5031_50310301_10_dialog_content = "嗚啊啊！卡蓮姐姐這不是超——漂亮的嗎！",
  ui_story_5031_50310301_11_dialog_content = "是吧！看起來是兼顧了舒適性與行動性的禮服呢，非常適合卡蓮呢！",
  ui_story_5031_50310301_12_dialog_content = "謝謝大家，好泊城確實也以有諸多禮服設計、裁縫的能工巧匠而馳名。",
  ui_story_5031_50310301_13_dialog_content = "這身禮服穿著起來也十分舒適。",
  ui_story_5031_50310301_14_dialog_content = "PlayerName你覺得呢？",
  ui_story_5031_50310301_15_dialog_content = "啊，抱歉，剛剛已經完全看呆了。要我說，就是——",
  ui_story_5031_50310301_16_dialog_content = "美麗！優雅！強大！",
  ui_story_5031_50310301_17_dialog_content = "不愧是舒瓦茲大人之女，卡蓮殿下這幅優雅的身姿簡直讓人感動得落淚。",
  ui_story_5031_50310301_18_dialog_content = "不......也太誇張了吧，不過還是謝謝你，艾維斯閣下。",
  ui_story_5031_50310301_19_dialog_content = "千萬別客氣，看到您這幅身姿就讓我想起舒瓦茲家族的正義與不屈的高貴品質。",
  ui_story_5031_50310301_20_dialog_content = "希望這件禮服能給您帶來好運，讓您在比賽中贏得優勝。",
  ui_story_5031_50310301_21_dialog_content = "在下還有主持的工作，我們晚些再見！",
  ui_story_5031_50310301_22_dialog_content = "啊，抱歉，還沒認真地評價一下卡蓮的新禮服。",
  ui_story_5031_50310301_23_dialog_content = "可惡，都被艾維斯領主說完了啊。",
  ui_story_5031_50310301_24_dialog_content = "嗯，不過其實不說出來也沒關係。",
  ui_story_5031_50310301_25_dialog_content = "我已經從你剛剛的眼神裡讀出想法了。",
  ui_story_5031_50310301_26_dialog_content = "欸？？",
  ui_story_5031_50310301_27_dialog_content = "大家好～又到了虹霞的講解時間囉。",
  ui_story_5031_50310301_28_dialog_content = "我是馬戲團的主持人兼職迎賓員兼職保全人員主職實習輪機師虹霞～",
  ui_story_5031_50310301_29_dialog_content = "這次由我擔任嘉年華的主持人～",
  ui_story_5031_50310301_30_dialog_content = "第一場比賽大家需要先從這裡領取虹霞特製的水槍。",
  ui_story_5031_50310301_31_dialog_content = "這種水槍可以十分方便地將光能轉化為水槍彈藥來發射。",
  ui_story_5031_50310301_32_dialog_content = "規則也十分簡單，只要用水槍攻擊到傑諾團長指定的目標就可以加分。",
  ui_story_5031_50310301_33_dialog_content = "但比賽中並不會限制不同選手或者不同隊伍之間的互相攻擊～",
  ui_story_5031_50310301_34_dialog_content = "最終分數最高的五個隊伍才能進入下一場比賽，淘汰的隊伍會被直接丟進海裡。",
  ui_story_5031_50310301_35_dialog_content = "所以不會游泳的來賓請不要參加喔～至少也要套個游泳圈再參加。",
  ui_story_5031_50310301_36_dialog_content = "本輪比賽對參賽隊伍的人數不做限制，會在最後以隊伍個人平均分數為最終分數。",
  ui_story_5031_50310301_37_dialog_content = "大姐，這規則看起來對我們很有利啊。",
  ui_story_5031_50310301_38_dialog_content = "憑約娜大姐頭和青瞳姐的本事，第一名我們十拿九穩了！",
  ui_story_5031_50310301_39_dialog_content = "水槍？雖然有點小兒科，看在真金白銀獎品的份上就湊湊熱鬧吧。",
  ui_story_5031_50310301_40_dialog_content = "反正也是閑著，找點樂子也沒什麼不好～",
  ui_story_5031_50310301_41_dialog_content = "嘿嘿，這下一定賺大啦！",
  ui_story_5031_50310301_42_dialog_content = "別高興那麼早，你們兩個小子才剛加入我們紅油扳手。",
  ui_story_5031_50310301_43_dialog_content = "好好記住我們的規矩！不要在外面給紅油扳手丟人。",
  ui_story_5031_50310301_44_dialog_content = "您放心您放心，我們兄弟都記著呢！",
  ui_story_5031_50310301_45_dialog_content = "就是那個什麼和那個什麼，都記清楚了！",
  ui_story_5031_50310301_46_dialog_content = "大家都明白規則了嗎～？",
  ui_story_5031_50310301_47_dialog_content = "明白啦～",
  ui_story_5031_50310301_48_dialog_content = "等等！如果這種水槍是用光能的話，我豈不是等於任人宰割嘛。",
  ui_story_5031_50310301_49_dialog_content = "嗯，倒是沒有考慮到空裔這一點呢。",
  ui_story_5031_50310301_50_dialog_content = "梅爾姐～那妳要去空裔的隊伍裡幫忙嗎？",
  ui_story_5031_50310301_51_dialog_content = "怎，怎麼可以！我們不能參加這場比賽啦......",
  ui_story_5031_50310301_52_dialog_content = "哎～人家真是不懂，那種豆芽菜有什麼好的嘛，至少也要身體結實一些才好。",
  ui_story_5031_50310301_53_dialog_content = "老闆～空裔要怎麼辦？",
  ui_story_5031_50310301_54_dialog_content = "就按老弱優待處理，和那個小姑娘算一個人。",
  ui_story_5031_50310301_55_dialog_content = "欸！人家為什麼和笨蛋空裔加起來算一個人啦。",
  ui_story_5031_50310301_56_dialog_content = "那按兩個人算。",
  ui_story_5031_50310301_57_dialog_content = "唔，其，其實菲雅啊，年紀和力氣都很小，應該只能算半個名額呢！",
  ui_story_5031_50310301_58_dialog_content = "既然都沒異議了，那接下來我要請出計分目標——",
  ui_story_5031_50310301_59_dialog_content = "來吧！大家！向這瘋狂獻上掌聲與獻禮吧！",
  ui_story_5031_50310301_60_dialog_content = "來啊！呼嚎吧！地獄的野獸們！",
  ui_story_5031_50310301_61_dialog_content = "等等！老大該不會想叫出那些......",
  ui_story_5031_50310301_62_dialog_content = "快，快蒙住虹霞姐的眼睛！她看到暗鬼又會失控的！",
  ui_story_5031_50310301_63_dialog_content = "嘎——！",
  ui_story_5031_50310301_64_dialog_content = "暗鬼！？",
  ui_story_5031_50310301_65_dialog_content = "暗鬼！！",
  ui_story_5031_50310301_66_dialog_content = "菲爾姆！快來幫忙按住虹霞姐，要控制不住啦！",
  ui_story_5031_50310301_67_dialog_content = "笨蛋老大！為什麼要叫出暗鬼啊？",
  ui_story_5031_50310301_68_dialog_content = "呵......因為和今天的風很配啊。",
  ui_story_5031_50310301_69_dialog_content = "PlayerName和菲雅，到我和薇絲身後來。",
  ui_story_5031_50310301_70_dialog_content = "大家無須擔心，這些暗鬼不過是我利用「<color=#FFB400>起源</color>」創造出的一種幻象。",
  ui_story_5031_50310301_71_dialog_content = "我利用自己這雙手掌握的能力，在與暗鬼的戰鬥中解析了牠們的「起源」。",
  ui_story_5031_50310301_72_dialog_content = "再藉由「<color=#FFB400>起源之牌</color>」的力量，創造出了如此活靈活現的幻象。",
  ui_story_5031_50310301_73_dialog_content = "嘎——",
  ui_story_5031_50310301_74_dialog_content = "嘎——",
  ui_story_5031_50310301_75_dialog_content = "正如大家所見，牠們都在我的操縱之下，但作為射擊目標再好不過。",
  ui_story_5031_50310301_76_dialog_content = "那麼我宣布，比賽開始！",
  ui_story_5031_50310401_1_dialog_content = "喂喂，你們幾個不許偷懶，給我繼續散開搜尋暗鬼，這次的第一名非我們紅油扳手莫屬。",
  ui_story_5031_50310401_2_dialog_content = "明白！約娜老大！那要是遇到光靈怎麼辦？",
  ui_story_5031_50310401_3_dialog_content = "怎麼辦？我們可是紅油扳手！",
  ui_story_5031_50310401_4_dialog_content = "不要做出有辱紅油扳手之名的事，全都給我射到船下面去！",
  ui_story_5031_50310401_5_dialog_content = "明白。",
  ui_story_5031_50310401_6_dialog_content = "可真是亂來呀，約娜。",
  ui_story_5031_50310401_7_dialog_content = "怎麼了？有哪個小帥哥讓妳捨不得下手嗎？",
  ui_story_5031_50310401_8_dialog_content = "嗯～雖然小帥哥很可愛，但是比起那個很誘人的大獎嘛......",
  ui_story_5031_50310401_9_dialog_content = "可惡，怎麼擅長使用槍械的約娜和青瞳都在。",
  ui_story_5031_50310401_10_dialog_content = "明明只要射擊暗鬼獲得積分就好了，這些紅油扳手的傢伙反而一直瞄準其他人！",
  ui_story_5031_50310401_11_dialog_content = "如果不是傑諾製造的這些作為掩體的幻象，我們恐怕早就被逼下船了。",
  ui_story_5031_50310401_12_dialog_content = "不過繼續這樣被動還是會被包圍的......我來帶著大家殺出一條路！",
  ui_story_5031_50310401_13_dialog_content = "等一下！卡蓮！",
  ui_story_5031_50310401_14_dialog_content = "你們這些不遵守規則的法外之徒，冰花，不對......「冰槍綻放」！",
  ui_story_5031_50310401_15_dialog_content = "唔！",
  ui_story_5031_50310401_16_dialog_content = "老，老大！",
  ui_story_5031_50310401_17_dialog_content = "這樣就解決兩個了，大家快過來。",
  ui_story_5031_50310401_18_dialog_content = "好強......直接被卡蓮的「冰槍綻放」射進海裡了，啊！卡蓮，快躲進掩體。",
  ui_story_5031_50310401_19_dialog_content = "PlayerName，現在是衝出去的最好時機！",
  ui_story_5031_50310401_20_dialog_content = "卡蓮，妳太孤軍深入了，這樣會——",
  ui_story_5031_50310401_21_dialog_content = "抓到妳了，白夜城的小公主。",
  ui_story_5031_50310401_22_dialog_content = "<color=#e8d9bb>砰——</color>",
  ui_story_5031_50310401_23_dialog_content = "——！！",
  ui_story_5031_50310401_24_dialog_content = "卡蓮！",
  ui_story_5031_50310401_25_dialog_content = "抱，抱歉，PlayerName。",
  ui_story_5031_50310401_26_dialog_content = "卡蓮妳沒事就好，沒想到約娜即使用光能水槍也這麼難纏。",
  ui_story_5031_50310401_27_dialog_content = "嗚！你們這些討厭的紅油壞蛋，不要再纏著我們不放啦！",
  ui_story_5031_50310401_28_dialog_content = "不行，我們得想想辦法才能突破僵局。",
  ui_story_5031_50310401_29_dialog_content = "比賽進行得很激烈呢。",
  ui_story_5031_50310401_30_dialog_content = "是啊，不過沒想到你居然會使用這種力量。",
  ui_story_5031_50310401_31_dialog_content = "這是我從真理結社獲得的力量......",
  ui_story_5031_50310401_32_dialog_content = "啊，你作為白夜城的貴族，應該聽到過他們很多負面傳聞吧。",
  ui_story_5031_50310401_33_dialog_content = "其實「起源」只是我為了製造出懸念感便於表演而創造出的名詞。",
  ui_story_5031_50310401_34_dialog_content = "其實只是我擁有的將能量進行轉化的力量......時間長這樣叫也就習慣了。",
  ui_story_5031_50310401_35_dialog_content = "我對他們並沒有什麼特別的看法，這點你可以放心。",
  ui_story_5031_50310401_36_dialog_content = "不過為什麼是暗鬼？",
  ui_story_5031_50310401_37_dialog_content = "大家來參加嘉年華，觀看馬戲，當然是為了追求驚險刺激。",
  ui_story_5031_50310401_38_dialog_content = "所以暗鬼不是理所當然嗎？",
  ui_story_5031_50310401_39_dialog_content = "很商業化的思考，你變得深思熟慮了。",
  ui_story_5031_50310401_40_dialog_content = "哪裡，我好歹也是領導著整個馬戲團的人。",
  ui_story_5031_50310401_41_dialog_content = "打擾了，艾維斯大人。",
  ui_story_5031_50310401_42_dialog_content = "帕托......我先失陪了，傑諾。",
  ui_story_5031_50310401_43_dialog_content = "有何發現？",
  ui_story_5031_50310401_44_dialog_content = "報告，據調查，已經找到了符合您之前描述的房間。",
  ui_story_5031_50310401_45_dialog_content = "什麼！太好了......",
  ui_story_5031_50310401_46_dialog_content = "不過，那個房間被從沒見過的門鎖保護著，強行突破的話可能會觸發警報。",
  ui_story_5031_50310401_47_dialog_content = "我知道了，那就先試著尋找能解開門鎖的鑰匙。",
  ui_story_5031_50310401_48_dialog_content = "我想鑰匙很有可能在傑諾的房間裡或是隨身攜帶，我們可以分頭行動。",
  ui_story_5031_50310401_49_dialog_content = "艾維斯！",
  ui_story_5031_50310401_50_dialog_content = "沒打擾你吧，不過有隊伍又得了一分，觀眾們都高聲呼喊著要他們的領主大人加分呢。",
  ui_story_5031_50310401_51_dialog_content = "領主大人！領主大人——！",
  ui_story_5031_50310401_52_dialog_content = "抱歉，傑諾，我再囑咐帕托一句就回來。",
  ui_story_5031_50310401_53_dialog_content = "怎麼辦，艾維斯大人。",
  ui_story_5031_50310401_54_dialog_content = "船艙內房間的搜尋就交給你的手下了。",
  ui_story_5031_50310401_55_dialog_content = "這種情況下，如果我長期離開，肯定會引起傑諾懷疑。",
  ui_story_5031_50310401_56_dialog_content = "而且有些參加比賽的光靈似乎目的並不簡單，他們也有可能是衝著我們的目標而來。",
  ui_story_5031_50310401_57_dialog_content = "所以現在也需要人監視他們，即使想要動手也要等夜深人靜，這些人下船之後。",
  ui_story_5031_50310401_58_dialog_content = "大人所言極是，那麼我就讓兄弟們繼續潛伏搜尋，隨時等待大人的命令。",
  ui_story_5031_50310401_59_dialog_content = "領主大人！領主大人！",
  ui_story_5031_50310401_60_dialog_content = "久等了！各位！我宣布紅油扳手隊再加一分！",
  ui_story_5031_50310401_61_dialog_content = "終於回來了，可讓我和觀眾們等了好久。",
  ui_story_5031_50310401_62_dialog_content = "抱歉，傑諾，讓你久等了。",
  ui_story_5031_50310402_1_dialog_content = "鑰匙嗎......該怎麼樣才能知道他放在哪裡了呢......",
  ui_story_5031_50310402_2_dialog_content = "艾維斯，你沒事吧？",
  ui_story_5031_50310402_3_dialog_content = "從剛剛你的侍衛走後你的臉色就不太好看。",
  ui_story_5031_50310402_4_dialog_content = "是身體不舒服嗎？",
  ui_story_5031_50310402_5_dialog_content = "啊，我沒事。",
  ui_story_5031_50310402_6_dialog_content = "只是在想一些政事而已，讓你擔心了。",
  ui_story_5031_50310402_7_dialog_content = "......我突然讓你一起擔任裁判，是不是耽誤你的工作了？",
  ui_story_5031_50310402_8_dialog_content = "抱歉，我只是想著或許這樣你可以和大家一起享受節日。",
  ui_story_5031_50310402_9_dialog_content = "哦？第一次見老大道歉呢！",
  ui_story_5031_50310402_10_dialog_content = "是呢，老大竟然也會正常說話不惹人生氣呀～",
  ui_story_5031_50310402_11_dialog_content = "妳們三個太閑的話，就去給虹霞幫忙。",
  ui_story_5031_50310402_12_dialog_content = "略略略～",
  ui_story_5031_50310402_13_dialog_content = "真是的，一天到晚就知道調皮搗蛋。",
  ui_story_5031_50310402_14_dialog_content = "呵，不用擔心我，我只是......",
  ui_story_5031_50310402_15_dialog_content = "有一些煩心事，還在權衡思考，沒有決定。",
  ui_story_5031_50310402_16_dialog_content = "正好借此機會休息一下，也能看清一些事情、一些人，會對我有所幫助。",
  ui_story_5031_50310402_17_dialog_content = "那就好，如果身體有什麼不舒服一定要跟我說。",
  ui_story_5031_50310402_18_dialog_content = "嗯，我知道。",
  ui_story_5031_50310402_19_dialog_content = "「敬告各位參賽的玩家，為了讓比賽更加激烈，馬上會加倍投放暗鬼。」",
  ui_story_5031_50310402_20_dialog_content = "終於等到了～！這就是所謂的獎勵時間！",
  ui_story_5031_50310402_21_dialog_content = "琪爾，好好掩護我，在獎勵時間裡奮力一搏可是拿高分的奧義呀！",
  ui_story_5031_50310402_22_dialog_content = "好，好的！貢露長官。",
  ui_story_5031_50310402_23_dialog_content = "啊，長官您跑得太快了——",
  ui_story_5031_50310402_24_dialog_content = "唷吼，看看這是誰呀。",
  ui_story_5031_50310402_25_dialog_content = "這不是落單的啟光小妹妹嗎？",
  ui_story_5031_50310402_26_dialog_content = "你，你們想幹嘛！",
  ui_story_5031_50310402_27_dialog_content = "我們當然是想包攬所有獎項，然後拿獎品去賣錢瀟灑一番啦。",
  ui_story_5031_50310402_28_dialog_content = "委屈妳了啊，小妹妹，妳的水槍我拿走了，妳也乖乖被我們丟下海去吧！",
  ui_story_5031_50310402_29_dialog_content = "等等，這小姑娘身上這套行頭看著挺不錯啊，拆下來賣到影鎮去應該能換不少錢吧。",
  ui_story_5031_50310402_30_dialog_content = "對，對！咱們紅油扳手從不走空，小妹妹我勸妳識相點。",
  ui_story_5031_50310402_31_dialog_content = "把身上值錢的東西都交出來！",
  ui_story_5031_50310402_32_dialog_content = "別，別碰我！",
  ui_story_5031_50310402_33_dialog_content = "你們住手——！",
  ui_story_5031_50310402_34_dialog_content = "誰啊？妳不是剛剛的主持人嗎？",
  ui_story_5031_50310402_35_dialog_content = "沒錯！兩位請停止你們的搶劫和違規行為，否則我要不客氣了！",
  ui_story_5031_50310402_36_dialog_content = "說什麼大話，妳以為妳是主持人我們就會怕妳嗎！",
  ui_story_5031_50310402_37_dialog_content = "仗勢欺人的行為，虹霞是不會允許的！",
  ui_story_5031_50310402_38_dialog_content = "<color=#e8d9bb>砰——！</color>",
  ui_story_5031_50310402_39_dialog_content = "大，大哥！",
  ui_story_5031_50310402_40_dialog_content = "你也是！",
  ui_story_5031_50310402_41_dialog_content = "<color=#e8d9bb>砰——！</color>",
  ui_story_5031_50310402_42_dialog_content = "嗚啊——！",
  ui_story_5031_50310402_43_dialog_content = "好，好厲害......直接就打飛出去了。",
  ui_story_5031_50310402_44_dialog_content = "妳沒受傷吧，這群傢伙也太過分了。居然趁著比賽做打劫的事！",
  ui_story_5031_50310402_45_dialog_content = "啊，我，我必須得去幫貢露前輩了，謝謝妳！",
  ui_story_5031_50310402_46_dialog_content = "水槍......水槍不見了。",
  ui_story_5031_50310402_47_dialog_content = "唉，真是沒辦法呢，這把水槍給妳。",
  ui_story_5031_50310402_48_dialog_content = "規則裡寫了「丟失水槍的人找到主持人就能領取新水槍」，妳就安心拿著吧。",
  ui_story_5031_50310402_49_dialog_content = "好，好的！謝謝妳。",
  ui_story_5031_50310402_50_dialog_content = "那個......",
  ui_story_5031_50310402_51_dialog_content = "嗯？",
  ui_story_5031_50310402_52_dialog_content = "我叫琪爾，謝謝妳，虹霞小姐。",
  ui_story_5031_50310402_53_dialog_content = "琪爾是嗎？我記住妳的名字了。",
  ui_story_5031_50310402_54_dialog_content = "嘖，真是的，為什麼卡蓮殿下要參加這種有一大群庶民的遊戲啊。",
  ui_story_5031_50310402_55_dialog_content = "這可真是讓貴族十分......十分難堪！",
  ui_story_5031_50310402_56_dialog_content = "……",
  ui_story_5031_50310402_57_dialog_content = "喂，你能不能也說兩句話啊！",
  ui_story_5031_50310402_58_dialog_content = "監視，保護卡蓮。",
  ui_story_5031_50310402_59_dialog_content = "嘖，等於沒說。",
  ui_story_5031_50310402_60_dialog_content = "快來快來！這邊有好多暗鬼可以射擊！",
  ui_story_5031_50310402_61_dialog_content = "啊！",
  ui_story_5031_50310402_62_dialog_content = "<color=#e8d9bb>咚！</color>",
  ui_story_5031_50310402_63_dialog_content = "抱，抱歉，這位大人，不小心撞掉您的水槍了。",
  ui_story_5031_50310402_64_dialog_content = "我幫您撿起來。",
  ui_story_5031_50310402_65_dialog_content = "沒事沒事，不必在意，你的朋友還在那邊等你，祝你玩得開心。",
  ui_story_5031_50310402_66_dialog_content = "謝謝，您真是一位溫柔的貴族。",
  ui_story_5031_50310402_67_dialog_content = "……",
  ui_story_5031_50310402_68_dialog_content = "............好噁心。",
  ui_story_5031_50310402_69_dialog_content = "水！給我拿水！我要洗手！！",
  ui_story_5031_50310402_70_dialog_content = "......麻煩。",
  ui_story_5031_50310402_71_dialog_content = "嘎——！",
  ui_story_5031_50310402_72_dialog_content = "PlayerName，暗鬼的數量增加了很多。",
  ui_story_5031_50310402_73_dialog_content = "但是那群紅油扳手的傢伙還死死盯著我們不放。",
  ui_story_5031_50310402_74_dialog_content = "他們就不怕積分不夠被淘汰嗎！",
  ui_story_5031_50310402_75_dialog_content = "恐怕在他們眼裡，我們就是奪冠的強敵。",
  ui_story_5031_50310402_76_dialog_content = "所以想直接在這場比賽裡把我們淘汰出局。",
  ui_story_5031_50310402_77_dialog_content = "我想到了個辦法......不如就放手一搏，由我這個沒有光能力量的人來當誘餌。",
  ui_story_5031_50310402_78_dialog_content = "儘量把更多暗鬼引過來，然後大家趁機逃出約娜和青瞳她們設下的包圍圈。",
  ui_story_5031_50310402_79_dialog_content = "PlayerName，這樣太亂來了！我可以再嘗試突破出去，這次我會更小心的！",
  ui_story_5031_50310402_80_dialog_content = "卡蓮，約娜和青瞳她們都是用槍的好手，在很遠的距離就能精準射中我們。",
  ui_story_5031_50310402_81_dialog_content = "我不會那麼輕易就倒下的，你要相信我的力量。",
  ui_story_5031_50310402_82_dialog_content = "我當然相信卡蓮的力量，但是這個時候也需要卡蓮相信我的力量。",
  ui_story_5031_50310402_83_dialog_content = "卡蓮，我認為PlayerName的提議可以試試看呢。",
  ui_story_5031_50310402_84_dialog_content = "也許在這個情況下，已經算是最好的戰術了。",
  ui_story_5031_50310402_85_dialog_content = "我知道了，那你多小心。",
  ui_story_5031_50310402_86_dialog_content = "放心吧，菲雅，妳就跟著卡蓮和薇絲一起行動。",
  ui_story_5031_50310402_87_dialog_content = "欸，欸？菲雅知道了。",
  ui_story_5031_50310402_88_dialog_content = "暗鬼們！你們的移動餐車來了！",
  ui_story_5031_50310402_89_dialog_content = "五百光珀吃到飽套餐再不來就沒有了啊啊啊啊——",
  ui_story_5031_50310402_90_dialog_content = "嘎——！",
  ui_story_5031_50310402_91_dialog_content = "嘎嘎——！",
  ui_story_5031_50310402_92_dialog_content = "哦？PlayerName突然跳出來了，他想幹嘛？",
  ui_story_5031_50310402_93_dialog_content = "不愧是小空裔～他是想用自己做誘餌，讓暗鬼阻擋我們的視線吧。",
  ui_story_5031_50310402_94_dialog_content = "不過這種程度可不行喔，作為輕視我的小小懲罰，就對著他的屁股來上一槍吧——",
  ui_story_5031_50310402_95_dialog_content = "兩位小姐。",
  ui_story_5031_50310402_96_dialog_content = "嗯？",
  ui_story_5031_50310402_97_dialog_content = "我可不能允許，你們這樣肆意攻擊卡蓮殿下他們啊——",
  ui_story_5031_50310402_98_dialog_content = "剛剛手被弄髒的怒火......就釋放在你們這些不知天高地厚想對貴族下手的傢伙們身上吧！！",
  ui_story_5031_50310402_99_dialog_content = "薇絲，菲雅，跟在我身後！",
  ui_story_5031_50310402_100_dialog_content = "區區暗鬼，我一個人就全部能解決掉！",
  ui_story_5031_50310402_101_dialog_content = "<color=#e8d9bb>砰砰——！</color>",
  ui_story_5031_50310402_102_dialog_content = "嘎——",
  ui_story_5031_50310402_103_dialog_content = "嘎——！！",
  ui_story_5031_50310402_104_dialog_content = "嘎——！",
  ui_story_5031_50310402_105_dialog_content = "嘎——！",
  ui_story_5031_50310402_106_dialog_content = "明明都是很弱的暗鬼，奈何數量太多，我們被包圍了。",
  ui_story_5031_50310402_107_dialog_content = "卡蓮，不要戀戰了，我們先去和PlayerName匯合。",
  ui_story_5031_50310402_108_dialog_content = "如果規則允許帶月之繭的話......你們這些暗鬼！",
  ui_story_5031_50310402_108X1_dialog_content = "如果我也擁有薇絲那種全新的力量的話......！",
  ui_story_5031_50310402_108X2_dialog_content = "冷靜下來，卡蓮。",
  ui_story_5031_50310402_108X3_dialog_content = "像薇絲說的那樣，讓意識下沉。",
  ui_story_5031_50310402_108X4_dialog_content = "感受......呼吸。",
  ui_story_5031_50310402_108X5_dialog_content = "卡蓮。",
  ui_story_5031_50310402_108X6_dialog_content = "父親......",
  ui_story_5031_50310402_108X7_dialog_content = "妳我都知道暗鬼是殺不完的。",
  ui_story_5031_50310402_108X8_dialog_content = "魯莽的行為，只會葬送信賴妳的士兵。",
  ui_story_5031_50310402_108X9_dialog_content = "而不夠強大的力量，也無法保護任何珍視的人。",
  ui_story_5031_50310402_108X10_dialog_content = "妳還不夠......還要去尋找......變得更強。",
  ui_story_5031_50310402_108X11_dialog_content = "我很失望......",
  ui_story_5031_50310402_108X12_dialog_content = "不......不是這樣的，父親！",
  ui_story_5031_50310402_108X13_dialog_content = "卡蓮！",
  ui_story_5031_50310402_108X14_dialog_content = "嘎——！",
  ui_story_5031_50310402_108X15_dialog_content = "滾開！！",
  ui_story_5031_50310402_109_dialog_content = "<color=#e8d9bb>咚！</color>",
  ui_story_5031_50310402_110_dialog_content = "怎，怎麼用拳頭打暗鬼啊，那樣不算分數的。",
  ui_story_5031_50310402_111_dialog_content = "卡蓮，冷靜點！我們得去找PlayerName了！",
  ui_story_5031_50310402_112_dialog_content = "......抱歉，妳說得對。",
  ui_story_5031_50310402_113_dialog_content = "<color=#e8d9bb>鈴鈴——</color>",
  ui_story_5031_50310402_114_dialog_content = "「比賽結束，請各位還在場內的參賽者回到裁判台查看成績。」",
  ui_story_5031_50310402_115_dialog_content = "太好了卡蓮，我們成功晉級了！",
  ui_story_5031_50310402_116_dialog_content = "嗯，多虧了PlayerName幫我們逃出了紅油扳手的包圍呢。",
  ui_story_5031_50310402_117_dialog_content = "不過還是太危險了，如果是實戰，絕對不要用這種危險的戰術。",
  ui_story_5031_50310402_118_dialog_content = "哎，空裔小弟還以為是自己救了大家呢。",
  ui_story_5031_50310402_119_dialog_content = "欸？青瞳？妳什麼意思？",
  ui_story_5031_50310402_120_dialog_content = "是突然出現的一個白夜城的傢伙找我們打架，我們兩個被他纏上了。",
  ui_story_5031_50310402_121_dialog_content = "不然你的屁股早就被青瞳打開花了。",
  ui_story_5031_50310402_122_dialog_content = "果然比起玩水槍這種家家酒的玩意，還是和白夜城的人真刀真槍來一場過癮啊。",
  ui_story_5031_50310402_123_dialog_content = "一邊喊著一邊衝過來的樣子完全不像是貴族啊，打著打著就完全忘記比賽的事了。",
  ui_story_5031_50310402_124_dialog_content = "可惜他被身邊那個不吭聲的人拖走了，不然現在還打得難解難分吧。",
  ui_story_5031_50310402_125_dialog_content = "大，大姐頭......",
  ui_story_5031_50310402_126_dialog_content = "嗯？你還有臉回來？",
  ui_story_5031_50310402_127_dialog_content = "你忘了我們紅油扳手不對女人和小孩下手嗎？",
  ui_story_5031_50310402_128_dialog_content = "對，對不起大姐頭，我一時鬼迷心竅。",
  ui_story_5031_50310402_129_dialog_content = "給我滾去船下做伏地挺身，做到我喝完酒去收拾你。",
  ui_story_5031_50310402_130_dialog_content = "是，是的！約娜大姐頭！",
  ui_story_5031_50310402_131_dialog_content = "真掃興......",
  ui_story_5031_50310402_132_dialog_content = "想不到你們紅油扳手還有這樣一面。",
  ui_story_5031_50310402_133_dialog_content = "我就當你是在誇我囉，大小姐，我要和青瞳喝酒去了，幾位回見。",
  ui_story_5031_50310402_134_dialog_content = "拜拜～我們要去那邊暢飲免費酒水了，空裔小弟一會要記得來找姐姐喔～",
  ui_story_5031_50310402_135_dialog_content = "哈——不管怎麼說，專門盯著咱們的對手少了一個。",
  ui_story_5031_50310402_136_dialog_content = "貢露她們好像也順利晉級了，分數還很高呢。",
  ui_story_5031_50310402_137_dialog_content = "想不到比賽這麼激烈，約娜和青瞳那麼強都在第一輪被淘汰了。",
  ui_story_5031_50310402_138_dialog_content = "接下來的比賽......一定是十分激烈的、悲慘的、針鋒相對的......",
  ui_story_5031_50310402_139_dialog_content = "咕嚕。",
  ui_story_5031_50310402_140_dialog_content = "妳咽口水的聲音也太大了吧！",
  ui_story_5031_50310402_141_dialog_content = "嗚，菲雅只是想配合一下你營造的緊張氣氛呀！",
  ui_story_5031_50310402_142_dialog_content = "領主大人～你好呀。",
  ui_story_5031_50310402_143_dialog_content = "妳好，妳是剛剛的......",
  ui_story_5031_50310402_144_dialog_content = "是的，我叫薩布莉。",
  ui_story_5031_50310402_145_dialog_content = "傑諾老大讓我來送這個～",
  ui_story_5031_50310402_146_dialog_content = "這是？",
  ui_story_5031_50310402_147_dialog_content = "是毯子啦，傑諾老大怕你吹太久海風會著涼。",
  ui_story_5031_50310402_148_dialog_content = "......我知道了，替我謝謝他吧。",
  ui_story_5031_50310402_149_dialog_content = "也謝謝妳，薩布莉。",
  ui_story_5031_50310402_150_dialog_content = "嘻嘻，沒事～",
  ui_story_5031_50310402_151_dialog_content = "……",
  ui_story_5031_50310501_1_dialog_content = "恭喜，各位完成了第一場比賽的勇士們。",
  ui_story_5031_50310501_2_dialog_content = "毫無疑問，你們已經證明了自己的勇氣與力量，來到了這祕寶之門外。",
  ui_story_5031_50310501_3_dialog_content = "第二場比賽的遊戲規則也非常簡單。",
  ui_story_5031_50310501_4_dialog_content = "想必大家在小的時候，都玩過這樣的遊戲。",
  ui_story_5031_50310501_5_dialog_content = "出來吧，在無盡的黃昏色中舞動的醜惡怪獸，祕法與祕寶的守護者啊——",
  ui_story_5031_50310501_6_dialog_content = "<color=#e8d9bb>咚——</color>",
  ui_story_5031_50310501_7_dialog_content = "這位，就是我們本次比賽的守祕人。",
  ui_story_5031_50310501_8_dialog_content = "咳咳～那麼接下來由虹霞繼續為大家解說規則～",
  ui_story_5031_50310501_9_dialog_content = "當這隻特殊暗鬼呈現綠色姿態時。",
  ui_story_5031_50310501_10_dialog_content = "大家要以最快的速度突破路上層層阻礙的暗鬼，衝到牠身邊～",
  ui_story_5031_50310501_11_dialog_content = "只要到達牠身邊這條線～就代表成功晉級。",
  ui_story_5031_50310501_12_dialog_content = "而當牠變成紅色姿態時，請大家小心～",
  ui_story_5031_50310501_13_dialog_content = "這是任何光靈與暗鬼都不能活動，違反者會被最近的暗鬼直接丟下船，失去晉級資格。",
  ui_story_5031_50310501_14_dialog_content = "未在限制時間內到達終點的人，也會被淘汰。",
  ui_story_5031_50310501_15_dialog_content = "這場比賽不會對可以使用的光能術做任何限制。",
  ui_story_5031_50310501_16_dialog_content = "正是如此！來啊！拿出你們全部的實力，向著祕寶發起挑戰吧！",
  ui_story_5031_50310501_17_dialog_content = "PlayerName。",
  ui_story_5031_50310501_18_dialog_content = "嗯，這次終於又到我能發揮實力的時候了。",
  ui_story_5031_50310501_19_dialog_content = "放心吧，我會協助大家第一個衝到終點！",
  ui_story_5031_50310502_1_dialog_content = "哈哈！這種程度的暗鬼，就連我也能輕鬆搞定啊！",
  ui_story_5031_50310502_2_dialog_content = "看招看招，你們這群蠢暗鬼！",
  ui_story_5031_50310502_3_dialog_content = "喂！那隻大號暗鬼馬上就要變色了，別打了！",
  ui_story_5031_50310502_4_dialog_content = "還有時間呢！我們再往前衝一點就能領先啦！",
  ui_story_5031_50310502_5_dialog_content = "一群蠢貨，明明馬上就要被淘汰了還不自知。",
  ui_story_5031_50310502_6_dialog_content = "上一場多虧你了啊，沒想到你還會趁我收拾那兩個匪徒的時候去賺積分。",
  ui_story_5031_50310502_7_dialog_content = "沒想到兩個區區匪徒還這麼難纏，讓我好好活動了一番。",
  ui_story_5031_50310502_8_dialog_content = "如果最後你沒拽我走的話，我肯定能收拾了她們兩個......",
  ui_story_5031_50310502_9_dialog_content = "……",
  ui_story_5031_50310502_10_dialog_content = "嘖，誇你也不吭聲，你的光能術是把自己的嘴巴黏在一起嗎？",
  ui_story_5031_50310502_11_dialog_content = "<color=#e8d9bb>鈴鈴——</color>",
  ui_story_5031_50310502_12_dialog_content = "牠變色了！",
  ui_story_5031_50310502_13_dialog_content = "嘎——！",
  ui_story_5031_50310502_14_dialog_content = "別，別過來啊！",
  ui_story_5031_50310502_15_dialog_content = "<color=#e8d9bb>噗通！</color>",
  ui_story_5031_50310502_16_dialog_content = "<color=#e8d9bb>噗通！！</color>",
  ui_story_5031_50310502_17_dialog_content = "果然被丟下去了，一群愚蠢的庶民啊......",
  ui_story_5031_50310502_18_dialog_content = "我們別離公主殿下太遠，靠近一點保護她。",
  ui_story_5031_50310502_19_dialog_content = "絕對不能讓她像剛剛那個可悲的庶民一樣被丟下去。",
  ui_story_5031_50310502_20_dialog_content = "謝謝你的毯子，傑諾。",
  ui_story_5031_50310502_21_dialog_content = "沒事，因為看你像是要被風吹跑了，怕你生病。",
  ui_story_5031_50310502_22_dialog_content = "呵呵，沒想到你現在還會喜歡這種遊戲。",
  ui_story_5031_50310502_23_dialog_content = "怎麼，覺得太幼稚了？",
  ui_story_5031_50310502_24_dialog_content = "不是，只是有點吃驚。",
  ui_story_5031_50310502_25_dialog_content = "這麼多年過去了，你居然還會對這種遊戲感興趣，甚至把它作為比賽的一環。",
  ui_story_5031_50310502_26_dialog_content = "因為我比較戀舊。",
  ui_story_5031_50310502_27_dialog_content = "我一件事能記很久，比如很多年前被人爽約，讓我等了一整天這件事。",
  ui_story_5031_50310502_28_dialog_content = "......對於當年的不辭而別，我很抱歉。",
  ui_story_5031_50310502_29_dialog_content = "嗯，原諒你了。",
  ui_story_5031_50310502_30_dialog_content = "......？",
  ui_story_5031_50310502_31_dialog_content = "我只是在等這一句道歉而已。",
  ui_story_5031_50310502_32_dialog_content = "其實稍微想想也知道。",
  ui_story_5031_50310502_33_dialog_content = "從一個餐廳老闆家的孩子變成了好泊城的領主，期間會有多少磨難。",
  ui_story_5031_50310502_34_dialog_content = "不過我還是能感覺到，你身上還有許多重要的東西不曾改變，希望那不是我的錯覺。",
  ui_story_5031_50310502_35_dialog_content = "重要的東西？",
  ui_story_5031_50310502_36_dialog_content = "比如你在好泊城推行的健身操，蠢死了，但是很有你的風格。",
  ui_story_5031_50310502_37_dialog_content = "哈哈哈哈，如果大家身體都能強健起來，那蠢就蠢吧。",
  ui_story_5031_50310502_38_dialog_content = "那麼你呢，我回到白夜城之後找過你很久，但根本沒人知道你們去了哪裡。",
  ui_story_5031_50310502_39_dialog_content = "我？",
  ui_story_5031_50310502_40_dialog_content = "我回到好泊城之後找過你很久，但根本沒人知道你們去了哪裡。",
  ui_story_5031_50310502_41_dialog_content = "甚至還有人說你們一家已經不在人世了......",
  ui_story_5031_50310502_42_dialog_content = "差不多吧。",
  ui_story_5031_50310502_43_dialog_content = "就像暗潮危機時每一個疲於求生的可憐人一樣，機緣巧合下我們一家逃進了「綠榴石號」裡。",
  ui_story_5031_50310502_44_dialog_content = "之後也許是命運使然，我被真理結社的維多利亞大人所救。",
  ui_story_5031_50310502_45_dialog_content = "她還給了我操縱起源的力量。",
  ui_story_5031_50310502_46_dialog_content = "但在我返回「綠榴石號」後，才知道父母早已經離世了。",
  ui_story_5031_50310502_47_dialog_content = "我當時一根筋地以為父母的離世與老團長有關，於是向他發起挑戰，想為雙親報仇。",
  ui_story_5031_50310502_48_dialog_content = "後面當我瞭解真相時已經過了很久了，所幸老團長並沒有責怪我。",
  ui_story_5031_50310502_49_dialog_content = "之後，我就和「綠榴石號」，還有馬戲團的人一起在海上四處漂泊。",
  ui_story_5031_50310502_50_dialog_content = "我很抱歉......他們都是很好的人。",
  ui_story_5031_50310502_51_dialog_content = "不用道歉，本來就不是你的錯。",
  ui_story_5031_50310502_52_dialog_content = "雖然我利用真理結社的力量還在繼續著魔術師的生涯。",
  ui_story_5031_50310502_53_dialog_content = "但老實說，我對真理結社和他們的教義沒什麼興趣。",
  ui_story_5031_50310502_54_dialog_content = "畢竟他們之中也有許多不同的派別，我大概就是那種最游離在外「不務正業」的類型。",
  ui_story_5031_50310502_55_dialog_content = "不過維多利亞大人對我有恩，我必須遵守和她的約定。",
  ui_story_5031_50310502_56_dialog_content = "我不想再有任何約定被背棄......",
  ui_story_5031_50310502_57_dialog_content = "約定......咳！咳咳！！",
  ui_story_5031_50310502_58_dialog_content = "你，你咳血了？",
  ui_story_5031_50310502_59_dialog_content = "我，我沒事。只是最近處理政務休息有點少，外加感冒......",
  ui_story_5031_50310502_60_dialog_content = "你當我是傻子嗎！",
  ui_story_5031_50310502_61_dialog_content = "哈哈哈......我怎麼會，我真的很健康。",
  ui_story_5031_50310502_62_dialog_content = "不相信的話用你擅長的占卜，算算我的壽命？我感覺自己還能活個兩百年呢。",
  ui_story_5031_50310502_63_dialog_content = "算個屁，到底怎麼了？和我說實話！",
  ui_story_5031_50310502_64_dialog_content = "哈......哈......你作為好泊城的曾住民，應該知道「英雄傳說」吧。",
  ui_story_5031_50310502_65_dialog_content = "當然知道，那套騙小孩的傳說。",
  ui_story_5031_50310502_66_dialog_content = "那個傳說，是真的。",
  ui_story_5031_50310502_67_dialog_content = "……",
  ui_story_5031_50310502_68_dialog_content = "簡單來說，他們透過以血為契的方式，發動了某種契約封印了暗鬼。",
  ui_story_5031_50310502_69_dialog_content = "被契約所影響的暗鬼陷入沉睡，好泊城也成為暗鬼無法靠近的樂土。",
  ui_story_5031_50310502_70_dialog_content = "而他們的後代也要承擔相應的代價。",
  ui_story_5031_50310502_71_dialog_content = "這就是「摩德利失能症」的真相。",
  ui_story_5031_50310502_72_dialog_content = "什麼！？你也患上了摩德利失能症？難道你臉上的這痕跡就是......",
  ui_story_5031_50310502_73_dialog_content = "是的，不過不用擔心，我現在還......咳咳，還不錯。",
  ui_story_5031_50310502_74_dialog_content = "既然是什麼契約，那也有解除契約的方法吧？",
  ui_story_5031_50310502_75_dialog_content = "其實，我這些年一直在尋找......尋找一個解決方法。",
  ui_story_5031_50310502_76_dialog_content = "什麼方法？",
  ui_story_5031_50310502_77_dialog_content = "抱歉，現在沒有十足的把握，這其中牽扯太多，我沒法簡單地解釋給你聽。",
  ui_story_5031_50310502_78_dialog_content = "……",
  ui_story_5031_50310502_79_dialog_content = "快看！那個衝在前面的女孩子好強！",
  ui_story_5031_50310502_80_dialog_content = "她好像還帶著一個完全不會光能術的人，怎麼會這麼強啊？",
  ui_story_5031_50310502_81_dialog_content = "那個不會光能術的，該不會是空裔吧？",
  ui_story_5031_50310502_82_dialog_content = "什麼？讓我看看空裔！",
  ui_story_5031_50310502_83_dialog_content = "老闆～需要打擾你兩分鐘，補給物資又到了一批，要請你清點一下喔～",
  ui_story_5031_50310502_84_dialog_content = "我知道了，馬上就去。",
  ui_story_5031_50310502_85_dialog_content = "裁判的工作先拜託你了，我很快回來。",
  ui_story_5031_50310502_86_dialog_content = "嗯，去吧，傑諾。",
  ui_story_5031_50310602_1_dialog_content = "「第二輪起跑——開始！」",
  ui_story_5031_50310602_2_dialog_content = "<color=#e8d9bb>鈴鈴——</color>",
  ui_story_5031_50310602_3_dialog_content = "PlayerName！跟緊我們！",
  ui_story_5031_50310602_4_dialog_content = "薇絲和菲雅，注意保護PlayerName，別讓暗鬼靠得太近。",
  ui_story_5031_50310602_5_dialog_content = "明白！",
  ui_story_5031_50310602_6_dialog_content = "抱歉，沒想到每次能活動的時間只有這麼短，指揮也發揮不上太大用處。",
  ui_story_5031_50310602_7_dialog_content = "好像有些光靈已經利用自己的光能術快速衝到守祕人旁邊了。",
  ui_story_5031_50310602_8_dialog_content = "不用太在意這種事，我們就按照自己的步調前進。",
  ui_story_5031_50310602_9_dialog_content = "PlayerName，拜託你幫我們指引前進的線路。",
  ui_story_5031_50310602_10_dialog_content = "明白了！",
  ui_story_5031_50310602_11_dialog_content = "唉——",
  ui_story_5031_50310602_12_dialog_content = "雖然任務裡說要儘量保持距離，但我實在看不下去了。",
  ui_story_5031_50310602_13_dialog_content = "你是......我想起來了，你是審判官馬太。",
  ui_story_5031_50310602_14_dialog_content = "在下正是審判官馬太，這邊不會說話的「罐頭」是我的同僚，審判員洛維。",
  ui_story_5031_50310602_15_dialog_content = "雖然之前彼亞塔曼那個笨小子承蒙您照顧了，但我還是想說——",
  ui_story_5031_50310602_16_dialog_content = "卡蓮殿下，這是何等的失態。",
  ui_story_5031_50310602_17_dialog_content = "那麼驍勇善戰的您，居然因為要保護一個沒有光能術的傢伙而束手束腳。",
  ui_story_5031_50310602_18_dialog_content = "若是您一人前進，不，就算沒有這個空裔，您也早就晉級了吧。",
  ui_story_5031_50310602_19_dialog_content = "這個空裔就和那些庶民一樣，是個沒用的累贅。",
  ui_story_5031_50310602_20_dialog_content = "你，你說什麼——！",
  ui_story_5031_50310602_21_dialog_content = "別在意他。",
  ui_story_5031_50310602_22_dialog_content = "嗯？",
  ui_story_5031_50310602_23_dialog_content = "他內心很有問題。",
  ui_story_5031_50310602_24_dialog_content = "你，你這傢伙說什麼？！",
  ui_story_5031_50310602_25_dialog_content = "繼續說繼續說，菲雅想听。",
  ui_story_5031_50310602_26_dialog_content = "平時故作隨和。",
  ui_story_5031_50310602_27_dialog_content = "其實非常厭惡平民。",
  ui_story_5031_50310602_28_dialog_content = "但實際上非常討厭他看不起的那些所謂「庶民」。",
  ui_story_5031_50310602_29_dialog_content = "明明自己的出身也......",
  ui_story_5031_50310602_30_dialog_content = "喂，不要再說了，停下，恢復你原來的悶聲人設！",
  ui_story_5031_50310602_31_dialog_content = "你聽到我說話了嗎，停下！",
  ui_story_5031_50310602_32_dialog_content = "......閉嘴！",
  ui_story_5031_50310602_33_dialog_content = "嘖。",
  ui_story_5031_50310602_34_dialog_content = "但是白夜城的貴族，多多少少都會有些看不起平民吧。",
  ui_story_5031_50310602_35_dialog_content = "不一樣。",
  ui_story_5031_50310602_X35_dialog_content = "間接碰到手，要洗幾十次。",
  ui_story_5031_50310602_X36_dialog_content = "身上落灰塵，嚇到尖叫。",
  ui_story_5031_50310602_36_dialog_content = "哦哦——那這位大哥哥需要把自己裝進箱子裡與外界隔絕才行呢。",
  ui_story_5031_50310602_37_dialog_content = "是，變態潔癖。",
  ui_story_5031_50310602_38_dialog_content = "大哥哥，你好可憐喔......",
  ui_story_5031_50310602_39_dialog_content = "我還輪不到你個庶民的小丫頭來可憐！！",
  ui_story_5031_50310602_40_dialog_content = "而且工作偷懶。",
  ui_story_5031_50310602_41_dialog_content = "什麼，工作也要偷懶嗎？明明是個大人。",
  ui_story_5031_50310602_42_dialog_content = "借老同學情分。",
  ui_story_5031_50310602_X42_dialog_content = "推給彼亞......",
  ui_story_5031_50310602_43_dialog_content = "<color=#e8d9bb>鈴鈴——</color>",
  ui_story_5031_50310602_44_dialog_content = "牠改變顏色了！大家穩住不要動！",
  ui_story_5031_50310602_45_dialog_content = "糟，糟糕了！",
  ui_story_5031_50310602_46_dialog_content = "拉我一把，我衝得太猛了！",
  ui_story_5031_50310602_47_dialog_content = "可，可惡的庶民，你不要靠過來——！",
  ui_story_5031_50310602_48_dialog_content = "<color=#e8d9bb>咚！</color>",
  ui_story_5031_50310602_49_dialog_content = "對，對不起，這位先生。",
  ui_story_5031_50310602_50_dialog_content = "走......快走開！",
  ui_story_5031_50310602_51_dialog_content = "我的衣服！我要換衣服！",
  ui_story_5031_50310602_52_dialog_content = "洛維，我要回去洗澡！",
  ui_story_5031_50310602_53_dialog_content = "挑食。",
  ui_story_5031_50310602_54_dialog_content = "說自己舌頭怕燙。",
  ui_story_5031_50310602_55_dialog_content = "總是大喊「啊——好燙——」。",
  ui_story_5031_50310602_56_dialog_content = "還讓我看。",
  ui_story_5031_50310602_57_dialog_content = "完全不想看。",
  ui_story_5031_50310602_58_dialog_content = "三位淘汰——",
  ui_story_5031_50310602_59_dialog_content = "下次再聊——",
  ui_story_5031_50310602_60_dialog_content = "和外表帶來的印象有很大差別呢，簡短有力的說話方式讓人印象深刻。",
  ui_story_5031_50310602_X60_dialog_content = "是呀，看起來是個很有趣的人呢。",
  ui_story_5031_50310602_61_dialog_content = "卡蓮，抱歉。",
  ui_story_5031_50310602_62_dialog_content = "道歉什麼？你該不會把馬太的話聽進去了吧。",
  ui_story_5031_50310602_63_dialog_content = "妳那麼拼命，我卻無法戰鬥，有的時候我會感覺自己是個累贅。",
  ui_story_5031_50310602_64_dialog_content = "因為我過於拼命，才讓你有了這種想法嗎？",
  ui_story_5031_50310602_65_dialog_content = "嗯，我感覺妳在這次嘉年華比賽裡表現得......非常認真，像是把一切都要自己承擔。",
  ui_story_5031_50310602_66_dialog_content = "是這樣嗎……",
  ui_story_5031_50310602_67_dialog_content = "我們從來沒認為你是累贅，你在自己的位置上始終發揮著重要作用。",
  ui_story_5031_50310602_68_dialog_content = "當然，PlayerName一直都是我們重要的夥伴。",
  ui_story_5031_50310602_69_dialog_content = "唉，沒想到PlayerName哥哥被那種人說了幾句就開始亂想呀。",
  ui_story_5031_50310602_70_dialog_content = "大家……",
  ui_story_5031_50310602_71_dialog_content = "<color=#e8d9bb>鈴鈴——</color>",
  ui_story_5031_50310602_72_dialog_content = "牠又變成綠色了，我們馬上就能繼續行動了。",
  ui_story_5031_50310602_73_dialog_content = "我知道了，大家，一起向前衝吧！",
  ui_story_5031_50310701_1_dialog_content = "馬上就要到終點了，PlayerName。",
  ui_story_5031_50310701_2_dialog_content = "只要繼續保持這個步調，在下一輪行動我們就能抵達終點。",
  ui_story_5031_50310701_3_dialog_content = "<color=#e8d9bb>鈴鈴——</color>",
  ui_story_5031_50310701_4_dialog_content = "大家行動！",
  ui_story_5031_50310701_5_dialog_content = "等等，不對！",
  ui_story_5031_50310701_6_dialog_content = "牠又變回來了！",
  ui_story_5031_50310701_7_dialog_content = "<color=#e8d9bb>鈴鈴——</color>",
  ui_story_5031_50310701_8_dialog_content = "怎麼回事，時間間隔怎麼突然變得這麼短？",
  ui_story_5031_50310701_9_dialog_content = "唉唷！",
  ui_story_5031_50310701_10_dialog_content = "可惡！怎麼突然改變間隔了！",
  ui_story_5031_50310701_11_dialog_content = "這次比賽應該是為了考驗反應能力，所以突然變成不固定間隔也很正常。",
  ui_story_5031_50310701_12_dialog_content = "我們現在必須更謹慎地行動。",
  ui_story_5031_50310701_13_dialog_content = "又有四位淘汰！",
  ui_story_5031_50310701_14_dialog_content = "卡蓮你注意到了嗎，那邊的小姑娘我感覺不太對。",
  ui_story_5031_50310701_15_dialog_content = "你看她好像神情有點奇怪，我感應到她身上的光能力量也一直在減弱。",
  ui_story_5031_50310701_16_dialog_content = "嗚……",
  ui_story_5031_50310701_17_dialog_content = "不好，她倒下了！",
  ui_story_5031_50310701_18_dialog_content = "按照規則，她可能會被丟進海裡吧？",
  ui_story_5031_50310701_19_dialog_content = "但是她好像閉上了眼睛，一副很痛苦的樣子。",
  ui_story_5031_50310701_20_dialog_content = "這樣被丟下海裡，可能會有危險。",
  ui_story_5031_50310701_21_dialog_content = "PlayerName，PlayerName，想想辦法啦。",
  ui_story_5031_50310701_22_dialog_content = "嘎——",
  ui_story_5031_50310701_23_dialog_content = "不能再等了。",
  ui_story_5031_50310701_24_dialog_content = "卡蓮！",
  ui_story_5031_50310702_1_dialog_content = "比賽暫停！！",
  ui_story_5031_50310702_2_dialog_content = "卡蓮殿下，發生什麼事了？",
  ui_story_5031_50310702_3_dialog_content = "這個小姑娘的狀況不太對。",
  ui_story_5031_50310702_4_dialog_content = "交給我吧，我懂一些醫學。",
  ui_story_5031_50310702_5_dialog_content = "小姑娘，妳怎麼了，能聽到我的聲音嗎？",
  ui_story_5031_50310702_6_dialog_content = "嗚……",
  ui_story_5031_50310702_7_dialog_content = "這個症狀......是「摩德利失能症」。",
  ui_story_5031_50310702_8_dialog_content = "快，把這個藥吃了。",
  ui_story_5031_50310702_9_dialog_content = "傑諾，麻煩你把剛剛那條毯子拿過來。",
  ui_story_5031_50310702_10_dialog_content = "知道了。",
  ui_story_5031_50310702_11_dialog_content = "呼……呼……",
  ui_story_5031_50310702_12_dialog_content = "領主大人......謝謝您......我已經感覺好多了。",
  ui_story_5031_50310702_13_dialog_content = "別太勉強，妳現在的體溫很低，裹上毛毯就會舒服很多。",
  ui_story_5031_50310702_14_dialog_content = "嗯......我知道，還有領主大人教我們的健身操......蘭卡也有乖乖多喝熱水。",
  ui_story_5031_50310702_15_dialog_content = "嗯，蘭卡真的很乖呢，我也為妳感到驕傲。",
  ui_story_5031_50310702_16_dialog_content = "艾維斯，毛毯拿來了。",
  ui_story_5031_50310702_17_dialog_content = "嗯，謝謝妳。",
  ui_story_5031_50310702_18_dialog_content = "帕托！",
  ui_story_5031_50310702_19_dialog_content = "在，艾維斯閣下。",
  ui_story_5031_50310702_20_dialog_content = "讓衛兵送她去家人身邊，敦促她的家人帶她去醫院做檢查。",
  ui_story_5031_50310702_21_dialog_content = "明白，請大人放心！",
  ui_story_5031_50310702_22_dialog_content = "傑諾，你看到了嗎，她還那麼小。",
  ui_story_5031_50310702_23_dialog_content = "……",
  ui_story_5031_50310702_24_dialog_content = "艾維斯閣下，果然是好泊城人民愛戴的領主。",
  ui_story_5031_50310702_25_dialog_content = "你對人民的愛護程度真是足以讓許多自詡愛民的貴族汗顏。",
  ui_story_5031_50310702_26_dialog_content = "好泊城能有閣下這樣心系人民的領主，真是非常幸運。",
  ui_story_5031_50310702_27_dialog_content = "嘖，不過就是一介庶民，卡蓮殿下也太興師動眾了。",
  ui_story_5031_50310702_28_dialog_content = "一想想剛剛那個撞上來讓我淘汰的傢伙......我就渾身難受的要命。",
  ui_story_5031_50310702_29_dialog_content = "還差點被丟進海裡，還好我爬回來了。",
  ui_story_5031_50310702_30_dialog_content = "我們到底什麼時候能回去洗澡更衣。",
  ui_story_5031_50310702_31_dialog_content = "安靜。",
  ui_story_5031_50310702_32_dialog_content = "感謝您的認可，卡蓮殿下。",
  ui_story_5031_50310702_33_dialog_content = "可惜我沒辦法幫上她太多。",
  ui_story_5031_50310702_34_dialog_content = "抱歉，我有點事，先失陪一下。",
  ui_story_5031_50310702_35_dialog_content = "請自便。",
  ui_story_5031_50310702_36_dialog_content = "……",
  ui_story_5031_50310702_37_dialog_content = "艾維斯閣下，您找我。",
  ui_story_5031_50310702_38_dialog_content = "帕托，時間不多了。",
  ui_story_5031_50310702_39_dialog_content = "我剛剛已經察覺到，「<color=#FFB400>信風石</color>」的力量又減弱了。",
  ui_story_5031_50310702_40_dialog_content = "所以我還有那個小女孩，才會接連發病。",
  ui_story_5031_50310702_41_dialog_content = "恐怕封印堅持不了多久了。",
  ui_story_5031_50310702_42_dialog_content = "大人，我們真的不能向白夜城的人求助嗎？卡蓮殿下看起來與那些貴族不同。",
  ui_story_5031_50310702_43_dialog_content = "也許她能聯繫上舒瓦茲大人，向我們提供幫助。",
  ui_story_5031_50310702_44_dialog_content = "我雖然單方面願意相信睿智賢明的舒瓦茲大人能分清利害。",
  ui_story_5031_50310702_45_dialog_content = "但我對元老院的那群人沒有這種信心。",
  ui_story_5031_50310702_46_dialog_content = "比起派重兵保護好泊城，他們更有可能提議我們全城遷走，讓我們離開世代生存的故土。",
  ui_story_5031_50310702_47_dialog_content = "而且祖先花費了諸多努力才守護住的「信風石」的祕密，現在幾乎無人所知。",
  ui_story_5031_50310702_48_dialog_content = "如果它的事被流傳開，肯定會有別有用心的人想要奪走。",
  ui_story_5031_50310702_49_dialog_content = "失去了信風石，那麼好泊城就全完了。",
  ui_story_5031_50310702_50_dialog_content = "先祖和他們的後人用生命保護的、好泊城人民世世代代建設起來的家園，就煙消雲散了。",
  ui_story_5031_50310702_51_dialog_content = "這一切都是為了人民的生命和好泊城的未來，我們必須依靠自己，也只能相信自己。",
  ui_story_5031_50310702_52_dialog_content = "是的......大人，屬下明白了。",
  ui_story_5031_50310702_53_dialog_content = "為好泊城和摩德利家族，在下赴湯蹈火、萬死不辭。",
  ui_story_5031_50310702_54_dialog_content = "已經，沒法回頭了。",
  ui_story_5031_50310702_55_dialog_content = "失敗的話，好泊城的人民，不會再有人來拯救。",
  ui_story_5031_50310702_56_dialog_content = "只有我們，能拯救自己，帕托。",
  ui_story_5031_50310702_57_dialog_content = "卡蓮殿下，您確定要隱瞞身分對嗎？",
  ui_story_5031_50310702_58_dialog_content = "是的，我不想讓這趟放鬆的旅程被什麼意外情況打擾，拜託艾維斯閣下了。",
  ui_story_5031_50310702_59_dialog_content = "我明白了。",
  ui_story_5031_50310702_60_dialog_content = "各位，請聽我說。",
  ui_story_5031_50310702_61_dialog_content = "剛剛一位參賽的小姑娘身體不適倒下，我們的暗鬼按照規則險些將她丟進海裡。",
  ui_story_5031_50310702_62_dialog_content = "在這危急時刻，這位無私無畏的少女以及她的夥伴們冒著犯規的風險挺身而出！",
  ui_story_5031_50310702_63_dialog_content = "救下了可能會落水遇到危險的小姑娘。",
  ui_story_5031_50310702_64_dialog_content = "雖然她們觸犯了規則，但在好泊城，心懷善意的人不應被如此對待！",
  ui_story_5031_50310702_65_dialog_content = "我們好泊城崇尚將善良帶給他人！因此希望大家能允許我，讓他們幾位重回賽場！",
  ui_story_5031_50310702_66_dialog_content = "同意！同意！",
  ui_story_5031_50310702_67_dialog_content = "我支持領主大人！",
  ui_story_5031_50310702_68_dialog_content = "謝謝大家！能作為你們的領主，是我的榮幸。",
  ui_story_5031_50310702_69_dialog_content = "謝謝你，艾維斯領主。",
  ui_story_5031_50310702_70_dialog_content = "不用客氣，我想這也是在場每一個人的心聲。",
  ui_story_5031_50310702_71_dialog_content = "您可以和夥伴們一起回到賽場上了。",
  ui_story_5031_50310702_X71_dialog_content = "那麼，比賽繼續！",
  ui_story_5031_50310702_X72_dialog_content = "哈......哈！妳們跑得也太快了，怎麼都到終點了。",
  ui_story_5031_50310702_X73_dialog_content = "PlayerName，抓緊時間！牠又要變色了！",
  ui_story_5031_50310702_X74_dialog_content = "啊？不，不行，我現在已經到極限了。",
  ui_story_5031_50310702_72_dialog_content = "PlayerName，直接衝過來，我們會接住你！",
  ui_story_5031_50310702_73_dialog_content = "知道了！",
  ui_story_5031_50310702_74_dialog_content = "<color=#e8d9bb>咚——</color>",
  ui_story_5031_50310702_75_dialog_content = "真是千鈞一發呢。",
  ui_story_5031_50310702_76_dialog_content = "好重呀，PlayerName。",
  ui_story_5031_50310702_77_dialog_content = "成功了！",
  ui_story_5031_50310702_78_dialog_content = "這樣就能順利晉級了。",
  ui_story_5031_50310702_79_dialog_content = "很多實力強勁的選手都已經衝過晉級線了。",
  ui_story_5031_50310702_80_dialog_content = "那個一直揮手喊個不停的，是貢露長官嗎？",
  ui_story_5031_50310702_81_dialog_content = "啊——琪爾妳倒是快點呀！",
  ui_story_5031_50310702_82_dialog_content = "快用妳的那個最強招式啦！",
  ui_story_5031_50310702_83_dialog_content = "再這樣下去我們兩個都要被淘汰啦！",
  ui_story_5031_50310702_84_dialog_content = "琪，琪個，但是「<color=#FFB400>斯提克斯</color>」還......",
  ui_story_5031_50310702_85_dialog_content = "嗚......我，我知道了，「腿部機甲狀態調整——II型」。",
  ui_story_5031_50310702_86_dialog_content = "「能源釋放百分比提高50%」。",
  ui_story_5031_50310702_87_dialog_content = "出發！",
  ui_story_5031_50310702_88_dialog_content = "唔啊！琪爾她直接衝過來了！",
  ui_story_5031_50310702_89_dialog_content = "唔啊啊啊——大家快躲開，「斯提克斯」失去控制啦！",
  ui_story_5031_50310702_90_dialog_content = "<color=#e8d9bb>轟——</color>",
  ui_story_5031_50310702_91_dialog_content = "好，好厲害，把船上的建築都穿了個洞。",
  ui_story_5031_50310702_92_dialog_content = "甲板上也拉出了一條長長的痕跡。",
  ui_story_5031_50310702_93_dialog_content = "唔哇，這可真了不得，都看不到人去哪了。",
  ui_story_5031_50310702_94_dialog_content = "妳沒事吧，小琪爾。",
  ui_story_5031_50310702_95_dialog_content = "疼疼疼，我，我沒怎麼受傷。",
  ui_story_5031_50310702_96_dialog_content = "妳雖然沒怎麼受傷，但是把我心愛的綠榴石號給狠狠撞了一下呢。",
  ui_story_5031_50310702_97_dialog_content = "欸，對，對不起！",
  ui_story_5031_50310702_98_dialog_content = "我不是故意的，「斯提克斯」的調試還不徹底，不，都怪我還不夠努力......",
  ui_story_5031_50310702_99_dialog_content = "唉，現在追究錯不錯已經沒意義啦～不如來想想怎麼處理吧。",
  ui_story_5031_50310702_100_dialog_content = "其實最直接就是花錢找人修理船上的破損。",
  ui_story_5031_50310702_101_dialog_content = "不過小琪爾看起來，也不像是什麼有錢人家的孩子呢。",
  ui_story_5031_50310702_102_dialog_content = "是的，對不起......",
  ui_story_5031_50310702_103_dialog_content = "都說別一直道歉啦～打起精神來。",
  ui_story_5031_50310702_104_dialog_content = "對了！妳不妨挑戰一下接下來的衝浪比賽呢！",
  ui_story_5031_50310702_105_dialog_content = "下一場衝浪比賽是由艾維斯領主提供贊助的，還專門為第一名準備了額外獎金。",
  ui_story_5031_50310702_106_dialog_content = "真，真的嗎！",
  ui_story_5031_50310702_107_dialog_content = "真的！我想想......好像第一名獎金有五百萬白夜幣！",
  ui_story_5031_50310702_108_dialog_content = "差不多就是修理的費用啦。",
  ui_story_5031_50310702_109_dialog_content = "太好了，我要參加！",
  ui_story_5031_50310702_110_dialog_content = "嘿嘿，別高興太早啦。",
  ui_story_5031_50310702_111_dialog_content = "我和梅爾特三姐妹她們也會一起參加喔～",
  ui_story_5031_50310702_112_dialog_content = "虹霞可是不會輕易放水的，小琪爾～",
  ui_story_5031_50310702_113_dialog_content = "如果妳輸了的話～嗯～這孩子是叫「斯提克斯」嗎？",
  ui_story_5031_50310702_114_dialog_content = "它可就歸我了喔～",
  ui_story_5031_50310702_115_dialog_content = "......不行",
  ui_story_5031_50310702_116_dialog_content = "欸～人家也只是想研究一下它啦，並不會搶走或者對它做什麼的。",
  ui_story_5031_50310702_117_dialog_content = "研究之後就會老實還給妳的～",
  ui_story_5031_50310702_118_dialog_content = "對不起。",
  ui_story_5031_50310702_119_dialog_content = "只有這個......不行......",
  ui_story_5031_50310801_1_dialog_content = "大家，夏日的海風和免費的水果是否讓你們精神為之一振呢？",
  ui_story_5031_50310801_2_dialog_content = "如果已經休息好了，就讓我們迎來下一輪的精彩比拼吧！",
  ui_story_5031_50310801_3_dialog_content = "好——！",
  ui_story_5031_50310801_4_dialog_content = "熱情非常高漲呢，看來一個個都已經摩拳擦掌了！",
  ui_story_5031_50310801_5_dialog_content = "那麼接下來，就讓我們洗去剛剛激烈戰鬥下的汗水。",
  ui_story_5031_50310801_6_dialog_content = "在熱情似火的陽光下，來泡一個沁心涼爽的海水浴吧！",
  ui_story_5031_50310801_7_dialog_content = "接下來就是大家期待已久的——<size=45>衝浪比賽！</size>",
  ui_story_5031_50310801_8_dialog_content = "哇！ ！",
  ui_story_5031_50310801_9_dialog_content = "因為衝浪比賽是好泊城的傳統賽事，所以這輪獲得第一名的隊伍......",
  ui_story_5031_50310801_10_dialog_content = "會額外獲得艾維斯領主提供的<color=#FFB400>五百萬白夜幣</color>！",
  ui_story_5031_50310801_11_dialog_content = "五，五百萬？",
  ui_story_5031_50310801_12_dialog_content = "五百萬？！",
  ui_story_5031_50310801_13_dialog_content = "PlayerName，薇絲，稍微收斂一下情緒。",
  ui_story_5031_50310801_14_dialog_content = "別忘了我們的真正目標是什麼。",
  ui_story_5031_50310801_15_dialog_content = "我知道，但是幫菲雅得到那隻大獎神奇動物，和獲得獎金並不衝突嘛。",
  ui_story_5031_50310801_16_dialog_content = "好泊城真富有啊。",
  ui_story_5031_50310801_17_dialog_content = "的確，好泊城近年來發展得非常迅速。",
  ui_story_5031_50310801_18_dialog_content = "作為貴族領主，願意為居民百姓這樣一擲千金，屬實難得。",
  ui_story_5031_50310801_19_dialog_content = "有這樣的賢明之君，能治理好好泊城也不奇怪。",
  ui_story_5031_50310801_20_dialog_content = "卡蓮最近，感覺真的是很努力呢。",
  ui_story_5031_50310801_21_dialog_content = "哪怕在休假的時候也會想到國家的發展問題。",
  ui_story_5031_50310801_22_dialog_content = "啊，抱歉，讓你們感到無聊了吧......",
  ui_story_5031_50310801_23_dialog_content = "不不，完全不會，我不是這個意思。",
  ui_story_5031_50310801_24_dialog_content = "我只是有點擔心妳會太累。",
  ui_story_5031_50310801_25_dialog_content = "是呀卡蓮，既然來散心，就適當放鬆一些吧！",
  ui_story_5031_50310801_26_dialog_content = "這一點可以學習一下菲雅，你看她啃個鳳梨都能快樂成那樣。",
  ui_story_5031_50310801_27_dialog_content = "完全忘了她來這裡的目的是什麼了。",
  ui_story_5031_50310801_28_dialog_content = "嗷嗚～好甜好甜！",
  ui_story_5031_50310801_29_dialog_content = "慶典真好啊，有免費的水果，好好吃！",
  ui_story_5031_50310801_30_dialog_content = "呵，確實如此。",
  ui_story_5031_50310801_31_dialog_content = "菲雅身上，有著很多值得學習的地方。",
  ui_story_5031_50310801_32_dialog_content = "<size=33>不僅是她，薇絲和PlayerName也是......</size>",
  ui_story_5031_50310801_33_dialog_content = "妳我都知道暗鬼是殺不完的。",
  ui_story_5031_50310801_34_dialog_content = "作為一名君主，妳不能只是一味地衝在最前線，試圖一個人抵擋一切。",
  ui_story_5031_50310801_35_dialog_content = "那樣妳不光會害了自己，還會害了信賴追隨妳的人。",
  ui_story_5031_50310801_36_dialog_content = "……",
  ui_story_5031_50310801_37_dialog_content = "卡蓮，我希望妳認真想一想，為什麼我會讓妳跟著PlayerName四處遊歷。",
  ui_story_5031_50310801_38_dialog_content = "我......",
  ui_story_5031_50310801_39_dialog_content = "妳的王道，還需要成長。",
  ui_story_5031_50310801_40_dialog_content = "……是。",
  ui_story_5031_50310801_41_dialog_content = "卡蓮？卡蓮！",
  ui_story_5031_50310801_42_dialog_content = "嗯？抱歉，妳剛剛說什麼？",
  ui_story_5031_50310801_43_dialog_content = "我說我們差不多該去換衣服啦，衝浪比賽可是鐵定會落水的。",
  ui_story_5031_50310801_44_dialog_content = "妳的新衣服可不能弄髒了！",
  ui_story_5031_50310801_45_dialog_content = "啊，好的。",
  ui_story_5031_50310801_46_dialog_content = "等等，換什麼衣服？",
  ui_story_5031_50310801_47_dialog_content = "嘿嘿，那自然是——",
  ui_story_5031_50310801_48_dialog_content = "泳裝啦！",
  ui_story_5031_50310801_49_dialog_content = "唔哇！卡蓮姐姐和薇絲姐姐好好看呀！",
  ui_story_5031_50310801_50_dialog_content = "嘿嘿～謝謝小菲雅。",
  ui_story_5031_50310801_51_dialog_content = "為，為什麼妳會連我的泳裝都帶著？",
  ui_story_5031_50310801_52_dialog_content = "知道要來海邊，那怎麼能不準備泳裝呢！",
  ui_story_5031_50310801_53_dialog_content = "不過因為之前都不是水上活動，所以沒有想起來這件事。",
  ui_story_5031_50310801_54_dialog_content = "好羡慕喔，菲雅也想擁有泳裝！",
  ui_story_5031_50310801_55_dialog_content = "那等慶典結束之後我們去找找好泊城裡的服裝店，為妳定做一套吧～",
  ui_story_5031_50310801_56_dialog_content = "真的嗎！謝謝薇絲姐姐！",
  ui_story_5031_50310801_57_dialog_content = "啊，菲雅還是第一次定做衣服呢，好開心啊！",
  ui_story_5031_50310801_58_dialog_content = "然後還有上次看到一套很可愛的餐具，說不定也可以買了！",
  ui_story_5031_50310801_59_dialog_content = "好耶好耶！",
  ui_story_5031_50310801_60_dialog_content = "還有……",
  ui_story_5031_50310801_61_dialog_content = "咳，那、那個......",
  ui_story_5031_50310801_62_dialog_content = "嗯？怎麼了PlayerName？",
  ui_story_5031_50310801_63_dialog_content = "雖然在妳們討論得這麼起勁的時候打擾很抱歉，但是......",
  ui_story_5031_50310801_64_dialog_content = "我，不會衝浪。",
  ui_story_5031_50310801_65_dialog_content = "<size=45>什麼？！</size>",
  ui_story_5031_50310801_66_dialog_content = "那菲雅的定制泳衣豈不是泡湯了？",
  ui_story_5031_50310801_67_dialog_content = "最擔心的竟然是泳衣嗎？妳已經忘了我們的真正目標是那隻神奇動物嗎？",
  ui_story_5031_50310801_68_dialog_content = "嗚......嗚，菲雅的泳衣，還有「海雲鯨」......",
  ui_story_5031_50310801_69_dialog_content = "都沒希望了啦，嗚嗚嗚哇啊啊啊！",
  ui_story_5031_50310801_70_dialog_content = "啊抱歉抱歉，菲雅不要哭了......",
  ui_story_5031_50310801_71_dialog_content = "我會想辦法的，就......就算真的沒拿到第一......",
  ui_story_5031_50310801_72_dialog_content = "至少泳衣我之後也會自己掏錢給你定做的！",
  ui_story_5031_50310801_73_dialog_content = "嗚嗚，真的嗎？",
  ui_story_5031_50310801_74_dialog_content = "真的，卡蓮和薇絲可以作證！",
  ui_story_5031_50310801_75_dialog_content = "那，那好吧。",
  ui_story_5031_50310801_76_dialog_content = "對不起，也怪我還沒有問清楚情況就擅自開始幻想得獎。",
  ui_story_5031_50310801_77_dialog_content = "不是薇絲的錯，都怪我太笨手笨腳了，竟然連衝浪都不會。",
  ui_story_5031_50310801_78_dialog_content = "啊，不不，PlayerName你誤會了。",
  ui_story_5031_50310801_79_dialog_content = "衝浪絕對不是一件人人都會的事情。",
  ui_story_5031_50310801_80_dialog_content = "只是恰好我以前有學過而已。",
  ui_story_5031_50310801_X80_dialog_content = "是的，我也是小時候來好泊城那次，恰好目睹了當年的衝浪比賽。",
  ui_story_5031_50310801_X81_dialog_content = "所以才有了興趣，找了老師來教我。",
  ui_story_5031_50310801_81_dialog_content = "原來是這樣嗎？那菲雅妳是在哪裡學的呀？",
  ui_story_5031_50310801_82_dialog_content = "嗯？菲雅沒有學過喔。",
  ui_story_5031_50310801_83_dialog_content = "什麼？！",
  ui_story_5031_50310801_84_dialog_content = "那妳剛剛哭得那麼大聲幹什麼！說到底妳不是也不會嗎？！",
  ui_story_5031_50310801_85_dialog_content = "呿，空裔這麼大聲地吼什麼啦，這麼兇當心以後找不到女朋友。",
  ui_story_5031_50310801_86_dialog_content = "女......女朋友？！",
  ui_story_5031_50310801_87_dialog_content = "妳這個傢伙在說什麼啊！給我過來！",
  ui_story_5031_50310801_88_dialog_content = "哇哇！大家都到海邊去了！我們也快過去吧！",
  ui_story_5031_50310801_89_dialog_content = "跑得真快！",
  ui_story_5031_50310801_90_dialog_content = "……",
  ui_story_5031_50310801_91_dialog_content = "……",
  ui_story_5031_50310801_92_dialog_content = "（為什麼氣氛忽然變得有點奇怪？）",
  ui_story_5031_50310801_93_dialog_content = "咳。那......那我們，也過去吧？",
  ui_story_5031_50310801_94_dialog_content = "哦，好。",
  ui_story_5031_50310801_95_dialog_content = "嗯，走吧。",
  ui_story_5031_50310801_96_dialog_content = "（她們兩個為什麼走得那麼快啊？）",
  ui_story_5031_50310801_97_dialog_content = "對，你的雙手要平行放在胸腔底部，雙腳併攏。",
  ui_story_5031_50310801_98_dialog_content = "然後用手臂的力量把身體撐起來。",
  ui_story_5031_50310801_99_dialog_content = "這、這樣嗎？",
  ui_story_5031_50310801_100_dialog_content = "對，目視前方，你做得很好。",
  ui_story_5031_50310801_101_dialog_content = "等海浪起來的時候，就跳起身來，雙腳與肩同寬，挺起背部。",
  ui_story_5031_50310801_102_dialog_content = "浪來了喔！",
  ui_story_5031_50310801_103_dialog_content = "感受到衝浪板被推動加速了嗎，就是現在！",
  ui_story_5031_50310801_104_dialog_content = "好、好的！",
  ui_story_5031_50310801_105_dialog_content = "跳起來......哇啊啊啊！",
  ui_story_5031_50310801_106_dialog_content = "<color=#e8d9bb>噗通——</color>",
  ui_story_5031_50310801_107_dialog_content = "PlayerName！",
  ui_story_5031_50310801_108_dialog_content = "咳咳咳！",
  ui_story_5031_50310801_109_dialog_content = "我，我沒事，還活著......",
  ui_story_5031_50310801_110_dialog_content = "呿，PlayerName你好弱喔。",
  ui_story_5031_50310801_111_dialog_content = "連菲雅都已經學會站在板子上了。",
  ui_story_5031_50310801_112_dialog_content = "妳這哪裡是站！妳明明是在蹲著！",
  ui_story_5031_50310801_113_dialog_content = "那也比你強！",
  ui_story_5031_50310801_114_dialog_content = "而且有卡蓮姐姐剛剛說的方法，菲雅學會蹲在板子上就足夠了！",
  ui_story_5031_50310801_115_dialog_content = "與魚群交流讓牠們幫我推動衝浪板，可是只有菲雅才能做到的事情喔！",
  ui_story_5031_50310801_116_dialog_content = "妳……",
  ui_story_5031_50310801_117_dialog_content = "時——間——到！",
  ui_story_5031_50310801_118_dialog_content = "哇哦，能看到許多選手都已經在海中開始練習了，幹勁滿滿嘛！",
  ui_story_5031_50310801_119_dialog_content = "看來五百萬白夜幣真是非常有吸引力呢～",
  ui_story_5031_50310801_120_dialog_content = "哈哈哈哈哈！",
  ui_story_5031_50310801_121_dialog_content = "哈哈，開個小玩笑！",
  ui_story_5031_50310801_122_dialog_content = "那麼現在，我開始講述規則！",
  ui_story_5031_50310801_123_dialog_content = "還是老規矩，最多四人一組，輪流進行賽道衝浪。",
  ui_story_5031_50310801_124_dialog_content = "人數不夠的隊伍，可以選擇自由組隊。",
  ui_story_5031_50310801_125_dialog_content = "因為這次只會從每支隊伍裡選出兩個最高分，去計算平均分，所以兩人即可參加！",
  ui_story_5031_50310801_126_dialog_content = "依然是擊殺暗鬼幻象得分，但這次跌落海裡不算淘汰，可以繼續比賽～",
  ui_story_5031_50310801_127_dialog_content = "除了擊殺暗鬼的分數外，衝浪的動作評分會佔據個人得分的50%。",
  ui_story_5031_50310801_128_dialog_content = "所以大家，謹慎地安排隊員的出場順序，也是制勝的關鍵！",
  ui_story_5031_50310801_129_dialog_content = "——哎呀，不小心把我們的祕訣說出來了！這下競爭更激烈了。",
  ui_story_5031_50310801_130_dialog_content = "哈哈哈哈哈哈！",
  ui_story_5031_50310801_131_dialog_content = "不過管他呢～大家玩得開心就好！",
  ui_story_5031_50310801_132_dialog_content = "那麼第一輪比賽馬上就要開始了。",
  ui_story_5031_50310801_133_dialog_content = "請各隊伍安排好後，讓第一位勇士划到起點處等候吧！",
  ui_story_5031_50310801_134_dialog_content = "最後再告訴大家一個小祕密——",
  ui_story_5031_50310801_135_dialog_content = "我們隊第一個上場的，是我喔！",
  ui_story_5031_50310801_136_dialog_content = "噢噢噢噢——！",
  ui_story_5031_50310801_137_dialog_content = "虹霞小姐衝呀！",
  ui_story_5031_50310801_138_dialog_content = "虹霞小姐的人氣愈來愈高了。",
  ui_story_5031_50310801_139_dialog_content = "怎麼辦，感覺她們這麼信心滿滿，應該是很擅長衝浪的樣子。",
  ui_story_5031_50310801_140_dialog_content = "沒辦法了，不過規則裡只取兩條成績這一點，還算是有利的情況。",
  ui_story_5031_50310801_141_dialog_content = "那麼出戰順序就很重要。",
  ui_story_5031_50310801_142_dialog_content = "如果虹霞小姐第一個出場的話，我們這邊......",
  ui_story_5031_50310801_143_dialog_content = "哼哼，那當然是，派出最強的我來迎戰了！",
  ui_story_5031_50310801_144_dialog_content = "......妳？最強？",
  ui_story_5031_50310801_145_dialog_content = "你這是什麼語氣！",
  ui_story_5031_50310801_146_dialog_content = "不要忘了，剛剛卡蓮姐姐說的方法，可是只有菲雅能做到喔！",
  ui_story_5031_50310801_147_dialog_content = "一定可以讓菲雅順利地拿下第一！",
  ui_story_5031_50310801_148_dialog_content = "PlayerName你就等著迎接我的凱旋吧！",
  ui_story_5031_50310801_149_dialog_content = "……真的沒問題嗎？",
  ui_story_5031_50310801_150_dialog_content = "看她這副樣子，我忽然更擔心了。",
  ui_story_5031_50310801_151_dialog_content = "咳，因為連主持人都跑去參加比賽了，所以這一局由我來做主持。",
  ui_story_5031_50310801_152_dialog_content = "嗯，從這個角度看過去，在海上沉浮著的你們，是如此渺小。",
  ui_story_5031_50310801_153_dialog_content = "但是如此渺小的存在，卻懂得順應自然的節奏，研究出了衝浪這樣的運動。",
  ui_story_5031_50310801_154_dialog_content = "這不失為一種極具美感與智慧的藝術。",
  ui_story_5031_50310801_155_dialog_content = "加油吧，去駕馭那些海浪的韻律，去征服......",
  ui_story_5031_50310801_156_dialog_content = "......能不能少廢話，快點開始啊！",
  ui_story_5031_50310801_157_dialog_content = "我們都等著看比賽呢！",
  ui_story_5031_50310801_158_dialog_content = "嘖，愚鈍的庸才果然無法理解。",
  ui_story_5031_50310801_159_dialog_content = "既然你們如此沒有耐心，那麼比賽現在就開始吧。",
  ui_story_5031_50310801_160_dialog_content = "……",
  ui_story_5031_50310801_161_dialog_content = "啊？這麼草率就開始了嗎？！",
  ui_story_5031_50310801_162_dialog_content = "這傢伙到底會不會當主持人啊！",
  ui_story_5031_50310801_163_dialog_content = "哈哈哈，真不愧是傑諾啊。",
  ui_story_5031_50310801_164_dialog_content = "那麼，我先走一步！",
  ui_story_5031_50310801_165_dialog_content = "啊啊，琪爾，比賽已經開始了，快出發！",
  ui_story_5031_50310801_166_dialog_content = "這就開始了？！不像之前一樣給個訊號什麼的嗎？",
  ui_story_5031_50310801_167_dialog_content = "糟......糟糕，「腿部機甲狀態調整——噴射模式」！",
  ui_story_5031_50310801_168_dialog_content = "這一個兩個的，都是用機甲動力驅動嗎？",
  ui_story_5031_50310801_169_dialog_content = "掀起的海浪直接把旁邊的參賽者給拋進海裡了啊！",
  ui_story_5031_50310801_170_dialog_content = "這還怎麼比啊？",
  ui_story_5031_50310801_171_dialog_content = "還好，菲雅她的位置離得比較遠，還算保持著平衡。",
  ui_story_5031_50310801_172_dialog_content = "噢噢噢噢——！虹霞小姐衝出來了！",
  ui_story_5031_50310801_173_dialog_content = "哇！這個急轉跳躍好帥氣！",
  ui_story_5031_50310801_174_dialog_content = "那個駕駛機甲的少女也不錯欸，反應很快！",
  ui_story_5031_50310801_175_dialog_content = "不過比起虹霞小姐還欠缺些美感。",
  ui_story_5031_50310801_176_dialog_content = "哼，這場比賽可沒這麼簡單。",
  ui_story_5031_50310801_177_dialog_content = "嘶吼吧，來自深海的詛咒之靈們。",
  ui_story_5031_50310801_178_dialog_content = "嘎嘎！",
  ui_story_5031_50310801_179_dialog_content = "出現了！",
  ui_story_5031_50310801_180_dialog_content = "哈哈！虹霞姐又要變身了。",
  ui_story_5031_50310801_181_dialog_content = "唔，虹霞姐要小心啊......",
  ui_story_5031_50310801_182_dialog_content = "欸？竟然從海裡竄出了暗鬼！",
  ui_story_5031_50310801_183_dialog_content = "這樣難度有點大......啊！",
  ui_story_5031_50310801_184_dialog_content = "虹，虹霞？",
  ui_story_5031_50310801_185_dialog_content = "噢噢噢噢！——",
  ui_story_5031_50310801_186_dialog_content = "終於忍耐到現在了——你們這群臭蟲！",
  ui_story_5031_50310801_187_dialog_content = "<size=45>都給我去死！</size>",
  ui_story_5031_50310801_188_dialog_content = "臉色又這麼難看，是在想蘭卡的事嗎？",
  ui_story_5031_50310802_X1_dialog_content = "臉色又這麼難看，是在想蘭卡的事嗎？",
  ui_story_5031_50310802_1_dialog_content = "啊，嗯......是的。",
  ui_story_5031_50310802_2_dialog_content = "給你拿了點水果，你得補充水分了。",
  ui_story_5031_50310802_3_dialog_content = "謝謝你，傑諾。",
  ui_story_5031_50310802_4_dialog_content = "剛剛你給她吃的藥，就是你所說的解決辦法？",
  ui_story_5031_50310802_5_dialog_content = "並不是，那是我根據古籍內相關記載研製出來的藥物，只能緩解一時痛苦。",
  ui_story_5031_50310802_6_dialog_content = "那竟然是你研製的？",
  ui_story_5031_50310802_7_dialog_content = "你以前不是想做廚師嗎，怎麼變成藥劑師了。",
  ui_story_5031_50310802_8_dialog_content = "呵呵，好泊城不缺掌勺的名廚，但是缺能解決「摩德利失能症」的人。",
  ui_story_5031_50310802_9_dialog_content = "所以你就犧牲了自己的夢想，去做了那個偉大的人？",
  ui_story_5031_50310802_10_dialog_content = "我從沒想過偉不偉大這件事，我只想不想再看到有人因此而受苦。",
  ui_story_5031_50310802_11_dialog_content = "況且我也算不上什麼藥劑師，只是喜歡泡在書籍卷軸堆裡研究調查而已。",
  ui_story_5031_50310802_12_dialog_content = "等到「摩德利失能症」徹底被解決的那一天，我也就可以做我想做的事了。",
  ui_story_5031_50310802_13_dialog_content = "到時候想做些什麼呢？",
  ui_story_5031_50310802_14_dialog_content = "或許，在大陸各地開辦可以用餐的高檔美術館吧。",
  ui_story_5031_50310802_15_dialog_content = "你竟然還記得這個約定？",
  ui_story_5031_50310802_16_dialog_content = "我還以為過了這麼多年，你已經忘了。",
  ui_story_5031_50310802_17_dialog_content = "我全都記著呢，包括你曾經答應會給我畫畫像這件事。",
  ui_story_5031_50310802_18_dialog_content = "好泊城美術館的領主畫像牆上，至今還缺一幅。",
  ui_story_5031_50310802_19_dialog_content = "……",
  ui_story_5031_50310802_20_dialog_content = "那，有什麼我能幫上忙的嗎？",
  ui_story_5031_50310802_21_dialog_content = "什麼？",
  ui_story_5031_50310802_22_dialog_content = "「摩德利失能症」，有什麼我能幫上忙的嗎？",
  ui_story_5031_50310802_23_dialog_content = "……",
  ui_story_5031_50310802_24_dialog_content = "其實……",
  ui_story_5031_50310802_25_dialog_content = "喔！！虹霞小姐太強了！",
  ui_story_5031_50310802_26_dialog_content = "動作上結合了美感與力量感，簡直完美！",
  ui_story_5031_50310802_27_dialog_content = "......你剛剛說什麼？",
  ui_story_5031_50310802_28_dialog_content = "沒什麼，我們先看比賽吧。",
  ui_story_5031_50310802_29_dialog_content = "得做好裁判的本職工作，才對得起場上拼搏的選手們。",
  ui_story_5031_50310802_30_dialog_content = "虹，虹霞小姐好強啊，但是有點可怕......",
  ui_story_5031_50310802_31_dialog_content = "的......的確。",
  ui_story_5031_50310802_32_dialog_content = "小豆芽菜，不可以這樣說虹霞姐喔。",
  ui_story_5031_50310802_33_dialog_content = "是喔是喔～就算是梅爾姐在意的人也不行～",
  ui_story_5031_50310802_34_dialog_content = "啊，不好意思，我們不是那個意思！",
  ui_story_5031_50310802_35_dialog_content = "只是對她昂揚的鬥志表示一種敬佩和震驚......",
  ui_story_5031_50310802_36_dialog_content = "薩布，不要搗亂啦......",
  ui_story_5031_50310802_37_dialog_content = "虹霞姐她，是因為憎恨暗鬼，所以才會這樣......",
  ui_story_5031_50310802_38_dialog_content = "憎恨暗鬼？",
  ui_story_5031_50310802_39_dialog_content = "唔......",
  ui_story_5031_50310802_40_dialog_content = "因為虹霞姐她的家鄉就是被暗鬼毀滅的。",
  ui_story_5031_50310802_41_dialog_content = "是的，虹霞姐的朋友和家人都不在了。",
  ui_story_5031_50310802_42_dialog_content = "所以虹霞姐見到暗鬼就會變成這個樣子。",
  ui_story_5031_50310802_43_dialog_content = "但是虹霞姐平時人非常好，只會對暗鬼這樣。",
  ui_story_5031_50310802_44_dialog_content = "嗯，菲爾姆最喜歡虹霞姐了！",
  ui_story_5031_50310802_45_dialog_content = "我也是，虹霞姐比那個天天兇巴巴的團長要好太多啦～",
  ui_story_5031_50310802_46_dialog_content = "團，團長人也很好的......",
  ui_story_5031_50310802_47_dialog_content = "只有梅爾姐這麼認為！",
  ui_story_5031_50310802_48_dialog_content = "竟然是因為這個原因嗎......",
  ui_story_5031_50310802_49_dialog_content = "虹霞小姐平時都那麼陽光開朗，實在沒有想到她竟然還有這樣的過往......",
  ui_story_5031_50310802_50_dialog_content = "以悲傷和憤怒為動力，反而茁壯成長成為了太陽花一般燦爛的女性。",
  ui_story_5031_50310802_51_dialog_content = "非常值得尊敬。",
  ui_story_5031_50310802_52_dialog_content = "妳說得對，但是我還是有點慶幸自己沒有第一個上場......",
  ui_story_5031_50310802_53_dialog_content = "這麼說起來，菲雅呢？",
  ui_story_5031_50310802_54_dialog_content = "你，你們不要四面八方地頂我的衝浪板啦！",
  ui_story_5031_50310802_55_dialog_content = "要從一個方向來！",
  ui_story_5031_50310802_56_dialog_content = "哎呀，方向反了反了！不是那邊啦......哇啊！",
  ui_story_5031_50310802_57_dialog_content = "<color=#e8d9bb>噗通——</color>",
  ui_story_5031_50310802_58_dialog_content = "哈哈哈哈，那個小姑娘，怎麼自己在原地還能轉起圈來了？",
  ui_story_5031_50310802_59_dialog_content = "而且自己轉著轉著還落水了，這下想拿動作分肯定沒戲了。",
  ui_story_5031_50310802_60_dialog_content = "噗！咳咳咳......",
  ui_story_5031_50310802_61_dialog_content = "你，你們這群笨蛋魚群！",
  ui_story_5031_50310802_62_dialog_content = "PlayerName那個傢伙，等下一定會笑話我的......嗚嗚。",
  ui_story_5031_50310802_63_dialog_content = "我已經預想到菲雅這傢伙，一定在擔心我等下會笑話她了。",
  ui_story_5031_50310802_64_dialog_content = "但是......噗！",
  ui_story_5031_50310802_65_dialog_content = "真的好好笑啊，哈哈哈哈哈！",
  ui_story_5031_50310802_66_dialog_content = "PlayerName，你笑太大聲啦。",
  ui_story_5031_50310802_67_dialog_content = "是我的錯，沒有預想到菲雅與魚群的協調性會存在問題。",
  ui_story_5031_50310802_68_dialog_content = "想利用她與動物溝通的能力，指揮魚群推動衝浪板還是太過不現實了。",
  ui_story_5031_50310802_69_dialog_content = "不不，是菲雅她自己打包票說一定沒問題的。",
  ui_story_5031_50310802_70_dialog_content = "卡蓮你不要總是把責任往自己身上攬啊，只是一場遊戲而已，不需要太認真。",
  ui_story_5031_50310802_71_dialog_content = "......嗯。",
  ui_story_5031_50310802_72_dialog_content = "講解一下賽況吧——如果您還擁有珍貴的雙眼，相信您一定也能看得出來。",
  ui_story_5031_50310802_73_dialog_content = "現在場上最出彩的就是來自我們馬戲團的虹霞，和來自啟光的琪爾小姐。",
  ui_story_5031_50310802_74_dialog_content = "二人擊殺暗鬼的數量難分伯仲，動作評分目前也是領先於其他所有人。",
  ui_story_5031_50310802_75_dialog_content = "但是以現場觀眾評審團的態度來看，虹霞的動作設計還是略勝一籌。",
  ui_story_5031_50310802_76_dialog_content = "那麼，其餘十八位毫無亮點的平凡普通人，你們加油。",
  ui_story_5031_50310802_77_dialog_content = "繼續在這浪濤翻湧的世間掙扎沉浮吧。",
  ui_story_5031_50310802_78_dialog_content = "……",
  ui_story_5031_50310802_79_dialog_content = "你你你，你給我等著！",
  ui_story_5031_50310802_80_dialog_content = "滾回海底去吧！",
  ui_story_5031_50310802_81_dialog_content = "嘎嘎！",
  ui_story_5031_50310802_82_dialog_content = "呼～雖然知道是幻象，但還是忍不住呢。",
  ui_story_5031_50310802_83_dialog_content = "清除完畢以後心情好多了！",
  ui_story_5031_50310802_84_dialog_content = "好，好強......",
  ui_story_5031_50310802_85_dialog_content = "嗯？妳也不差嘛！",
  ui_story_5031_50310802_86_dialog_content = "竟然能跟我這個從小玩水到大的人不相上下，我對妳另眼相看喔！",
  ui_story_5031_50310802_87_dialog_content = "不，我只是靠著不停地攻擊暗鬼拿分而已。",
  ui_story_5031_50310802_88_dialog_content = "實際上衝浪的技術分根本沒有多高。",
  ui_story_5031_50310802_89_dialog_content = "只是利用規則投機取巧而已......",
  ui_story_5031_50310802_90_dialog_content = "唔，小琪爾真是，好奇怪啊。",
  ui_story_5031_50310802_91_dialog_content = "奇，奇怪？",
  ui_story_5031_50310802_92_dialog_content = "你看，我明明在誇妳，妳卻不停地在說自己不好，表情也很難過。",
  ui_story_5031_50310802_93_dialog_content = "攻擊暗鬼得分，這不是很正常的規則嗎？為什麼要說是投機取巧呢？",
  ui_story_5031_50310802_94_dialog_content = "……",
  ui_story_5031_50310802_95_dialog_content = "小琪爾呀，明明挺能幹的，為什麼不多相信自己一點？",
  ui_story_5031_50310802_96_dialog_content = "總是這樣緊繃繃的，能做好的事都會反而失敗喔～",
  ui_story_5031_50310802_97_dialog_content = "我......",
  ui_story_5031_50310802_98_dialog_content = "嘎！",
  ui_story_5031_50310802_99_dialog_content = "又有暗鬼！別想跑！",
  ui_story_5031_50310802_100_dialog_content = "我......能幹？",
  ui_story_5031_50310802_101_dialog_content = "嘿嘿......嘿嘿嘿。",
  ui_story_5031_50310802_102_dialog_content = "既然如此，那絕對不能讓虹霞小姐失望！",
  ui_story_5031_50310802_103_dialog_content = "「手臂機甲狀態調整——Ⅱ型」！",
  ui_story_5031_50310802_104_dialog_content = "「能源釋放百分比提高至60%」！",
  ui_story_5031_50310802_105_dialog_content = "<color=#e8d9bb>轟——</color>",
  ui_story_5031_50310802_106_dialog_content = "琪......琪爾？！",
  ui_story_5031_50310802_107_dialog_content = "她又提高了能源釋放比嗎？",
  ui_story_5031_50310802_108_dialog_content = "可是「斯提克斯」現在......",
  ui_story_5031_50310802_109_dialog_content = "哇！那個機甲小女孩怎麼忽然對著海面噴射這麼大的能源啊？",
  ui_story_5031_50310802_110_dialog_content = "唔哇，連船都晃動了，不會翻船吧......",
  ui_story_5031_50310802_111_dialog_content = "她飛到空中了！是想借力做跳躍旋轉拿動作分嗎？",
  ui_story_5031_50310802_112_dialog_content = "不，不對，那是......",
  ui_story_5031_50310802_113_dialog_content = "暗鬼！海裡的暗鬼都被掀翻出來了！",
  ui_story_5031_50310802_114_dialog_content = "哇！這是......",
  ui_story_5031_50310802_115_dialog_content = "這力量，也太酷了吧！",
  ui_story_5031_50310802_116_dialog_content = "既然我不太會高難度的動作，那就靠剩下50%的分數吧！",
  ui_story_5031_50310802_117_dialog_content = "「斯提克斯」，掃射！",
  ui_story_5031_50310802_118_dialog_content = "但是機甲的能源輸出功率很大，可以有效做到大範圍進攻。",
  ui_story_5031_50310802_119_dialog_content = "嗯，由於機甲比較笨重，所以無法做出輕盈的動作。",
  ui_story_5031_50310802_120_dialog_content = "琪爾利用這個優勢，瞬間擊殺大量暗鬼，現在得分已經反超了。",
  ui_story_5031_50310802_121_dialog_content = "逆境中仍然能找到突破口，非常值得尊敬。",
  ui_story_5031_50310802_122_dialog_content = "那麼就請領主大人給她計分吧。",
  ui_story_5031_50310802_123_dialog_content = "呵，好的團長大人。",
  ui_story_5031_50310802_124_dialog_content = "這，這樣就......",
  ui_story_5031_50310802_125_dialog_content = "<color=#e8d9bb>喀、喀！</color>",
  ui_story_5031_50310802_126_dialog_content = "咦？",
  ui_story_5031_50310802_127_dialog_content = "糟了，果然「斯提克斯」沒能承載住這麼大的能源輸出......",
  ui_story_5031_50310802_128_dialog_content = "哇啊啊！要、要掉下去了！",
  ui_story_5031_50310802_129_dialog_content = "小琪爾！",
  ui_story_5031_50310802_130_dialog_content = "嘿咻～！",
  ui_story_5031_50310802_131_dialog_content = "咦？虹霞小姐？",
  ui_story_5031_50310802_132_dialog_content = "唔......",
  ui_story_5031_50310802_133_dialog_content = "睜開眼吧，接住妳了喔～",
  ui_story_5031_50310802_134_dialog_content = "嗯？",
  ui_story_5031_50310802_135_dialog_content = "虹，虹霞小姐？",
  ui_story_5031_50310802_136_dialog_content = "妳剛剛可真亂來啊，明明機甲還沒有調試好，竟然還用那麼大的輸出功率。",
  ui_story_5031_50310802_137_dialog_content = "抱......抱歉。",
  ui_story_5031_50310802_138_dialog_content = "因為之前「斯提克斯」經歷過一次爆炸，還沒有徹底修好。",
  ui_story_5031_50310802_139_dialog_content = "給虹霞小姐添麻煩了......",
  ui_story_5031_50310802_140_dialog_content = "這樣啊，好可惜！",
  ui_story_5031_50310802_141_dialog_content = "不過等它徹底修好，一定很厲害的！好期待啊～",
  ui_story_5031_50310802_142_dialog_content = "……",
  ui_story_5031_50310802_143_dialog_content = "那個，虹霞小姐。",
  ui_story_5031_50310802_144_dialog_content = "嗯？怎麼啦？",
  ui_story_5031_50310802_145_dialog_content = "妳為什麼要救我呀，明明我掉入海裡的話，一定會被扣很多動作分。",
  ui_story_5031_50310802_146_dialog_content = "咦？唔，這個嘛......",
  ui_story_5031_50310802_147_dialog_content = "大概是因為，比起那五百萬白夜幣——",
  ui_story_5031_50310802_148_dialog_content = "我對妳更感興趣吧～",
  ui_story_5031_50310901_1_dialog_content = "第一輪比賽結束，現在請第二輪要上場的選手到指定起點位置。",
  ui_story_5031_50310901_2_dialog_content = "等待期間，會統計核算上一輪的評分。",
  ui_story_5031_50310901_3_dialog_content = "小菲雅，不要太難過，沒關係的，我們還有機會。",
  ui_story_5031_50310901_4_dialog_content = "是呀是呀，妳不用有壓力，本來也沒有指望妳能拿高分的。",
  ui_story_5031_50310901_5_dialog_content = "嗚哇啊啊啊！",
  ui_story_5031_50310901_6_dialog_content = "PlayerName你這個笨蛋！",
  ui_story_5031_50310901_7_dialog_content = "啊？我又怎麼了？",
  ui_story_5031_50310901_8_dialog_content = "我，我只是在安慰妳啊。",
  ui_story_5031_50310901_9_dialog_content = "好了好了，PlayerName你先別說話了。",
  ui_story_5031_50310901_10_dialog_content = "......我好委屈啊。",
  ui_story_5031_50310901_11_dialog_content = "大家，要準備下一輪了。",
  ui_story_5031_50310901_12_dialog_content = "我剛剛聽到虹霞她們那邊說，下一場會是梅爾特上場。",
  ui_story_5031_50310901_13_dialog_content = "嗯？菲雅妳怎麼了？",
  ui_story_5031_50310901_14_dialog_content = "嗚嗚嗚，卡蓮姐姐，PlayerName他、他......",
  ui_story_5031_50310901_15_dialog_content = "停停停，我什麼都沒做好吧！",
  ui_story_5031_50310901_16_dialog_content = "菲雅，我們先準備下一輪比賽好不好？",
  ui_story_5031_50310901_17_dialog_content = "菲雅也很想要獎......泳裝，「海雲鯨」也需要我們拯救，對吧？",
  ui_story_5031_50310901_18_dialog_content = "嗚嗚......嗯......",
  ui_story_5031_50310901_19_dialog_content = "那菲雅就擦乾眼淚，我們一起討論下一場的出場順序吧～",
  ui_story_5031_50310901_20_dialog_content = "那......我提議下一場讓PlayerName哥哥上場呢！",
  ui_story_5031_50310901_21_dialog_content = "啊？！",
  ui_story_5031_50310901_22_dialog_content = "哼哼，你剛剛一定趁菲雅落水的時候嘲笑了菲雅對吧！",
  ui_story_5031_50310901_23_dialog_content = "這次輪到菲雅來嘲笑你啦！",
  ui_story_5031_50310901_24_dialog_content = "妳怎麼知道我剛剛嘲笑妳了......不是，妳這是什麼邏輯啊！",
  ui_story_5031_50310901_25_dialog_content = "重點難道不是贏得比賽嗎？",
  ui_story_5031_50310901_26_dialog_content = "反正只要兩個成績，壓根就不用我上場才對吧？",
  ui_story_5031_50310901_27_dialog_content = "你忘了嗎PlayerName？你和菲雅可是算作一個人的。",
  ui_story_5031_50310901_28_dialog_content = "所以你們兩個的成績，是按照總和計算的。",
  ui_story_5031_50310901_29_dialog_content = "......好，好像確實有這麼一回事。",
  ui_story_5031_50310901_30_dialog_content = "現在也無法判斷我和薇絲上場時候會不會遇到什麼強敵。",
  ui_story_5031_50310901_31_dialog_content = "所以，最好還是你也上場比較保險。",
  ui_story_5031_50310901_32_dialog_content = "這麼說的話，好像下一輪讓PlayerName上場，也是個不錯的選擇？",
  ui_story_5031_50310901_33_dialog_content = "確實，畢竟那三胞胎裡性格最溫和的估計就是梅爾特了。",
  ui_story_5031_50310901_34_dialog_content = "而且貢露長官給人的感覺應該也不會太擅長衝浪。",
  ui_story_5031_50310901_35_dialog_content = "那這麼看來......",
  ui_story_5031_50310901_36_dialog_content = "這麼看來......",
  ui_story_5031_50310901_37_dialog_content = "......我知道了，我上場就是了，妳們別盯著我看了。",
  ui_story_5031_50310901_38_dialog_content = "嘿嘿，PlayerName加油喔～",
  ui_story_5031_50310901_39_dialog_content = "不要有太大心理壓力，記住我們之前教給你的訣竅就好。",
  ui_story_5031_50310901_40_dialog_content = "就算做不到也沒有關係。",
  ui_story_5031_50310901_41_dialog_content = "嗯，我知道了。",
  ui_story_5031_50310901_42_dialog_content = "哼哼，PlayerName可不要給菲雅拖後腿！",
  ui_story_5031_50310901_43_dialog_content = "妳自己的分數也沒有多高吧！",
  ui_story_5031_50310901_44_dialog_content = "趁著我們宣布成績的時候，還沒有到起點的選手抓緊時間。",
  ui_story_5031_50310901_45_dialog_content = "上一輪成績最好的是——虹霞。",
  ui_story_5031_50310901_46_dialog_content = "哼，不愧是我們馬戲團的得力幹將，完全不出所料。",
  ui_story_5031_50310901_47_dialog_content = "虹霞小姐——！！",
  ui_story_5031_50310901_48_dialog_content = "不過，接下來的這位恐怕會出乎大家的預料。",
  ui_story_5031_50310901_49_dialog_content = "竟然有一人的成績與虹霞並列排名第一——琪爾小姐。",
  ui_story_5031_50310901_50_dialog_content = "哇！是那個機甲小姑娘吧？",
  ui_story_5031_50310901_51_dialog_content = "這麼厲害，竟然追上了虹霞小姐的分數！",
  ui_story_5031_50310901_52_dialog_content = "哇！小琪爾，妳好厲害啊！",
  ui_story_5031_50310901_53_dialog_content = "謝謝貢露長官。",
  ui_story_5031_50310901_54_dialog_content = "貢露長官？妳為什麼會在這裡！",
  ui_story_5031_50310901_55_dialog_content = "妳還不去起點準備嗎？",
  ui_story_5031_50310901_56_dialog_content = "嘿嘿，那是因為......",
  ui_story_5031_50310901_57_dialog_content = "我猜你們肯定想讓PlayerName和梅爾特還有我進行比賽。",
  ui_story_5031_50310901_58_dialog_content = "這樣的話，你們兩個的比賽就會少一個阻力對吧？",
  ui_story_5031_50310901_59_dialog_content = "……",
  ui_story_5031_50310901_60_dialog_content = "啊，這......",
  ui_story_5031_50310901_61_dialog_content = "既然如此，那肯定不能讓你們得逞啦～！",
  ui_story_5031_50310901_62_dialog_content = "呼，不要緊張。",
  ui_story_5031_50310901_63_dialog_content = "這一輪明顯人少了很多，我只要能穩住就夠了。",
  ui_story_5031_50310901_64_dialog_content = "PlayerName，那個......",
  ui_story_5031_50310901_65_dialog_content = "怎麼啦梅爾特？",
  ui_story_5031_50310901_66_dialog_content = "唔......你，你的衝浪板繩子，沒有綁在自己身上。",
  ui_story_5031_50310901_67_dialog_content = "很危險的......",
  ui_story_5031_50310901_68_dialog_content = "哦！我忘記了。",
  ui_story_5031_50310901_69_dialog_content = "謝謝妳啊梅爾特！幫大忙了。",
  ui_story_5031_50310901_70_dialog_content = "......唔！",
  ui_story_5031_50310901_71_dialog_content = "哇，一頭扎進水裡不見了！",
  ui_story_5031_50310901_72_dialog_content = "是我又說錯了什麼嗎？",
  ui_story_5031_50310901_73_dialog_content = "嗯，時間差不多了。",
  ui_story_5031_50310901_74_dialog_content = "那第二輪開始吧。",
  ui_story_5031_50310901_75_dialog_content = "哈哈哈哈，又是這麼隨意的開場。",
  ui_story_5031_50310901_76_dialog_content = "這就是馬戲團團長的風格嗎？",
  ui_story_5031_50310901_77_dialog_content = "唷，這一輪沒有機甲了，沒有上一局精彩啊。",
  ui_story_5031_50310901_78_dialog_content = "嗯？你們看！那個馬戲團的三胞胎小丫頭......",
  ui_story_5031_50310901_79_dialog_content = "她的動作竟然比虹霞小姐還要優美！",
  ui_story_5031_50310901_80_dialog_content = "當然，梅爾特可是馬戲團裡肢體平衡和掌握力最強的人之一。",
  ui_story_5031_50310901_81_dialog_content = "空中飛人和吊環體操都能完成得完美無瑕，區區衝浪不在話下。",
  ui_story_5031_50310901_82_dialog_content = "你對馬戲團裡每一個人的事都瞭若指掌呢。",
  ui_story_5031_50310901_83_dialog_content = "嗯，他們不光是為馬戲團演出的演員。",
  ui_story_5031_50310901_84_dialog_content = "更是馬戲團這個大家庭的一員。",
  ui_story_5031_50310901_85_dialog_content = "……",
  ui_story_5031_50310901_86_dialog_content = "這句話，讓我有點想起了以前的你。",
  ui_story_5031_50310901_87_dialog_content = "是嗎，想起了以前那個只會依賴家人和「艾維斯哥哥」的廢柴嗎？",
  ui_story_5031_50310901_88_dialog_content = "不，是那個會為了掉出巢的小鳥而哭鼻子的善良孩子。",
  ui_story_5031_50310901_89_dialog_content = "最後為了將牠送回去而爬上樹，還摔斷了手臂打了半年石膏。",
  ui_story_5031_50310901_90_dialog_content = "你還是這樣，每個人都要操心，沒辦法做到不去在意。",
  ui_story_5031_50310901_91_dialog_content = "你就別提我這些糗事了。",
  ui_story_5031_50310901_92_dialog_content = "好好看比賽。",
  ui_story_5031_50310901_93_dialog_content = "呵呵，知道了。",
  ui_story_5031_50310902_1_dialog_content = "毫無懸念，第二輪成績最高的依然是我們馬戲團的成員——",
  ui_story_5031_50310902_2_dialog_content = "梅爾特。",
  ui_story_5031_50310902_3_dialog_content = "噢噢噢噢！",
  ui_story_5031_50310902_4_dialog_content = "這就是她夜以繼日，在星輝見證之下揮灑汗水的成果。",
  ui_story_5031_50310902_5_dialog_content = "希望她的成功，能給你們這些木訥腐朽的懶惰靈魂帶來一些刺激。",
  ui_story_5031_50310902_X5_dialog_content = "……",
  ui_story_5031_50310902_X6_dialog_content = "哼，自慚形愧到無言以對了嗎？也罷，並不是所有人都有人生追求。",
  ui_story_5031_50310902_X7_dialog_content = "那麼，第三輪參賽選手，去起點準備吧。",
  ui_story_5031_50310902_X8_dialog_content = "第三組選手準備。",
  ui_story_5031_50310902_6_dialog_content = "第三輪參賽選手，去起點準備吧。",
  ui_story_5031_50310902_7_dialog_content = "欸～不會吧，PlayerName居然能拿到零分嗎？",
  ui_story_5031_50310902_8_dialog_content = "在某種方面來說已經達到了常人所不能及的水準了呢。",
  ui_story_5031_50310902_9_dialog_content = "如果沒有薇絲姐姐和卡蓮姐姐，都不知道「海雲鯨」的事該怎麼辦了呢。",
  ui_story_5031_50310902_10_dialog_content = "嗚嗚......妳別說了。",
  ui_story_5031_50310902_11_dialog_content = "生而為空裔，我很抱歉。",
  ui_story_5031_50310902_12_dialog_content = "菲雅不要太責怪PlayerName啦。",
  ui_story_5031_50310902_13_dialog_content = "初學者想一天學會衝浪，確實不太現實呢。",
  ui_story_5031_50310902_14_dialog_content = "我們會把分數追回來的，不用太擔心。",
  ui_story_5031_50310902_15_dialog_content = "薇絲姐姐和卡蓮姐姐真的很可靠呢！",
  ui_story_5031_50310902_16_dialog_content = "唉～PlayerName哥哥也要多努力呀。",
  ui_story_5031_50310902_17_dialog_content = "不拿你開玩笑啦，打起精神來～等菲雅學會了衝浪就和卡蓮姐姐一起手把手教你！",
  ui_story_5031_50310902_18_dialog_content = "啊哈哈......還真是謝謝呢。",
  ui_story_5031_50310902_19_dialog_content = "嗯哼～儘管感謝我吧。",
  ui_story_5031_50310902_20_dialog_content = "那，那個，PlayerName......",
  ui_story_5031_50310902_21_dialog_content = "咦？是梅爾特，怎麼了嗎？",
  ui_story_5031_50310902_22_dialog_content = "唔......",
  ui_story_5031_50310902_23_dialog_content = "薩布莉來說吧！",
  ui_story_5031_50310902_24_dialog_content = "梅爾姐想向PlayerName道歉喔，因為剛剛差點誤傷到了你！",
  ui_story_5031_50310902_25_dialog_content = "哦，這個呀。沒事啦！妳完全沒有傷到我喔，梅爾特。",
  ui_story_5031_50310902_26_dialog_content = "只是我自己嚇了一跳，所以嗆了兩口水而已。",
  ui_story_5031_50310902_27_dialog_content = "唔......嗯......",
  ui_story_5031_50310902_28_dialog_content = "PlayerName真的好溫柔啊，和老大完全不一樣！",
  ui_story_5031_50310902_29_dialog_content = "這麼溫柔的話豆芽菜身材也不是完全無法接受了，難怪梅爾姐會喜......唔！",
  ui_story_5031_50310902_30_dialog_content = "菲，菲爾姆！",
  ui_story_5031_50310902_31_dialog_content = "妳該準備去起點了，快......快走吧！",
  ui_story_5031_50310902_32_dialog_content = "唔唔唔！",
  ui_story_5031_50310902_33_dialog_content = "啊，等等薩布莉！",
  ui_story_5031_50310902_34_dialog_content = "哦？",
  ui_story_5031_50310902_35_dialog_content = "PlayerName真的很受歡迎呢。",
  ui_story_5031_50310902_36_dialog_content = "……",
  ui_story_5031_50310902_37_dialog_content = "啊？妳在說什麼？",
  ui_story_5031_50310902_38_dialog_content = "沒什麼～",
  ui_story_5031_50310902_39_dialog_content = "我也得快去準備了呢，馬上要開始了！",
  ui_story_5031_50310902_40_dialog_content = "嗯，走吧。",
  ui_story_5031_50310902_41_dialog_content = "......什麼嘛，神神祕祕的。",
  ui_story_5031_50310902_42_dialog_content = "我們也過去海邊吧，菲......",
  ui_story_5031_50310902_43_dialog_content = "欸？菲雅？",
  ui_story_5031_50310902_44_dialog_content = "......真是的，一個兩個都怎麼回事？",
  ui_story_5031_50310902_45_dialog_content = "第三輪，規則都知道了，開始吧。",
  ui_story_5031_50310902_46_dialog_content = "速射感知！",
  ui_story_5031_50310902_47_dialog_content = "哦～好淩厲的攻勢呢。",
  ui_story_5031_50310902_48_dialog_content = "看來菲爾姆也要認真起來了～不要小看了偷偷特訓過的我喔。",
  ui_story_5031_50310902_49_dialog_content = "咳咳......咳咳咳！",
  ui_story_5031_50310902_50_dialog_content = "艾維斯，你的藥呢？！",
  ui_story_5031_50310902_51_dialog_content = "在我......外衣內側的口袋。",
  ui_story_5031_50310902_52_dialog_content = "記得，把擴音器關掉......咳咳！",
  ui_story_5031_50310902_53_dialog_content = "嗯，我知道，已經關掉了。",
  ui_story_5031_50310902_54_dialog_content = "你確定在外衣口袋嗎？我找不到。",
  ui_story_5031_50310902_55_dialog_content = "唔......咳咳咳！",
  ui_story_5031_50310902_56_dialog_content = "抱歉，你有，手帕嗎？",
  ui_story_5031_50310902_57_dialog_content = "有，你等等。",
  ui_story_5031_50310902_58_dialog_content = "<color=#e8d9bb>叮當——</color>",
  ui_story_5031_50310902_59_dialog_content = "嘖，雜七雜八的東西太多了......",
  ui_story_5031_50310902_60_dialog_content = "你們能不能安分點，不要在這種時候掉出來添亂？",
  ui_story_5031_50310902_61_dialog_content = "……",
  ui_story_5031_50310902_62_dialog_content = "給。",
  ui_story_5031_50310902_63_dialog_content = "多謝......咳咳。",
  ui_story_5031_50310902_64_dialog_content = "哇！這一輪很精彩嘛，能打的選手很多喔！",
  ui_story_5031_50310902_65_dialog_content = "哦！又幹掉了一個暗鬼！",
  ui_story_5031_50310902_66_dialog_content = "那個用弓箭的小姑娘很厲害嘛！",
  ui_story_5031_50310902_67_dialog_content = "……",
  ui_story_5031_50310902_68_dialog_content = "抱歉，能麻煩你扶我去旁邊人少的地方休息一下嗎？",
  ui_story_5031_50310902_69_dialog_content = "好，稍等。",
  ui_story_5031_50310902_70_dialog_content = "那邊的小丑，你過來一下！",
  ui_story_5031_50310902_71_dialog_content = "對就是你。",
  ui_story_5031_50310902_72_dialog_content = "團長，什麼事？",
  ui_story_5031_50310902_73_dialog_content = "你先負責統計一下分數，我們去談點事。",
  ui_story_5031_50310902_74_dialog_content = "成交！",
  ui_story_5031_50310902_75_dialog_content = "你不用這副表情，我沒什麼事了。",
  ui_story_5031_50310902_76_dialog_content = "沒事？你剛剛可是抓著我，咳了我一身血。",
  ui_story_5031_50310902_77_dialog_content = "抱歉，弄髒你的衣服了。",
  ui_story_5031_50310902_78_dialog_content = "你知道我在意的不是這個。",
  ui_story_5031_50310902_79_dialog_content = "別擔心，這不是證明我體內含生命值比較高嗎，反而是健康的體現。",
  ui_story_5031_50310902_80_dialog_content = "......別扯了。",
  ui_story_5031_50310902_81_dialog_content = "你之前說的解決方案，真的不能告訴我嗎？",
  ui_story_5031_50310902_82_dialog_content = "如果你願意相信我，我會幫你完成。",
  ui_story_5031_50310902_83_dialog_content = "……",
  ui_story_5031_50310902_84_dialog_content = "妳這是什麼表情？",
  ui_story_5031_50310902_85_dialog_content = "沒什麼，只是你剛剛說的這句話，一瞬間又讓我想起來了小時候。",
  ui_story_5031_50310902_86_dialog_content = "不會又是什麼我的糗事吧？",
  ui_story_5031_50310902_87_dialog_content = "唔，小時候你雖然比我矮小，比我瘦弱，但是卻總是想要盡力幫助別人，幫助我。",
  ui_story_5031_50310902_88_dialog_content = "那時候，你的眼神和剛剛一模一樣，絲毫未變。",
  ui_story_5031_50310902_89_dialog_content = "歲月或許可以在面容和軀體上刻下印記，但是卻不能改變靈魂。",
  ui_story_5031_50310902_90_dialog_content = "是啊，有很多東西，是不會變的。",
  ui_story_5031_50310902_91_dialog_content = "比如你還是比我矮這件事。",
  ui_story_5031_50310902_92_dialog_content = "嘖，但是你現在這個體格，我一個人可以打十個你。",
  ui_story_5031_50310902_93_dialog_content = "是啊，如今你再也不是那個需要我保護的傑諾了。",
  ui_story_5031_50310902_94_dialog_content = "我如今這副樣子，也保護不了你了。",
  ui_story_5031_50310902_95_dialog_content = "......那麼就換我保護你。",
  ui_story_5031_50310902_96_dialog_content = "呵呵，這可不是隨便說說而已的事。",
  ui_story_5031_50310902_97_dialog_content = "我是認真的，艾維斯。",
  ui_story_5031_50310902_98_dialog_content = "如果你願意告訴我你說的方法到底是什麼，只要能做到的事我一定會去做。",
  ui_story_5031_50310902_99_dialog_content = "那麼，假如這件事會涉及到你背後的組織呢？",
  ui_story_5031_50310902_100_dialog_content = "......？",
  ui_story_5031_50310902_101_dialog_content = "假如——我是說假如，這件事，需要你的船，需要它最深處的某樣東西呢？",
  ui_story_5031_50310902_102_dialog_content = "你還會願意幫我嗎？",
  ui_story_5031_50310902_103_dialog_content = "......你怎麼知道的？",
  ui_story_5031_50310902_104_dialog_content = "這不重要，傑諾。",
  ui_story_5031_50310902_105_dialog_content = "重要的是，我們已經不再是孩子了，沒有辦法回到那時候簡簡單單無憂無慮的快樂。",
  ui_story_5031_50310902_106_dialog_content = "現在的每一個決定，每一個承諾，每說的一個字，都背負了太多太多。",
  ui_story_5031_50310902_107_dialog_content = "所以我再問你，你願意幫我嗎？",
  ui_story_5031_50310902_108_dialog_content = "……",
  ui_story_5031_50310902_109_dialog_content = "我......我曾經，發過誓。",
  ui_story_5031_50310902_110_dialog_content = "我發過誓，會保護好這艘船，保護那個東西。",
  ui_story_5031_50310902_111_dialog_content = "......我明白了，抱歉，讓你感到為難了。",
  ui_story_5031_50310902_112_dialog_content = "走吧，我們也該回去主持賽況了——那邊的小丑先生，已經手忙腳亂了。",
  ui_story_5031_50310902_113_dialog_content = "艾維斯，我......",
  ui_story_5031_50310902_114_dialog_content = "傑諾。",
  ui_story_5031_50310902_115_dialog_content = "……",
  ui_story_5031_50310902_116_dialog_content = "不用再說了，我全都理解。",
  ui_story_5031_50310902_117_dialog_content = "不過不管怎樣，我想讓你知道......",
  ui_story_5031_50310902_118_dialog_content = "這十幾年以來，我一直都很想你。",
  ui_story_5031_50310902_119_dialog_content = "......！",
  ui_story_5031_50311001_1_dialog_content = "卡蓮殿下。",
  ui_story_5031_50311001_2_dialog_content = "馬太閣下？有什麼事嗎？",
  ui_story_5031_50311001_3_dialog_content = "您還要繼續參加這場鬧劇嗎？",
  ui_story_5031_50311001_4_dialog_content = "和這麼多庶民一起泡在水裡，真是......太噁心了。",
  ui_story_5031_50311001_5_dialog_content = "是的，我並不介意。",
  ui_story_5031_50311001_6_dialog_content = "如果你認為噁心，大可以站在沙灘上或船上觀戰，或者直接回白夜城去。",
  ui_story_5031_50311001_7_dialog_content = "嘖，妳這個讓人惱火的姿......",
  ui_story_5031_50311001_8_dialog_content = "馬太。",
  ui_story_5031_50311001_9_dialog_content = "......哼，麻煩，我為什麼要保護這樣一個任性的公主殿下。",
  ui_story_5031_50311001_10_dialog_content = "……",
  ui_story_5031_50311001_11_dialog_content = "馬太閣下，我不是什麼任性的公主殿下，也不需要你的保護。",
  ui_story_5031_50311001_12_dialog_content = "如果是因為不會游泳這件事讓你感到煩躁，你大可以放心，我不會出任何事。",
  ui_story_5031_50311001_13_dialog_content = "噗。",
  ui_story_5031_50311001_14_dialog_content = "妳，妳說什麼？！",
  ui_story_5031_50311001_15_dialog_content = "說誰不會游泳啊，不就是游泳嗎？庶民都會的東西我怎麼可能不會！",
  ui_story_5031_50311001_16_dialog_content = "還，還有洛維你這個傢伙，你在偷笑什麼？我都聽到了！",
  ui_story_5031_50311001_17_dialog_content = "你確實不會。",
  ui_story_5031_50311001_18_dialog_content = "......啊啊啊，你這傢伙！",
  ui_story_5031_50311001_19_dialog_content = "夠了，我受夠了！性格惡劣的公主殿下，妳會後悔和庶民混在一起的！",
  ui_story_5031_50311001_20_dialog_content = "我要回去更衣沐浴了！",
  ui_story_5031_50311001_21_dialog_content = "……",
  ui_story_5031_50311001_22_dialog_content = "......他們是來幹什麼的？",
  ui_story_5031_50311001_23_dialog_content = "大概是因為他不敢下水，所以也想阻止我參加這場比賽吧。",
  ui_story_5031_50311001_24_dialog_content = "真是的，不知道伊倫汀大人到底為什麼讓他來跟著我......",
  ui_story_5031_50311001_25_dialog_content = "薇絲姐姐！妳回來啦！",
  ui_story_5031_50311001_26_dialog_content = "薇絲，歡迎回來。",
  ui_story_5031_50311001_27_dialog_content = "剛剛薇絲姐姐妳好棒啊，妳的分數一定很高呢！",
  ui_story_5031_50311001_28_dialog_content = "這下「海雲鯨」一定屬於我們了！我總算可以不用聽師父嘮叨了！",
  ui_story_5031_50311001_29_dialog_content = "小菲雅也不要抱太大期望了。",
  ui_story_5031_50311001_30_dialog_content = "剛剛的對手也都很強勁呢。",
  ui_story_5031_50311001_31_dialog_content = "沒有想到貢露長官竟然會這麼擅長衝浪，太大意了！",
  ui_story_5031_50311001_32_dialog_content = "沒關係，我們還有下一輪，但是她們的成績已經不會再變了。",
  ui_story_5031_50311001_33_dialog_content = "嗯，那接下來就看卡蓮的了！",
  ui_story_5031_50311001_34_dialog_content = "不過剛剛那是馬太和洛維嗎？他們來做什麼呀，也要參賽嗎？",
  ui_story_5031_50311001_35_dialog_content = "無需在意他們。",
  ui_story_5031_50311001_36_dialog_content = "說起來，從剛剛開始已經很久沒有聽到主持人的聲音了。",
  ui_story_5031_50311001_37_dialog_content = "唔，確實是這樣呢，不知道艾維斯領主他們在做什麼。",
  ui_story_5031_50311001_38_dialog_content = "不過不管怎樣，卡蓮先快去準備一下吧！",
  ui_story_5031_50311001_39_dialog_content = "加油啊，卡蓮！",
  ui_story_5031_50311001_40_dialog_content = "加油卡蓮姐姐！",
  ui_story_5031_50311001_41_dialog_content = "嗯，放心交給我吧。",
  ui_story_5031_50311001_42_dialog_content = "……",
  ui_story_5031_50311001_43_dialog_content = "傑諾老大？",
  ui_story_5031_50311001_44_dialog_content = "幹什麼？",
  ui_story_5031_50311001_45_dialog_content = "<size=33>唔哇，好可怕！老大怎麼忽然心情變得很不好的樣子......</size>",
  ui_story_5031_50311001_46_dialog_content = "那......那個，老大，上一輪的成績出來了，您宣布一下嗎？",
  ui_story_5031_50311001_47_dialog_content = "……",
  ui_story_5031_50311001_48_dialog_content = "呃，或者老大，您要不喊個比賽開始？",
  ui_story_5031_50311001_49_dialog_content = "選手們好像都已經就位了......",
  ui_story_5031_50311001_50_dialog_content = "開始。",
  ui_story_5031_50311001_51_dialog_content = "……",
  ui_story_5031_50311001_52_dialog_content = "算了，也逐漸接受這個風格了。",
  ui_story_5031_50311001_53_dialog_content = "冰花綻放！",
  ui_story_5031_50311001_54_dialog_content = "哇，反應好快呀！",
  ui_story_5031_50311001_55_dialog_content = "竟然用光能冰封了前面的海浪！",
  ui_story_5031_50311001_56_dialog_content = "快速拉開了距離，還完美完成了動作。",
  ui_story_5031_50311001_57_dialog_content = "好厲害好厲害～薩布莉看得好激動！",
  ui_story_5031_50311001_58_dialog_content = "破！",
  ui_story_5031_50311001_59_dialog_content = "嘎！！",
  ui_story_5031_50311001_60_dialog_content = "嗯？剛剛竟然還同時凍住了這麼多暗鬼嗎！",
  ui_story_5031_50311001_61_dialog_content = "哇！",
  ui_story_5031_50311001_62_dialog_content = "那個女孩子好像還救了蘭卡吧？",
  ui_story_5031_50311001_63_dialog_content = "這也太強了，不僅動作優雅完美，對暗鬼簡直是群體秒殺！",
  ui_story_5031_50311001_64_dialog_content = "而且她好厲害，竟然能精準地凍住海面，形成她的彎道！",
  ui_story_5031_50311001_65_dialog_content = "喔～這個姐姐，是叫卡蓮嗎？",
  ui_story_5031_50311001_66_dialog_content = "想起來了，好像是那位公主大人呢！",
  ui_story_5031_50311001_67_dialog_content = "好棒，好棒！",
  ui_story_5031_50311001_68_dialog_content = "看得熱血沸騰，薩布莉也得加油才行了！",
  ui_story_5031_50311001_69_dialog_content = "呼……",
  ui_story_5031_50311001_70_dialog_content = "這樣就是62隻了。",
  ui_story_5031_50311001_71_dialog_content = "剛剛貢露應該有擊中70隻，而琪爾是......93隻。",
  ui_story_5031_50311001_72_dialog_content = "嘖，機甲在這方面還是佔據優勢。",
  ui_story_5031_50311001_73_dialog_content = "薇絲擊中了69隻的話，還有......",
  ui_story_5031_50311001_74_dialog_content = "32隻的差距，和不知道的動作分。",
  ui_story_5031_50311001_75_dialog_content = "馬戲團這邊的話......",
  ui_story_5031_50311001_76_dialog_content = "嗨～卡蓮公主姐姐，妳停在這裡休息嗎？",
  ui_story_5031_50311001_77_dialog_content = "薩布莉？",
  ui_story_5031_50311001_78_dialog_content = "卡蓮公主姐姐竟然記住了薩布莉的名字！薩布莉好開心～",
  ui_story_5031_50311001_79_dialog_content = "喊我卡蓮就好。",
  ui_story_5031_50311001_80_dialog_content = "好的卡蓮姐姐～",
  ui_story_5031_50311001_81_dialog_content = "雖然薩布莉很喜歡卡蓮姐姐，但是還是有一個不幸的消息要告訴妳呢。",
  ui_story_5031_50311001_82_dialog_content = "什麼？",
  ui_story_5031_50311001_83_dialog_content = "我們的策略呀，是讓虹霞姐姐和梅爾特姐姐打頭陣，先拿下分數喔。",
  ui_story_5031_50311001_84_dialog_content = "至於菲爾姆妹妹和薩布莉呀，就是負責......",
  ui_story_5031_50311001_85_dialog_content = "給剩下的選手搗亂呢～",
  ui_story_5031_50311001_86_dialog_content = "唔！",
  ui_story_5031_50311001_87_dialog_content = "難怪剛剛薇絲處處受到菲爾姆的阻撓！",
  ui_story_5031_50311001_88_dialog_content = "是呢～卡蓮姐姐可不要討厭薩布莉啊，薩布莉也沒辦法呢。",
  ui_story_5031_50311001_89_dialog_content = "嘖，這個刁民，竟然真敢攻擊卡蓮殿下！",
  ui_story_5031_50311001_90_dialog_content = "洛維，你去幫卡蓮殿下把那個庶民的小鬼打下水。",
  ui_story_5031_50311001_91_dialog_content = "……",
  ui_story_5031_50311001_92_dialog_content = "好靈巧的身形，不愧是馬戲團出身。",
  ui_story_5031_50311001_93_dialog_content = "在這麼窄小的衝浪板上，對我很不利......",
  ui_story_5031_50311001_94_dialog_content = "哇，不愧是卡蓮姐姐！",
  ui_story_5031_50311001_95_dialog_content = "竟然在抵擋薩布莉的進攻的同時還能保持重心！",
  ui_story_5031_50311001_96_dialog_content = "實在是太優雅了！薩布莉好喜歡妳呀！",
  ui_story_5031_50311001_97_dialog_content = "唔，不能真的傷到她。",
  ui_story_5031_50311001_98_dialog_content = "總之先拉開距離吧。",
  ui_story_5031_50311001_99_dialog_content = "欸，卡蓮姐姐要去哪裡呀？",
  ui_story_5031_50311001_100_dialog_content = "不再陪薩布莉玩一會嗎？薩布莉還沒有玩夠呢。",
  ui_story_5031_50311001_101_dialog_content = "......就是現在！",
  ui_story_5031_50311001_102_dialog_content = "冰花——綻放！",
  ui_story_5031_50311001_103_dialog_content = "<color=#e8d9bb>喀嚓——</color>",
  ui_story_5031_50311001_104_dialog_content = "啊！",
  ui_story_5031_50311001_105_dialog_content = "抱歉，妳先在這老實待一會吧。",
  ui_story_5031_50311001_106_dialog_content = "嗚......欸？",
  ui_story_5031_50311001_107_dialog_content = "嚇，嚇了一跳，還以為要完蛋了。",
  ui_story_5031_50311001_108_dialog_content = "原來只是把薩布莉的身體凍在這裡了呀！",
  ui_story_5031_50311001_109_dialog_content = "嗯～完美地束縛了四肢，但是沒有傷害到薩布莉，也留出了頭部的位置......",
  ui_story_5031_50311001_110_dialog_content = "太強大了，這種把控力，薩布莉感覺更喜歡卡蓮姐姐了呢！",
  ui_story_5031_50311001_111_dialog_content = "......這個孩子，怎麼奇奇怪怪的。",
  ui_story_5031_50311001_112_dialog_content = "不過這樣就消除威脅了，接下來只要專心賺取分數就夠了。",
  ui_story_5031_50311001_113_dialog_content = "剛剛浪費了太多時間了，為了大家的期望，得要抓緊時間了。",
  ui_story_5031_50311002_1_dialog_content = "大家，集合啦！",
  ui_story_5031_50311002_2_dialog_content = "剛剛的衝浪比賽，大家覺得精彩嗎？",
  ui_story_5031_50311002_3_dialog_content = "精彩！——",
  ui_story_5031_50311002_4_dialog_content = "嘿嘿，虹霞也玩得很盡興呢！",
  ui_story_5031_50311002_5_dialog_content = "辛苦每一位參賽選手，你們為自己和大家都留下了難忘的體驗。",
  ui_story_5031_50311002_6_dialog_content = "那麼接下來，就到了宣布成績的時刻了！",
  ui_story_5031_50311002_7_dialog_content = "咕——",
  ui_story_5031_50311002_8_dialog_content = "菲雅妳咽口水的聲音，真的很大。",
  ui_story_5031_50311002_9_dialog_content = "菲，菲雅才沒有緊張喔。",
  ui_story_5031_50311002_10_dialog_content = "別擔心，剛剛卡蓮發揮得那麼好，一定沒問題的！",
  ui_story_5031_50311002_11_dialog_content = "不，我只是把與貢露琪爾她們的暗鬼分差追平了而已。",
  ui_story_5031_50311002_12_dialog_content = "至於動作分數，還是得看最後結果。",
  ui_story_5031_50311002_13_dialog_content = "而且和虹霞她們......可能還是有一定差距。",
  ui_story_5031_50311002_14_dialog_content = "好啦，我們也不吊各位的胃口了！",
  ui_story_5031_50311002_15_dialog_content = "現在，我宣布，衝浪大賽獲得第一名的是——",
  ui_story_5031_50311002_16_dialog_content = "當當當當！是我們「綠榴石隊」喔！",
  ui_story_5031_50311002_17_dialog_content = "分數明細之後會貼在告示板上，大家有異議可以去看看。",
  ui_story_5031_50311002_18_dialog_content = "這可是來自現場的群眾評審的真實資料，絕無包庇杜撰成分！",
  ui_story_5031_50311002_19_dialog_content = "哇！",
  ui_story_5031_50311002_20_dialog_content = "虹霞小姐，當之無愧！",
  ui_story_5031_50311002_21_dialog_content = "感謝大家對我們「綠榴石隊」的厚愛！",
  ui_story_5031_50311002_22_dialog_content = "也感謝領主大人的五百萬白夜幣～",
  ui_story_5031_50311002_23_dialog_content = "哈哈哈哈！",
  ui_story_5031_50311002_24_dialog_content = "啊，好可惜！",
  ui_story_5031_50311002_25_dialog_content = "白夜幣......五百萬白夜幣......",
  ui_story_5031_50311002_26_dialog_content = "嗚嗚，菲雅的泳衣！",
  ui_story_5031_50311002_27_dialog_content = "沒關係，「綠榴石隊」不算是嘉年華比賽的隊伍，至少「海雲鯨」還有希望。",
  ui_story_5031_50311002_28_dialog_content = "至於泳衣，就算不用獎金，我們也還是買得起的啦。",
  ui_story_5031_50311002_29_dialog_content = "真的嗎！PlayerName真的願意給菲雅買泳衣嗎！",
  ui_story_5031_50311002_30_dialog_content = "可以吧，如果妳表現乖，不再惹人生氣和惹是生非的話。",
  ui_story_5031_50311002_31_dialog_content = "嗚哇，你對菲雅的刻板印象太深了！菲雅可是很淑女的。",
  ui_story_5031_50311002_32_dialog_content = "妳是說妳做不到嗎？那果然還是算了吧。",
  ui_story_5031_50311002_33_dialog_content = "啊啊！既然已經說出口了就不許反悔耍賴！",
  ui_story_5031_50311002_34_dialog_content = "……",
  ui_story_5031_50311002_35_dialog_content = "接下來要公布的是，獲得第二名的隊伍。",
  ui_story_5031_50311002_36_dialog_content = "噓！要宣布第二名了！",
  ui_story_5031_50311002_37_dialog_content = "獲得第二名的是——",
  ui_story_5031_50311002_38_dialog_content = "來自啟光的，貢露和琪爾！",
  ui_story_5031_50311002_39_dialog_content = "喔喔——！",
  ui_story_5031_50311002_40_dialog_content = "咦？！",
  ui_story_5031_50311002_41_dialog_content = "<size=45>欸？！！</size>",
  ui_story_5031_50311002_42_dialog_content = "<size=55>欸？！！！</size>",
  ui_story_5031_50311002_43_dialog_content = "竟，竟然是貢露長官和琪爾？",
  ui_story_5031_50311002_44_dialog_content = "這，這樣的話，能拿到大獎的不就......",
  ui_story_5031_50311002_45_dialog_content = "不就不是我們了嗎？",
  ui_story_5031_50311002_46_dialog_content = "那，那那那「海雲鯨」豈不是要被別人帶走了！",
  ui_story_5031_50311002_47_dialog_content = "糟糕了啊！師父一定會罵慘我的！",
  ui_story_5031_50311002_48_dialog_content = "……",
  ui_story_5031_50311002_49_dialog_content = "啊卡蓮，妳去哪裡？",
  ui_story_5031_50311002_50_dialog_content = "卡蓮！",
  ui_story_5031_50311002_51_dialog_content = "卡蓮妳等一下，妳要去哪裡呀？",
  ui_story_5031_50311002_52_dialog_content = "卡......",
  ui_story_5031_50311002_53_dialog_content = "抱歉PlayerName，薇絲，我想一個人待一會。",
  ui_story_5031_50311002_54_dialog_content = "我，我們可以離開。",
  ui_story_5031_50311002_55_dialog_content = "但是我們都很擔心妳，如果可以的話......",
  ui_story_5031_50311002_56_dialog_content = "能至少先告訴我們，發生了什麼嗎？",
  ui_story_5031_50311002_56X1_dialog_content = "是呀，是我們做了什麼讓妳不開心的事情嗎？",
  ui_story_5031_50311002_56X2_dialog_content = "不，不是的，和你們沒有關係。",
  ui_story_5031_50311002_57_dialog_content = "......我只是覺得，自己很失敗。",
  ui_story_5031_50311002_58_dialog_content = "拼盡了全力，卻依然沒有辦法幫助朋友獲得勝利，沒有辦法幫她得到她想要的。",
  ui_story_5031_50311002_59_dialog_content = "可是這不是卡蓮的錯呀？",
  ui_story_5031_50311002_60_dialog_content = "要是真說起來，我才是最該道歉的那個人吧......",
  ui_story_5031_50311002_61_dialog_content = "明明前面大家都那麼努力的賺取分數了，卻因為我沒學會衝浪功虧一簣。",
  ui_story_5031_50311002_62_dialog_content = "那不一樣......",
  ui_story_5031_50311002_63_dialog_content = "為什麼不一樣，明明是一樣的！",
  ui_story_5031_50311002_64_dialog_content = "我很感謝妳這麼努力和為我著想，但我的錯就是我的錯，妳不應該責怪自己。",
  ui_story_5031_50311002_65_dialog_content = "這種團隊合作的比賽，本來就不能過分苛責某個人。",
  ui_story_5031_50311002_66_dialog_content = "我才是應該道歉和感謝妳。",
  ui_story_5031_50311002_67_dialog_content = "如果沒有卡蓮，我們根本不可能走到這一步。",
  ui_story_5031_50311002_68_dialog_content = "……",
  ui_story_5031_50311002_69_dialog_content = "同樣，沒了薇絲，卡蓮覺得我們可能做到現在這樣嗎？",
  ui_story_5031_50311002_70_dialog_content = "……看不出來。",
  ui_story_5031_50311002_71_dialog_content = "對吧，卡蓮對我們來講，也是一樣的。",
  ui_story_5031_50311002_72_dialog_content = "既然拿第一是為了那個什麼什麼鯨魚，那我們就再想辦法嘛。",
  ui_story_5031_50311002_73_dialog_content = "又不是說丟了個第一，天就塌了。",
  ui_story_5031_50311002_74_dialog_content = "是呀卡蓮，實在不行，我們可以去問傑諾、問貢露長官、問虹霞小姐。",
  ui_story_5031_50311002_75_dialog_content = "把關於海雲鯨的事情講清楚，我相信他們也會願意幫助我們的。",
  ui_story_5031_50311002_75X1_dialog_content = "薇絲說得對，這些都不是什麼大問題，總會有解決辦法的。",
  ui_story_5031_50311002_76_dialog_content = "所以卡蓮，就不要再難過了，好不好？",
  ui_story_5031_50311002_77_dialog_content = "我們一起想辦法。",
  ui_story_5031_50311002_78_dialog_content = "……",
  ui_story_5031_50311002_79_dialog_content = "好。",
  ui_story_5031_50311002_80_dialog_content = "你們說得對，謝謝你們。",
  ui_story_5031_50311002_81_dialog_content = "我確實應該向你們多學習，可能，這就是父親大人的目的......",
  ui_story_5031_50311002_82_dialog_content = "舒瓦茲殿下？為什麼要提到妳父親呀？",
  ui_story_5031_50311002_83_dialog_content = "其實，我這次出來前，曾和他有過一場......討論。",
  ui_story_5031_50311002_83X1_dialog_content = "討論？",
  ui_story_5031_50311002_83X2_dialog_content = "是的，父親大人他提到，希望我能思考一下與你們一同遊歷的意義。",
  ui_story_5031_50311002_83X3_dialog_content = "我想我大概明白了，你們身上都有著許多值得我去學習的地方。",
  ui_story_5031_50311002_83X4_dialog_content = "難怪感覺卡蓮這一整天都在陷入在自己的世界裡思考呢。",
  ui_story_5031_50311002_83X5_dialog_content = "但就算是冥思苦想，有很多事情對我而言也依然很縹緲。",
  ui_story_5031_50311002_83X6_dialog_content = "比如，薇絲妳之前所說的有關覺醒的事情，我今天其實有過一次嘗試。",
  ui_story_5031_50311002_83X7_dialog_content = "欸？關於覺醒的嘗試嗎？",
  ui_story_5031_50311002_83X8_dialog_content = "是的，我根據妳之前所說的方法，讓意識下沉。",
  ui_story_5031_50311002_83X9_dialog_content = "但是，卻因為回憶起了與父親大人的對話，怎麼樣都無法集中注意力。",
  ui_story_5031_50311002_83X10_dialog_content = "最後失敗了。",
  ui_story_5031_50311002_83X11_dialog_content = "原來如此，不過其實這種情況還是滿常見的。",
  ui_story_5031_50311002_83X12_dialog_content = "讓自己不受情緒雜念的擺布，精神高度集中，這本身就是一件困難的事情。",
  ui_story_5031_50311002_83X13_dialog_content = "我的話，是因為當時內心有一縷光芒，幫我驅散了一切執念。",
  ui_story_5031_50311002_83X14_dialog_content = "光芒？我記得妳之前也提到過，它究竟是什麼？",
  ui_story_5031_50311002_83X15_dialog_content = "唔，就是我會想到和妳，還有PlayerName的一些有趣的經歷。",
  ui_story_5031_50311002_83X16_dialog_content = "然後不知不覺地，內心就會變得平和下來。",
  ui_story_5031_50311002_83X17_dialog_content = "不過這種事情比較玄妙，很難去描述。",
  ui_story_5031_50311002_83X18_dialog_content = "原來如此，那麼我......",
  ui_story_5031_50311002_84_dialog_content = "PlayerName！卡蓮姐姐！薇絲姐姐！",
  ui_story_5031_50311002_85_dialog_content = "你們怎麼丟下菲雅跑來這裡了呀，我們找了你們好久！",
  ui_story_5031_50311002_85X1_dialog_content = "啊，糟糕，剛剛太著急，竟然把小菲雅一個人忘在那邊了！",
  ui_story_5031_50311002_86_dialog_content = "菲雅？妳怎麼了，這麼慌慌張張的？",
  ui_story_5031_50311002_87_dialog_content = "來找你們呀！",
  ui_story_5031_50311002_88_dialog_content = "你們聽我說，剛剛傑諾告訴我們——",
  ui_story_5031_50311002_89_dialog_content = "衝浪比賽的排名只是用來決定下一場比賽的出場順序，我們還有下一場比賽！",
  ui_story_5031_50311002_90_dialog_content = "是作為員工，參加馬戲表演喔！",
  ui_story_5031_50311002_91_dialog_content = "我們還有機會！",
  ui_story_5031_50311101_1_dialog_content = "所以，現在的情況是——",
  ui_story_5031_50311101_2_dialog_content = "嗚嗚嗚......<size=45>嗚哇！！！</size>",
  ui_story_5031_50311101_3_dialog_content = "<size=45>我們的......偉大目標......</size>",
  ui_story_5031_50311101_4_dialog_content = "海雲鯨......再這樣下去就找不到海雲鯨了，<size=45>嗚啊啊啊！</size>",
  ui_story_5031_50311101_5_dialog_content = "（唉......明明馬上就要進行最關鍵的最終舞台決戰了。）",
  ui_story_5031_50311101_6_dialog_content = "（但是，現在這些神奇動物卻在和菲雅鬧彆扭，怎麼都不肯聽話。）",
  ui_story_5031_50311101_7_dialog_content = "（這樣下去就要被淘汰了，還是先勸勸菲雅，最後努力一把好了！）",
  ui_story_5031_50311101_8_option_content = "菲雅，先不要氣餒！",
  ui_story_5031_50311101_9_dialog_content = "嗚......難，難道PlayerName你有什麼好辦法嗎？",
  ui_story_5031_50311101_10_dialog_content = "說實話，我也沒有想到什麼點子，可是留給我們彩排的時間只剩一個小時。",
  ui_story_5031_50311101_11_dialog_content = "一個小時後，船上的觀眾們就會準備來看表演了。",
  ui_story_5031_50311101_12_dialog_content = "那不就是完蛋了嗎？！嗚哇！！！",
  ui_story_5031_50311101_13_dialog_content = "停停停，妳先別急著哭！",
  ui_story_5031_50311101_14_dialog_content = "想想當年我們兩個足跡遍布整個艾斯特拉，歷盡艱險只為保護神奇動物。",
  ui_story_5031_50311101_15_dialog_content = "完成了這樣一番偉業的我們，怎麼能輕易被這種小小的困難打敗呢？",
  ui_story_5031_50311101_16_dialog_content = "只要菲雅再努努力和比卡打好關係，就一定能完成演出的！",
  ui_story_5031_50311101_17_dialog_content = "嗨？",
  ui_story_5031_50311101_18_dialog_content = "菲雅......菲雅已經沒有幹勁了。",
  ui_story_5031_50311101_19_dialog_content = "說到底，我們連最終大獎究竟是不是海雲鯨都不知道，就跑過來參加了這個比賽。",
  ui_story_5031_50311101_20_dialog_content = "（妳竟然才意識到這一點嗎？！）",
  ui_story_5031_50311101_21_dialog_content = "喂！你那副表情，是不是正在心裡說菲雅的壞話？！",
  ui_story_5031_50311101_22_dialog_content = "不不不，我怎麼敢呢！",
  ui_story_5031_50311101_23_dialog_content = "不然這樣吧，我們兩個假裝去廁所，然後偷偷去看一下最終大獎究竟是不是海雲鯨。",
  ui_story_5031_50311101_24_dialog_content = "如果真是海雲鯨的話，妳也能打起精神來繼續和比卡彩排了吧？",
  ui_story_5031_50311101_25_dialog_content = "還，還可以這樣嗎？",
  ui_story_5031_50311101_26_dialog_content = "可那個叫傑諾的傢伙看起來就很可怕，如果這麼做惹他生氣的話就糟了......",
  ui_story_5031_50311101_27_dialog_content = "只是偷偷看一眼，應該沒關係吧？",
  ui_story_5031_50311101_28_dialog_content = "我也會用感應能力幫忙，不會讓別人發現我們的。",
  ui_story_5031_50311101_29_dialog_content = "嗯......嗯！有道理！",
  ui_story_5031_50311101_30_dialog_content = "那就靠你了，菲雅的神奇動物夥伴，「超珍奇物種」空裔PlayerName！",
  ui_story_5031_50311101_31_dialog_content = "都說了幾次了，我才不是神奇動物啊！",
  ui_story_5031_50311101_32_dialog_content = "唉，算了。時間所剩不多了，我們快去快回吧。",
  ui_story_5031_50311101_33_dialog_content = "<color=#e8d9bb>航船深處</color>",
  ui_story_5031_50311101_34_dialog_content = "這裡就是之前那個兇巴巴的團長不讓我們進來的地方了。",
  ui_story_5031_50311101_35_dialog_content = "好大啊，每條走廊長得都一個樣，而且還有好多岔路......",
  ui_story_5031_50311101_36_dialog_content = "海雲鯨究竟被藏在哪裡呢？",
  ui_story_5031_50311101_37_dialog_content = "停，菲雅。",
  ui_story_5031_50311101_38_dialog_content = "先在這裡躲一下，我感應到前面有人過來了。",
  ui_story_5031_50311101_39_dialog_content = "呼啊——已經巡邏第三圈了。",
  ui_story_5031_50311101_40_dialog_content = "真不知道團長怎麼想的，要我在這種螞蟻都爬不進來的地方巡邏。",
  ui_story_5031_50311101_41_dialog_content = "馬戲團裡怎麼還會有警衛在巡邏，難道團長有著什麼不可告人的祕密嗎？",
  ui_story_5031_50311101_42_dialog_content = "如果沒有PlayerName幫忙的話，菲雅一定早早就被抓住丟出去了。",
  ui_story_5031_50311101_43_dialog_content = "這都是PlayerName的功勞喔，等找到海雲鯨，菲雅一定會好好獎勵PlayerName的。",
  ui_story_5031_50311101_44_dialog_content = "一整包動物餅乾怎麼樣，凱羅很喜歡的那種，PlayerName喜歡嗎？",
  ui_story_5031_50311101_45_dialog_content = "別急著考慮那種問題，還是先找到最終大獎再說吧。",
  ui_story_5031_50311101_46_dialog_content = "唔......",
  ui_story_5031_50311101_47_dialog_content = "再停一下，我感應到前面有兩個人......但是他們似乎停在原地沒有走動？",
  ui_story_5031_50311101_48_dialog_content = "那我們悄悄溜過去，一定不會被發現的。",
  ui_story_5031_50311101_49_dialog_content = "等等！",
  ui_story_5031_50311101_50_dialog_content = "又怎麼了？",
  ui_story_5031_50311101_51_dialog_content = "這兩個人給我的感覺，似乎有點熟悉。",
  ui_story_5031_50311101_52_dialog_content = "是艾維斯和帕托？！",
  ui_story_5031_50311101_53_dialog_content = "那個領主和衛兵叔叔？他們怎麼會在這裡？",
  ui_story_5031_50311101_54_dialog_content = "我怎麼可能知道嘛！總之，先不要管他們，專注於我們的目標。",
  ui_story_5031_50311101_55_dialog_content = "小聲一點，千萬別驚動他們。",
  ui_story_5031_50311101_56_dialog_content = "抱歉，大人，我們仔細搜尋過傑諾的住所和可疑的地方，都沒發現像是鑰匙的東西。",
  ui_story_5031_50311101_57_dialog_content = "沒關係，我已經找到了。",
  ui_story_5031_50311101_58_dialog_content = "他一直將鑰匙隨身攜帶著，不管做什麼都不會離身。",
  ui_story_5031_50311101_59_dialog_content = "這就難辦了......",
  ui_story_5031_50311101_60_dialog_content = "無妨，繼續按照計畫進行，今晚，一定要成功。",
  ui_story_5031_50311101_61_dialog_content = "計畫？PlayerName，那兩個傢伙好像在說什麼計畫唔唔唔——！",
  ui_story_5031_50311101_62_option_content = "別出聲！",
  ui_story_5031_50311101_63_dialog_content = "你聽見剛才的動靜了嗎？",
  ui_story_5031_50311101_64_dialog_content = "是什麼人？給我出來！",
  ui_story_5031_50311101_65_dialog_content = "（不好了，快跑！）",
  ui_story_5031_50311101_66_dialog_content = "呼......呼，一口氣跑到甲板上來了。",
  ui_story_5031_50311101_67_dialog_content = "噗哈——！PlayerName太粗暴了！菲雅差點被憋死了呀！",
  ui_story_5031_50311101_68_dialog_content = "抱歉抱歉，剛才太著急了。",
  ui_story_5031_50311101_69_dialog_content = "好像是往這邊跑了！",
  ui_story_5031_50311101_70_dialog_content = "咳咳......我們，追上去。",
  ui_story_5031_50311101_71_dialog_content = "不好，他們還追在後面，得趕緊找個地方躲起來！",
  ui_story_5031_50311101_72_dialog_content = "唷——PlayerName，還有小菲雅！",
  ui_story_5031_50311101_73_dialog_content = "菲雅一點也不小啦！",
  ui_story_5031_50311101_74_dialog_content = "你們已經排練好了嗎？",
  ui_story_5031_50311101_75_dialog_content = "欸？還，還沒有。抱歉我們還有事，先......",
  ui_story_5031_50311101_76_dialog_content = "哼哼，我可是已經準備好了絕招喔！",
  ui_story_5031_50311101_77_dialog_content = "有王座的幫助，這次的勝利者一定會是我。",
  ui_story_5031_50311101_78_dialog_content = "不然現在就給你表演一下吧，我的手下敗將！",
  ui_story_5031_50311101_79_dialog_content = "（糟糕，被貢露纏上了，附近有沒有可以躲的地方？）",
  ui_story_5031_50311101_80_dialog_content = "PlayerName，他們追過來了！",
  ui_story_5031_50311101_81_dialog_content = "快用你無敵的感應能力想想辦法啊！",
  ui_story_5031_50311101_82_dialog_content = "我的感應能力沒法用來想辦法啊！",
  ui_story_5031_50311101_83_dialog_content = "無敵——！",
  ui_story_5031_50311101_84_dialog_content = "碧海——！",
  ui_story_5031_50311101_85_dialog_content = "<size=45>王座——！！！</size>",
  ui_story_5031_50311101_86_dialog_content = "好刺眼的光？！",
  ui_story_5031_50311101_87_dialog_content = "呃，那邊那道光芒是？！",
  ui_story_5031_50311101_88_dialog_content = "怎麼樣，很厲害吧？",
  ui_story_5031_50311101_89_dialog_content = "這可是我為王座新增的照明功能喔！",
  ui_story_5031_50311101_90_dialog_content = "有了它，就算是在夜晚黑暗無光的海面上也能盡情衝浪了呢！",
  ui_story_5031_50311101_91_dialog_content = "呃，好......好厲害？",
  ui_story_5031_50311101_92_dialog_content = "好厲害啊！",
  ui_story_5031_50311101_93_dialog_content = "好多人被吸引過來了？！",
  ui_story_5031_50311101_94_dialog_content = "剛才那招太厲害了，能再表演一次嗎？！",
  ui_story_5031_50311101_95_dialog_content = "再表演一次？沒問題喔！",
  ui_story_5031_50311101_96_dialog_content = "嘖，這裡人太多了，看來偷聽的傢伙已經跑了。",
  ui_story_5031_50311101_97_dialog_content = "無妨，只是偷聽罷了，不會對計畫有任何影響。",
  ui_story_5031_50311101_98_dialog_content = "我們走，一切按原計畫執行。",
  ui_story_5031_50311101_99_dialog_content = "遵命。",
  ui_story_5031_50311101_100_dialog_content = "他們好像走了，並沒有發現我們。",
  ui_story_5031_50311101_101_dialog_content = "太好了，貢露，幫大忙了！",
  ui_story_5031_50311101_102_dialog_content = "欸欸？我有幫到忙嗎？你們在說什麼？",
  ui_story_5031_50311101_103_dialog_content = "等事情結束，我們再好好感謝妳。",
  ui_story_5031_50311101_104_dialog_content = "但是現在還有重要的事情要做，先走了！",
  ui_story_5031_50311101_105_dialog_content = "手下敗將怎麼急急忙忙的？",
  ui_story_5031_50311101_106_dialog_content = "不過，剛才看他的表情那麼緊張，現在卻放鬆下來了。",
  ui_story_5031_50311101_107_dialog_content = "他們兩個一定是沉醉在我精彩的表演裡了吧！",
  ui_story_5031_50311101_108_dialog_content = "到頭來忙了這麼久，不僅沒有看到最終大獎是什麼，還白白浪費了不少時間。",
  ui_story_5031_50311101_109_dialog_content = "沒辦法，船內部的空間太大了，還有那麼多的守衛。",
  ui_story_5031_50311101_110_dialog_content = "只靠我們兩個，是沒辦法在這麼短的時間內全都探索一遍的。",
  ui_story_5031_50311101_111_dialog_content = "看樣子，只能老老實實地磨煉技巧、奪取比賽的第一名了！",
  ui_story_5031_50311101_112_dialog_content = "可是......明明已經沒時間了......",
  ui_story_5031_50311101_113_dialog_content = "海雲鯨......嗚嗚，可憐的海雲鯨會不會已經......",
  ui_story_5031_50311101_114_dialog_content = "怎麼又哭起來了？！",
  ui_story_5031_50311101_115_dialog_content = "PlayerName，菲雅？你們還在排練嗎？",
  ui_story_5031_50311101_116_dialog_content = "你該不會是對菲雅說了什麼語氣太重的話，給她惹哭了吧？",
  ui_story_5031_50311101_117_option_content = "才沒那回事！",
  ui_story_5031_50311101_118_option_content = "不是因為我！",
  ui_story_5031_50311101_119_dialog_content = "比卡在彩排的時候總是不肯配合，所以菲雅正在為這件事發愁。",
  ui_story_5031_50311101_120_dialog_content = "嗨嗨～",
  ui_story_5031_50311101_121_dialog_content = "嗚嗚......真是的，他們......他們可沒在誇你！",
  ui_story_5031_50311101_122_dialog_content = "嗨？",
  ui_story_5031_50311101_123_dialog_content = "真奇怪啊，明明之前比卡和菲雅的關係很好啊。",
  ui_story_5031_50311101_124_dialog_content = "為什麼比卡突然變得不配合了？",
  ui_story_5031_50311101_125_dialog_content = "難道是沒有和比卡好好溝通嗎？",
  ui_story_5031_50311101_126_dialog_content = "菲雅明明，明明和比卡君好好說過了，但牠就是不聽嘛！",
  ui_story_5031_50311101_127_dialog_content = "菲雅都對比卡說了什麼呢？",
  ui_story_5031_50311101_128_dialog_content = "菲雅說，菲雅想要獲得比賽的大獎，要比卡君幫忙配合菲雅。",
  ui_story_5031_50311101_129_dialog_content = "那比卡是怎麼說的呢？",
  ui_story_5031_50311101_130_dialog_content = "比卡君好像什麼都沒說......",
  ui_story_5031_50311101_131_dialog_content = "那不就是根本沒同意嗎？",
  ui_story_5031_50311101_132_dialog_content = "可是，比卡君明明已經答應菲雅成為臨時搭檔了，怎麼可能不同意？",
  ui_story_5031_50311101_133_dialog_content = "嗚哇！！！",
  ui_story_5031_50311101_134_dialog_content = "唉，所以說妳先別哭，這件事想要解決，還得靠妳自己。",
  ui_story_5031_50311101_135_dialog_content = "靠菲雅自己？",
  ui_story_5031_50311101_136_dialog_content = "雖然比卡是你的臨時搭檔，但也不能因為搭檔會包容妳，就高高在上地對牠下指令。",
  ui_story_5031_50311101_137_dialog_content = "現在這種情況，說到底還是因為妳沒有和比卡好好溝通過吧。",
  ui_story_5031_50311101_138_dialog_content = "嗚，那菲雅該怎麼補救呢？",
  ui_story_5031_50311101_139_dialog_content = "先認真地向比卡道個歉吧？",
  ui_story_5031_50311101_140_dialog_content = "不僅要道歉，更重要的是之後要認真地請求比卡幫忙，並且獲得牠的同意才行。",
  ui_story_5031_50311101_141_dialog_content = "比卡君，會願意幫忙嗎？",
  ui_story_5031_50311101_142_dialog_content = "牠看起來比野生的比卡凶好多......",
  ui_story_5031_50311101_143_dialog_content = "這就要看妳的誠意了。",
  ui_story_5031_50311101_144_dialog_content = "如果是菲雅的話，一定沒問題的。",
  ui_story_5031_50311101_145_dialog_content = "嗯，不要放棄，加油喔！",
  ui_story_5031_50311101_146_dialog_content = "好，好吧，菲雅試試看。",
  ui_story_5031_50311101_147_dialog_content = "比卡君，對......",
  ui_story_5031_50311101_148_dialog_content = "對不起。",
  ui_story_5031_50311101_149_dialog_content = "嗨嗨？",
  ui_story_5031_50311101_150_dialog_content = "（比卡把爪子湊到了耳朵旁邊，是想說菲雅聲音太小了嗎？）",
  ui_story_5031_50311101_151_dialog_content = "對……",
  ui_story_5031_50311101_152_dialog_content = "<size=45>對不起嘛！！！</size>",
  ui_story_5031_50311101_153_dialog_content = "之前是我不好，不該自說自話地強迫你幫菲雅表演。",
  ui_story_5031_50311101_154_dialog_content = "是我錯了，下一次、不......沒有下一次了！",
  ui_story_5031_50311101_155_dialog_content = "之後的事情，我會好好徵求你的意見，嗚......",
  ui_story_5031_50311101_156_dialog_content = "嗨？",
  ui_story_5031_50311101_157_dialog_content = "之後？呃，之後......給你買好吃的？",
  ui_story_5031_50311101_158_dialog_content = "嗨～嗨嗨？",
  ui_story_5031_50311101_159_dialog_content = "欸？！你說要吃傳說中的彭伯伯種的葡萄？",
  ui_story_5031_50311101_160_dialog_content = "還說是另外一隻比卡告訴你的？！",
  ui_story_5031_50311101_161_dialog_content = "可是那個好貴的......",
  ui_story_5031_50311101_162_dialog_content = "嗨嗨？",
  ui_story_5031_50311101_163_dialog_content = "沒沒沒，我沒有在抱怨！",
  ui_story_5031_50311101_164_dialog_content = "只要你願意原諒我，我都買給你！嗚......",
  ui_story_5031_50311101_165_dialog_content = "（菲雅露出了狼狽的表情呢。）",
  ui_story_5031_50311101_166_dialog_content = "（趁著這個機會，也讓她多學習一些與他人相處的方法吧。）",
  ui_story_5031_50311101_167_dialog_content = "嗨～",
  ui_story_5031_50311101_168_dialog_content = "（比卡好像很開心的樣子，是認可菲雅的道歉了嗎？）",
  ui_story_5031_50311101_169_dialog_content = "你原諒菲雅了？太好了！",
  ui_story_5031_50311101_170_dialog_content = "那之後的表演......",
  ui_story_5031_50311101_171_dialog_content = "嗨嗨～",
  ui_story_5031_50311101_172_dialog_content = "欸？",
  ui_story_5031_50311101_173_dialog_content = "菲雅，比卡說了什麼？",
  ui_story_5031_50311101_174_dialog_content = "牠說......「要看菲雅的表現」。",
  ui_story_5031_50311101_175_dialog_content = "這麼模糊的說法嗎？！",
  ui_story_5031_50311101_176_dialog_content = "真的沒問題嗎，妳要不要再拜託牠一下？",
  ui_story_5031_50311101_177_dialog_content = "畢竟這可是關乎最終決戰的大事件。",
  ui_story_5031_50311101_178_dialog_content = "嗚，我......",
  ui_story_5031_50311101_179_dialog_content = "決賽的帷幕即將拉開，各位參賽者們，時間到了。",
  ui_story_5031_50311101_180_dialog_content = "這麼快？！",
  ui_story_5031_50311101_181_dialog_content = "已經一個小時了嗎，沒辦法了......",
  ui_story_5031_50311101_182_dialog_content = "硬著頭皮上吧！",
  ui_story_5031_50311101_183_dialog_content = "就交給我吧！",
  ui_story_5031_50311101_184_dialog_content = "我們會盡可能多爭取分數的。",
  ui_story_5031_50311101_185_dialog_content = "菲雅和比卡君也會加油的！",
  ui_story_5031_50311101_186_dialog_content = "嗨嗨！",
  ui_story_5031_50311201_1_dialog_content = "伴隨著夜幕的降臨，本次大賽的第三場比賽也正式開始了！",
  ui_story_5031_50311201_2_dialog_content = "噢！！！",
  ui_story_5031_50311201_3_dialog_content = "根據之前的比賽成績，有兩支隊伍將在這座舞台上一決高下！",
  ui_story_5031_50311201_4_dialog_content = "他們分別是目前成績最好的啟光隊！",
  ui_story_5031_50311201_5_dialog_content = "以及由新人馴獸師菲雅帶領的菲雅隊！",
  ui_story_5031_50311201_6_dialog_content = "噢噢噢！！！",
  ui_story_5031_50311201_7_dialog_content = "氣氛相當熱烈呢，真是太棒了！",
  ui_story_5031_50311201_8_dialog_content = "那麼，在正式比賽之前，就先請各位欣賞由傑諾團長和三姐妹帶來的開場表演吧！",
  ui_story_5031_50311201_9_dialog_content = "首先，有請傑諾團長！",
  ui_story_5031_50311201_10_dialog_content = "「預知儀式」，這是古今無數光靈追求過的能力。",
  ui_story_5031_50311201_11_dialog_content = "與超凡的存在溝通，從中解讀出來自過去或未來的隻言片語......",
  ui_story_5031_50311201_12_dialog_content = "進而便可洞悉歷史的真相或預知未來。",
  ui_story_5031_50311201_13_dialog_content = "今夜，我將在此展現這古老的能力，解答在座各位的疑惑。",
  ui_story_5031_50311201_14_dialog_content = "而我將使用的，便是這副起源之牌。",
  ui_story_5031_50311201_15_dialog_content = "噢！來了來了，是傳說中的「預知儀式」嗎！",
  ui_story_5031_50311201_16_dialog_content = "能召喚暗鬼，甚至還能預知......起源的力量到底有著怎樣的奧祕啊？",
  ui_story_5031_50311201_17_dialog_content = "接下來，我將邀請一位幸運觀眾登台協助我的表演。",
  ui_story_5031_50311201_18_dialog_content = "將會是哪一位貴客的命運之線，與我交匯呢？",
  ui_story_5031_50311201_19_dialog_content = "我！！！",
  ui_story_5031_50311201_20_dialog_content = "選我，選我！",
  ui_story_5031_50311201_21_dialog_content = "感應到了，我感應到了......",
  ui_story_5031_50311201_22_dialog_content = "起源之牌將我的命運指向了您——",
  ui_story_5031_50311201_23_dialog_content = "那位坐在第一排最右邊的女士。",
  ui_story_5031_50311201_24_dialog_content = "選、選中我了嗎？",
  ui_story_5031_50311201_25_dialog_content = "沒錯，請您上台。",
  ui_story_5031_50311201_26_dialog_content = "您可以向我詢問任何問題，而我將用這副起源之牌進行通靈，給出答案。",
  ui_story_5031_50311201_27_dialog_content = "什麼都可以問嗎？",
  ui_story_5031_50311201_28_dialog_content = "當然。",
  ui_story_5031_50311201_29_dialog_content = "那麼......您知道我來自哪裡嗎？",
  ui_story_5031_50311201_30_dialog_content = "起源之牌，請成為我的雙眼，助我洞悉真相，指明這位女士的家鄉。",
  ui_story_5031_50311201_31_dialog_content = "（紙牌在傑諾的手指間飛舞，他抽出了一張牌！）",
  ui_story_5031_50311201_32_dialog_content = "起源之牌已經告訴了我答案，您來自佩德羅堡。",
  ui_story_5031_50311201_33_dialog_content = "你是怎麼知道的？！",
  ui_story_5031_50311201_34_dialog_content = "這是起源之牌帶給我的答案，不僅如此，它還告訴了我其他關於您的事情——",
  ui_story_5031_50311201_35_dialog_content = "您來自某位子爵的家族，並且有著幸福的家庭。",
  ui_story_5031_50311201_36_dialog_content = "雖然不知為何，您與您的伴侶並未坐在一起，但兩位的關係仍然相當融洽。",
  ui_story_5031_50311201_37_dialog_content = "真厲害啊，這都被您看出來了......",
  ui_story_5031_50311201_38_dialog_content = "由於票太搶手了，我們沒能買到相鄰的座位，所以只好分開來坐。",
  ui_story_5031_50311201_39_dialog_content = "而且，您的伴侶將前排的好位置讓給了您。",
  ui_story_5031_50311201_40_dialog_content = "是、是的……",
  ui_story_5031_50311201_41_dialog_content = "起源之牌祝福你們未來一切順利，您可以回到座位上了。",
  ui_story_5031_50311201_42_dialog_content = "噢！！！好厲害！！！",
  ui_story_5031_50311201_43_dialog_content = "再選一個人吧！",
  ui_story_5031_50311201_44_dialog_content = "時間如此寶貴，哪怕是起源之牌，也需要遵循時間的法則。",
  ui_story_5031_50311201_45_dialog_content = "還請各位繼續觀賞接下來的表演，我期待著下一次與各位命運交匯的契機。",
  ui_story_5031_50311201_46_dialog_content = "傑諾團長的表演真是精彩！",
  ui_story_5031_50311201_47_dialog_content = "接下來請各位欣賞由梅爾特、薩布莉和菲爾姆帶來的驚險刺激的空中飛人表演！",
  ui_story_5031_50311201_48_dialog_content = "那個......要上了喔！",
  ui_story_5031_50311201_49_dialog_content = "讓他們驚訝得下巴脫臼！",
  ui_story_5031_50311201_50_dialog_content = "好——",
  ui_story_5031_50311201_51_dialog_content = "來吧！",
  ui_story_5031_50311201_52_dialog_content = "（梅爾特登上了梯子，向另外兩個人伸出了手！）",
  ui_story_5031_50311201_53_dialog_content = "嘿——！",
  ui_story_5031_50311201_54_dialog_content = "菲爾，要好好接住我喔！",
  ui_story_5031_50311201_55_dialog_content = "薩布姐，好重......",
  ui_story_5031_50311201_56_dialog_content = "（好險！還好菲爾姆拉住了薩布莉！）",
  ui_story_5031_50311201_57_dialog_content = "我，我要上了喔！",
  ui_story_5031_50311201_58_dialog_content = "（欸？！難道說她們要——）",
  ui_story_5031_50311201_59_dialog_content = "咿呀！",
  ui_story_5031_50311201_60_dialog_content = "我抓！",
  ui_story_5031_50311201_61_dialog_content = "變得......更重了！",
  ui_story_5031_50311201_62_dialog_content = "成功了！",
  ui_story_5031_50311201_63_option_content = "好厲害！！！",
  ui_story_5031_50311201_64_dialog_content = "噢噢噢！！！太厲害了！！！",
  ui_story_5031_50311201_65_dialog_content = "謝、謝謝！",
  ui_story_5031_50311201_66_dialog_content = "好好記住我們華麗的身姿了嗎？",
  ui_story_5031_50311201_67_dialog_content = "記住了！！！",
  ui_story_5031_50311201_68_dialog_content = "只不過是普普通通的表演......",
  ui_story_5031_50311201_69_dialog_content = "總之，各位的歡呼，我們收下了！",
  ui_story_5031_50311201_70_dialog_content = "請期待接下來的比賽吧！",
  ui_story_5031_50311201_71_dialog_content = "感謝三位的精彩演出！",
  ui_story_5031_50311201_72_dialog_content = "接下來我宣布，最後一輪比賽正式開始！",
  ui_story_5031_50311201_73_dialog_content = "排在第一位的是啟光隊，將由琪爾和貢露分別為各位帶來自己的絕技！",
  ui_story_5031_50311201_74_dialog_content = "我參考貢露前輩的意見改裝了機甲，就是為了這一刻......",
  ui_story_5031_50311201_75_dialog_content = "一定要成功啊，拜託了！",
  ui_story_5031_50311201_76_dialog_content = "噢噢！琪爾好像準備了什麼很厲害的絕招！",
  ui_story_5031_50311201_77_dialog_content = "……",
  ui_story_5031_50311201_78_dialog_content = "咦？菲雅，妳還好嗎？怎麼在發抖？",
  ui_story_5031_50311201_79_dialog_content = "好緊張......",
  ui_story_5031_50311201_80_dialog_content = "妳在緊張嗎？",
  ui_story_5031_50311201_81_dialog_content = "才......才沒那回事！",
  ui_story_5031_50311201_82_dialog_content = "菲雅可是神奇動物專家，菲雅才——嗚！",
  ui_story_5031_50311201_83_dialog_content = "竟然緊張得咬到舌頭了嗎......",
  ui_story_5031_50311201_84_dialog_content = "菲雅才沒有緊張！",
  ui_story_5031_50311201_85_dialog_content = "菲雅，先不要想其他事情，試著深呼吸。",
  ui_story_5031_50311201_86_dialog_content = "呼——",
  ui_story_5031_50311201_87_dialog_content = "吸——",
  ui_story_5031_50311201_88_dialog_content = "怎麼樣，感覺好點了嗎？",
  ui_story_5031_50311201_89_dialog_content = "嗚......還是不行。緊張得心臟都要跳出來了。",
  ui_story_5031_50311201_90_dialog_content = "琪爾和貢露看起來那麼強，但我甚至還沒有和比卡達成一致......",
  ui_story_5031_50311201_91_dialog_content = "怎麼看都沒可能取勝啊！",
  ui_story_5031_50311201_92_dialog_content = "先不要緊張，事已至此，再怎麼後悔都來不及了。",
  ui_story_5031_50311201_93_dialog_content = "打起精神來，盡力完成演出吧。",
  ui_story_5031_50311201_94_dialog_content = "可是，萬一比卡還是不配合該怎麼辦？",
  ui_story_5031_50311201_95_dialog_content = "這個嘛……",
  ui_story_5031_50311201_96_option_content = "你有沒有聽說過一句話？",
  ui_story_5031_50311201_97_dialog_content = "什麼話？",
  ui_story_5031_50311201_98_dialog_content = "「好孩子是誇出來的！」",
  ui_story_5031_50311201_99_dialog_content = "咦？！",
  ui_story_5031_50311201_100_dialog_content = "總之大概是這個意思，試著去討牠開心，求牠配合妳吧。",
  ui_story_5031_50311201_101_dialog_content = "只要能拿到大獎，不管是不是海雲鯨，剩下的一切都好說！",
  ui_story_5031_50311201_102_dialog_content = "那我，我就勉為其難地試試吧！",
  ui_story_5031_50311201_103_dialog_content = "加油！我、薇絲和卡蓮也會努力取得積分的！",
  ui_story_5031_50311201_104_dialog_content = "畢竟最後的得分是總分除以人數得到的平均分。",
  ui_story_5031_50311201_105_dialog_content = "每個人都盡可能努力，取得勝利的機率就會提高！",
  ui_story_5031_50311201_106_dialog_content = "我......我知道了......",
  ui_story_5031_50311201_107_dialog_content = "大家請看，貢露和琪爾的演出實在是太精彩了！",
  ui_story_5031_50311201_108_dialog_content = "琪爾的機甲與貢露的王座在炫目的光芒中交錯飛舞。",
  ui_story_5031_50311201_109_dialog_content = "琪爾的鋼鐵機甲仿佛失去了重量，以高難度的技巧像戰鬥一樣舞蹈著。",
  ui_story_5031_50311201_110_dialog_content = "她將重量與美感的衝突結合得非常完美！",
  ui_story_5031_50311201_111_dialog_content = "那麼，接下來有請菲雅隊登台表演！",
  ui_story_5031_50311201_112_dialog_content = "不知道他們會為觀眾帶來怎樣精彩絕倫的表演呢？",
  ui_story_5031_50311201_113_dialog_content = "呼......我們走吧，比卡君！",
  ui_story_5031_50311201_114_dialog_content = "嗨！",
  ui_story_5031_50311201_115_dialog_content = "（加油啊，菲雅、比卡！）",
  ui_story_5031_50311201_116_dialog_content = "（拜託了，這次千萬不要出意外啊......）",
  ui_story_5031_50311201_117_dialog_content = "好，來吧，比卡君，請到這裡來。",
  ui_story_5031_50311201_118_dialog_content = "嗨！",
  ui_story_5031_50311201_119_dialog_content = "照我說的，跳起的同時翻個跟頭吧。",
  ui_story_5031_50311201_120_dialog_content = "嗨嗨？",
  ui_story_5031_50311201_121_dialog_content = "（比卡，在看著菲雅，好像還露出了意味不明的笑？！）",
  ui_story_5031_50311201_122_dialog_content = "請......請你配合我吧！",
  ui_story_5031_50311201_123_dialog_content = "嗨？",
  ui_story_5031_50311201_124_dialog_content = "（比卡開始裝傻了？！）",
  ui_story_5031_50311201_125_dialog_content = "怎麼回事啊喂！",
  ui_story_5031_50311201_126_dialog_content = "我們買了票可不是來這裡看妳浪費時間的！",
  ui_story_5031_50311201_127_dialog_content = "嗚……",
  ui_story_5031_50311201_128_dialog_content = "拜、拜託你了！",
  ui_story_5031_50311201_129_dialog_content = "嗨～？",
  ui_story_5031_50311201_129X1_dialog_content = "比卡君最厲害了，這種小事對你來說一定輕輕鬆鬆就能做到吧！",
  ui_story_5031_50311201_130_dialog_content = "等比賽結束我就去給你買彭伯伯種的葡萄！",
  ui_story_5031_50311201_131_dialog_content = "嗨嗨！",
  ui_story_5031_50311201_132_dialog_content = "成功了？！",
  ui_story_5031_50311201_133_dialog_content = "嗨～",
  ui_story_5031_50311201_134_dialog_content = "喔喔！再來一個！",
  ui_story_5031_50311201_135_dialog_content = "下面我會扔出這個排球，請你好好接住！",
  ui_story_5031_50311201_136_dialog_content = "嗨！嗨！",
  ui_story_5031_50311201_137_dialog_content = "嗨～",
  ui_story_5031_50311201_138_dialog_content = "精彩！",
  ui_story_5031_50311201_139_dialog_content = "（太好了，比卡君看在葡萄的份上願意配合我了！）",
  ui_story_5031_50311201_140_dialog_content = "嗨？",
  ui_story_5031_50311201_141_dialog_content = "等等啊？這個不是給你吃的！",
  ui_story_5031_50311201_142_dialog_content = "哈哈哈！",
  ui_story_5031_50311201_143_dialog_content = "（好險，還以為要出演出事故了，看起來觀眾把這當成了表演的一環。）",
  ui_story_5031_50311201_144_dialog_content = "最後，請向大家展示你的絕招吧，比卡君！",
  ui_story_5031_50311201_145_dialog_content = "絕招？！我怎麼沒聽過這個？",
  ui_story_5031_50311201_146_dialog_content = "難道菲雅你要像那次對付獵人那樣，讓比卡吞下巨大的石頭嗎？！",
  ui_story_5031_50311201_147_dialog_content = "很危險的啊喂！",
  ui_story_5031_50311201_148_dialog_content = "菲雅才不會做那種事情呢！",
  ui_story_5031_50311201_149_dialog_content = "菲雅這次準備了這個！",
  ui_story_5031_50311201_150_dialog_content = "請看——！",
  ui_story_5031_50311201_151_dialog_content = "好多泡泡？！",
  ui_story_5031_50311201_152_dialog_content = "好漂亮的泡泡啊。",
  ui_story_5031_50311201_153_dialog_content = "但是這跟馴獸有什麼關係？",
  ui_story_5031_50311201_154_dialog_content = "接下來就看比卡君的表演了！",
  ui_story_5031_50311201_155_dialog_content = "嗨嗨！",
  ui_story_5031_50311201_156_dialog_content = "嗨——！",
  ui_story_5031_50311201_157_dialog_content = "（對喔！這些氣泡都是比卡喜歡的球型！）",
  ui_story_5031_50311201_158_dialog_content = "噢噢！這小傢伙還有這種能力嗎？！",
  ui_story_5031_50311201_159_dialog_content = "嗨！",
  ui_story_5031_50311201_160_dialog_content = "嗨......嗨......",
  ui_story_5031_50311201_161_dialog_content = "嗝——！",
  ui_story_5031_50311201_162_dialog_content = "（比卡吃掉太多空氣，身體都被撐起來了！）",
  ui_story_5031_50311201_163_dialog_content = "哈哈哈哈哈！好可愛啊！",
  ui_story_5031_50311201_164_dialog_content = "那麼，菲雅的表演就到這裡了！",
  ui_story_5031_50311201_165_dialog_content = "請大家期待菲雅隊友的精彩表現喔！",
  ui_story_5031_50311201_166_dialog_content = "噢！！！",
  ui_story_5031_50311201_167_dialog_content = "在菲雅完成表演之後，我、薇絲和卡蓮也依次登台。",
  ui_story_5031_50311201_168_dialog_content = "我使用感應能力，表演了讀心。",
  ui_story_5031_50311201_169_dialog_content = "薇絲則憑藉著強大的箭術表演了射箭。",
  ui_story_5031_50311201_170_dialog_content = "不過還是希望她下回不要再把作為箭靶的蘋果放在我頭上了！",
  ui_story_5031_50311201_171_dialog_content = "最厲害的當然還是卡蓮，她的芭蕾舞讓所有人都驚呆了。",
  ui_story_5031_50311201_172_dialog_content = "而且沒想到......她竟然會讓傑諾把暗鬼放到舞台上作為節目道具！",
  ui_story_5031_50311202_1_dialog_content = "冰花綻放！",
  ui_story_5031_50311202_2_dialog_content = "將芭蕾舞與戰鬥結合起來，恐怕也只有卡蓮能做到了吧！",
  ui_story_5031_50311202_3_dialog_content = "真是......太厲害了！",
  ui_story_5031_50311202_4_dialog_content = "感謝卡蓮選手的芭蕾表演，真是驚險又精彩呢！",
  ui_story_5031_50311202_5_dialog_content = "接下來，就是萬眾期待的環節了——",
  ui_story_5031_50311202_6_dialog_content = "終於......要公布成績了！",
  ui_story_5031_50311202_7_dialog_content = "嗨！",
  ui_story_5031_50311202_8_dialog_content = "已經......要緊張得......喘不過氣了......",
  ui_story_5031_50311202_9_dialog_content = "撐住啊，菲雅！",
  ui_story_5031_50311202_10_dialog_content = "想想妳要找的海雲鯨！",
  ui_story_5031_50311202_11_dialog_content = "海雲鯨......對，海雲鯨！菲雅的大獎！",
  ui_story_5031_50311202_12_dialog_content = "下面由我來宣布比賽的最終勝利者，他們是——",
  ui_story_5031_50311202_13_dialog_content = "菲雅隊！",
  ui_story_5031_50311202_14_dialog_content = "菲雅，勝利了......？",
  ui_story_5031_50311202_15_dialog_content = "耶！菲雅勝利了！！！",
  ui_story_5031_50311202_16_dialog_content = "嗨！",
  ui_story_5031_50311202_17_dialog_content = "雖然菲雅的馴獸表演還不夠完美，但菲雅隊勝在隊友之間的通力合作。",
  ui_story_5031_50311202_18_dialog_content = "卡蓮小姐的芭蕾舞表演更是前所未有的精彩。",
  ui_story_5031_50311202_19_dialog_content = "因此，菲雅隊的平均成績取得了第一！",
  ui_story_5031_50311202_20_dialog_content = "恭喜妳，菲雅。",
  ui_story_5031_50311202_21_dialog_content = "沒想到妳個子這麼小，卻滿強的嘛！",
  ui_story_5031_50311202_22_dialog_content = "這次我被妳打敗了，但下次我可不會輸喔！",
  ui_story_5031_50311202_23_dialog_content = "恭喜恭喜，菲雅終於成功完成馴獸表演，取得勝利了呢！",
  ui_story_5031_50311202_24_dialog_content = "不過我還是很在意，那個最終大獎究竟是什麼？",
  ui_story_5031_50311202_25_dialog_content = "會是菲雅一直在找的海雲鯨嗎？",
  ui_story_5031_50311202_26_dialog_content = "對喔！菲雅的大獎，那個從深海中撈上來的、絕無僅有的寶物！",
  ui_story_5031_50311202_27_dialog_content = "是的，我已經帶來了妳應得的大獎。",
  ui_story_5031_50311202_28_dialog_content = "就是牠。",
  ui_story_5031_50311202_29_dialog_content = "囉！囉囉囉！",
  ui_story_5031_50311202_30_dialog_content = "嗚哇？！這這這，這不是凱羅嗎？！",
  ui_story_5031_50311202_31_dialog_content = "我不是派你去海裡找海雲鯨的線索嗎？",
  ui_story_5031_50311202_32_dialog_content = "怪不得你一直都沒來聯絡我，原來是在這裡偷懶呀！",
  ui_story_5031_50311202_33_dialog_content = "這是我不久前從海裡撈上來的動物。",
  ui_story_5031_50311202_34_dialog_content = "牠看起來很好吃的樣子，我準備把牠燉成湯給大賽的優勝者喝。",
  ui_story_5031_50311202_35_dialog_content = "囉囉囉？！囉！",
  ui_story_5031_50311202_36_dialog_content = "不可以吃凱羅啊！",
  ui_story_5031_50311202_37_dialog_content = "牠可是菲雅的夥伴！",
  ui_story_5031_50311202_38_dialog_content = "是妳的夥伴嗎？我還以為是什麼美味的食材。",
  ui_story_5031_50311202_39_dialog_content = "畢竟妳是勝利者，而牠是妳的獎品，理應交由妳處置。",
  ui_story_5031_50311202_40_dialog_content = "囉囉......",
  ui_story_5031_50311202_41_dialog_content = "呼，你這傢伙真是不小心，知不知道自己差點就要死翹翹了啊？",
  ui_story_5031_50311202_42_dialog_content = "囉......囉囉！",
  ui_story_5031_50311202_43_dialog_content = "你說你正在海底找海雲鯨的時候，忽然被一隻網子撈走了？",
  ui_story_5031_50311202_44_dialog_content = "還被關在船裡好幾天？",
  ui_story_5031_50311202_45_dialog_content = "那你有沒有在船上見過海雲鯨？！",
  ui_story_5031_50311202_46_dialog_content = "囉？囉囉！",
  ui_story_5031_50311202_47_dialog_content = "什麼嘛......竟然沒有。",
  ui_story_5031_50311202_48_dialog_content = "既然已經公布了成績、頒發了獎品，那就請各位移步至甲板吧。",
  ui_story_5031_50311202_49_dialog_content = "慶功宴與煙火大會馬上就要開始了。",
  ui_story_5031_50311202_50_dialog_content = "還有煙火嗎？那我們快去占個好位置吧！",
  ui_story_5031_50311202_51_dialog_content = "不是海雲鯨......大獎怎麼不是海雲鯨啊！",
  ui_story_5031_50311202_52_dialog_content = "結果到頭來還不是白忙活一陣！",
  ui_story_5031_50311202_53_dialog_content = "怎麼可能是鯨魚呢？",
  ui_story_5031_50311202_54_dialog_content = "就算只是鯨魚的幼崽，僅憑綠榴石號也是無法容納的。",
  ui_story_5031_50311202_55_dialog_content = "這位小小的女士，妳也許未曾見過鯨魚真正的模樣？",
  ui_story_5031_50311202_56_dialog_content = "沒，沒見過又怎麼了嘛！",
  ui_story_5031_50311202_57_dialog_content = "那可是珍奇物種，怎麼可能隨隨便便就讓人見到？",
  ui_story_5031_50311202_58_dialog_content = "噗……",
  ui_story_5031_50311202_59_dialog_content = "不許笑！！！",
  ui_story_5031_50311202_60_dialog_content = "好啦好啦，我們也並沒有白忙活啊。",
  ui_story_5031_50311202_61_option_content = "至少贏了比賽",
  ui_story_5031_50311202_62_dialog_content = "菲雅也和馬戲船上的比卡成為朋友了吧？",
  ui_story_5031_50311202_63_dialog_content = "嗨！",
  ui_story_5031_50311202_64_dialog_content = "知，知道了啦！我會給你買葡萄吃的！",
  ui_story_5031_50311202_65_option_content = "至少救了凱羅",
  ui_story_5031_50311202_66_dialog_content = "囉囉！",
  ui_story_5031_50311202_67_dialog_content = "唉......只是沒想到最後的大獎竟然是凱羅。",
  ui_story_5031_50311202_68_dialog_content = "既然你是被意外抓到的，那你還是回去繼續找海雲鯨吧。",
  ui_story_5031_50311202_69_dialog_content = "囉？",
  ui_story_5031_50311202_70_dialog_content = "我這邊不需要你幫忙啦，好了，快回去吧！",
  ui_story_5031_50311202_71_dialog_content = "我扔！",
  ui_story_5031_50311202_72_dialog_content = "囉——！",
  ui_story_5031_50311202_73_dialog_content = "（凱羅成為了天邊的流星......菲雅好可怕！）",
  ui_story_5031_50311202_74_dialog_content = "唉......妳，真的是神奇動物專家嗎？",
  ui_story_5031_50311202_75_dialog_content = "如假包換喔！",
  ui_story_5031_50311202_76_dialog_content = "不過，傑諾的占卜是怎麼做到的？",
  ui_story_5031_50311202_77_dialog_content = "難道你也是空裔一族，有著神奇的感應能力嗎？",
  ui_story_5031_50311202_78_dialog_content = "那其實並不是真正的占卜，只是觀察對方得出的推斷。",
  ui_story_5031_50311202_79_dialog_content = "比如那位女士，她穿著的衣服雖然是大眾款式，但用的料子卻只產自佩德羅堡。",
  ui_story_5031_50311202_80_dialog_content = "有沒有家庭這件事，只需要觀察她手上的戒指。",
  ui_story_5031_50311202_81_dialog_content = "至於與伴侶分開就坐，則是因為我觀察到她頻頻回頭與另一個人對視。",
  ui_story_5031_50311202_82_dialog_content = "所以就能得出結論——",
  ui_story_5031_50311202_83_dialog_content = "打擾了，傑諾，我有些事情想對你說。我們能去舞台那邊說嗎？",
  ui_story_5031_50311202_84_dialog_content = "我知道了。",
  ui_story_5031_50311202_85_dialog_content = "抱歉，各位，我先失陪一會。",
  ui_story_5031_50311202_86_dialog_content = "喂！你倒是先把話說完啊！",
  ui_story_5031_50311202_87_dialog_content = "真是的，就這麼自說自話地走掉了。",
  ui_story_5031_50311202_88_dialog_content = "煙火大會開始了！",
  ui_story_5031_50311202_89_dialog_content = "嗯，真美啊。",
  ui_story_5031_50311202_90_dialog_content = "原來你們也在這裡啊！",
  ui_story_5031_50311202_91_dialog_content = "大，大家都在......",
  ui_story_5031_50311202_92_dialog_content = "虹霞，妳怎麼端著一堆吃的，是要回去吃嗎？",
  ui_story_5031_50311202_93_dialog_content = "不一起看煙火嗎？",
  ui_story_5031_50311202_94_dialog_content = "我們有別的安排！",
  ui_story_5031_50311202_95_dialog_content = "雖然煙火很漂亮，但是剛才我和琪爾一起想到了一個改裝機甲的絕妙主意！",
  ui_story_5031_50311202_96_dialog_content = "所以我們打算立刻回去試試！",
  ui_story_5031_50311202_97_dialog_content = "是的……",
  ui_story_5031_50311202_98_dialog_content = "抱歉，沒辦法和大家一起聊天了。",
  ui_story_5031_50311202_99_dialog_content = "沒關係沒關係，以後還有很多機會！",
  ui_story_5031_50311202_100_dialog_content = "那我們先走啦！",
  ui_story_5031_50311202_101_dialog_content = "她們兩個關係真好，讓人有點羡慕。",
  ui_story_5031_50311202_102_dialog_content = "卡蓮，妳說什麼呢？",
  ui_story_5031_50311202_103_dialog_content = "妳不是還有我和PlayerName兩個好朋友嗎！",
  ui_story_5031_50311202_104_dialog_content = "是啊，一直以來，我們不都是一起旅行、一起冒險的嗎？",
  ui_story_5031_50311202_105_dialog_content = "是啊，這次也一樣！",
  ui_story_5031_50311202_106_dialog_content = "如果不是卡蓮的芭蕾舞掙到了那麼多分數，我們肯定就輸了！",
  ui_story_5031_50311202_107_dialog_content = "沒錯，多虧了妳！",
  ui_story_5031_50311202_108_dialog_content = "可別把自己當成是外人喔，卡蓮！",
  ui_story_5031_50311202_109_dialog_content = "是嗎......呵呵，我知道了。",
  ui_story_5031_50311202_110_dialog_content = "謝謝你們。",
  ui_story_5031_50311202_111_dialog_content = "嗯！",
  ui_story_5031_50311301_1_dialog_content = "白天的時候還沒注意到，但是現在仔細看的話，夜幕和煙火下的好泊城真美啊。",
  ui_story_5031_50311301_2_dialog_content = "是啊，白色的建築被煙火照得五顏六色，比白天時更好看！",
  ui_story_5031_50311301_3_dialog_content = "PlayerName，薇絲還有菲雅，我想去找艾維斯談談。",
  ui_story_5031_50311301_4_dialog_content = "你們願意等我一會嗎？",
  ui_story_5031_50311301_5_dialog_content = "沒問題！我們就在這裡等妳回來。",
  ui_story_5031_50311301_6_dialog_content = "好，多謝。",
  ui_story_5031_50311301_7_dialog_content = "看樣子，事情終於告一段落了。",
  ui_story_5031_50311301_8_dialog_content = "但海雲鯨還是沒有找到......",
  ui_story_5031_50311301_9_dialog_content = "到底在哪裡呢，傳說中的海雲鯨......",
  ui_story_5031_50311301_10_dialog_content = "不要那麼著急嘛，有些事情是不能強求的。",
  ui_story_5031_50311301_11_dialog_content = "沒錯。就像我偶爾會在起床後找不到自己的髮夾，愈是急著找，就愈找不到。",
  ui_story_5031_50311301_12_dialog_content = "但當我最後想放棄不找的時候，就會突然發現髮夾出現在自己手邊了喔！",
  ui_story_5031_50311301_13_dialog_content = "真的嗎？",
  ui_story_5031_50311301_14_dialog_content = "當然是真的。",
  ui_story_5031_50311301_15_dialog_content = "好吧，菲雅就相信你一次。",
  ui_story_5031_50311301_16_dialog_content = "大家。",
  ui_story_5031_50311301_17_dialog_content = "咦？卡蓮，你們這麼快就聊完了？",
  ui_story_5031_50311301_18_dialog_content = "不，不是的。我怎麼都找不到艾維斯。",
  ui_story_5031_50311301_19_dialog_content = "他不是拉著傑諾去舞台聊天了嗎？",
  ui_story_5031_50311301_20_dialog_content = "我去過了舞台，並沒有看到他們。",
  ui_story_5031_50311301_21_dialog_content = "艾維斯和傑諾......",
  ui_story_5031_50311301_22_dialog_content = "難不成他們往船艙裡去了？",
  ui_story_5031_50311301_23_dialog_content = "船艙？那不是傑諾不允許任何人靠近的地方嗎？",
  ui_story_5031_50311301_24_dialog_content = "但如果別的地方找不到的話，他們很可能就是在那裡了。",
  ui_story_5031_50311301_25_dialog_content = "我們過去看一下吧，那邊應該有人知道他們的去向。",
  ui_story_5031_50311301_26_dialog_content = "PlayerName，你怎麼對船艙的路這麼清楚？",
  ui_story_5031_50311301_27_dialog_content = "因為之前我和菲雅曾在這裡被艾維斯和帕托追著跑了好久......",
  ui_story_5031_50311301_28_dialog_content = "艾維斯和帕托？這是怎麼回事？",
  ui_story_5031_50311301_29_dialog_content = "說來話長，就是......",
  ui_story_5031_50311301_30_dialog_content = "PlayerName，你快看那邊好像有個人倒在地上！",
  ui_story_5031_50311301_31_dialog_content = "那是......傑諾？！",
  ui_story_5031_50311301_32_dialog_content = "真的嗎？你真的願意給我畫畫像？",
  ui_story_5031_50311301_33_dialog_content = "嗯......但我畫得很慢，畫得也不太好......",
  ui_story_5031_50311301_34_dialog_content = "沒關係，傑諾給我畫的一定是最棒的！",
  ui_story_5031_50311301_35_dialog_content = "那，我們明天一早在海港碼頭見面吧？",
  ui_story_5031_50311301_36_dialog_content = "等趕完海你就給我畫，畫完我給你做海鮮湯！",
  ui_story_5031_50311301_37_dialog_content = "哇！艾維斯的海鮮湯！",
  ui_story_5031_50311301_38_dialog_content = "好呀好呀～那就一言為定！",
  ui_story_5031_50311301_39_dialog_content = "明天見！",
  ui_story_5031_50311301_40_dialog_content = "明，明天見！",
  ui_story_5031_50311301_41_dialog_content = "……",
  ui_story_5031_50311301_42_dialog_content = "…………",
  ui_story_5031_50311301_43_dialog_content = "明明約好了。",
  ui_story_5031_50311301_44_dialog_content = "明明，約好了的......",
  ui_story_5031_50311301_45_dialog_content = "<size=33>傑......</size>",
  ui_story_5031_50311301_46_dialog_content = "<size=33>傑諾——</size>",
  ui_story_5031_50311301_47_dialog_content = "嗯？是誰？",
  ui_story_5031_50311301_48_dialog_content = "傑諾！",
  ui_story_5031_50311301_49_dialog_content = "艾維斯？是你嗎？你回來了？",
  ui_story_5031_50311301_50_dialog_content = "<size=45>傑諾，你醒一醒！</size>",
  ui_story_5031_50311301_51_dialog_content = "艾維斯！",
  ui_story_5031_50311301_52_dialog_content = "哇啊！",
  ui_story_5031_50311301_53_dialog_content = "哇啊啊！！",
  ui_story_5031_50311301_54_dialog_content = "PlayerName你叫那麼大聲幹嘛啦？嚇到我了！",
  ui_story_5031_50311301_55_dialog_content = "抱......抱歉，我也是被嚇了一跳。",
  ui_story_5031_50311301_56_dialog_content = "傑諾，你感覺怎麼樣？有沒有哪裡受傷？",
  ui_story_5031_50311301_57_dialog_content = "我......怎麼會在這裡？",
  ui_story_5031_50311301_58_dialog_content = "這話不是應該我們問你嗎？",
  ui_story_5031_50311301_59_dialog_content = "你為什麼要躺在這個角落裡睡覺呀？我們找了你好久呢。",
  ui_story_5031_50311301_60_dialog_content = "所以說菲雅，他並不是在睡覺......",
  ui_story_5031_50311301_61_dialog_content = "是這樣的，煙火表演和慶典都結束了，我們想與艾維斯閣下辭別後就返程。",
  ui_story_5031_50311301_62_dialog_content = "但四處都沒有找到他，所以在想或許你們是進了船艙裡。",
  ui_story_5031_50311301_63_dialog_content = "於是我們也冒昧進來了，卻看到你昏迷在這裡。",
  ui_story_5031_50311301_64_dialog_content = "剛剛......嘶。",
  ui_story_5031_50311301_65_dialog_content = "這裡不會有旁人打擾了，你想說什麼，艾維斯？",
  ui_story_5031_50311301_66_dialog_content = "我想要......向你表達我的感謝，傑諾。",
  ui_story_5031_50311301_67_dialog_content = "......這麼突然？",
  ui_story_5031_50311301_68_dialog_content = "謝我做什麼？",
  ui_story_5031_50311301_69_dialog_content = "謝謝你接受了我的邀請，給好泊城的市民們帶來如此美好難忘的回憶。",
  ui_story_5031_50311301_70_dialog_content = "你能來對我而言......意義重大。",
  ui_story_5031_50311301_71_dialog_content = "不必在意，我們馬戲團四處漂泊，到哪裡停靠出演都一樣。",
  ui_story_5031_50311301_72_dialog_content = "況且你贈送給我們補給也是出手大方，反倒是我們該表示感謝。",
  ui_story_5031_50311301_73_dialog_content = "不，傑諾。",
  ui_story_5031_50311301_74_dialog_content = "我欠你的，大概怎樣都無法償還了。",
  ui_story_5031_50311301_75_dialog_content = "欠我？你在說什......",
  ui_story_5031_50311301_76_dialog_content = "唔？！",
  ui_story_5031_50311301_77_dialog_content = "抱歉。",
  ui_story_5031_50311301_78_dialog_content = "咳！咳咳......這......這是什......",
  ui_story_5031_50311301_79_dialog_content = "什麼……",
  ui_story_5031_50311301_80_dialog_content = "傑諾......我很抱歉。",
  ui_story_5031_50311301_81_dialog_content = "你是說，是艾維斯閣下用了什麼東西讓你陷入昏迷？",
  ui_story_5031_50311301_82_dialog_content = "嗯。",
  ui_story_5031_50311301_83_dialog_content = "欸？艾維斯是壞人嗎？",
  ui_story_5031_50311301_84_dialog_content = "菲雅，真相還未明確，不應該妄下斷言。",
  ui_story_5031_50311301_85_dialog_content = "<size=33>糟了，真的不見了......</size>",
  ui_story_5031_50311301_86_dialog_content = "怎麼了傑諾？你在找什......",
  ui_story_5031_50311301_87_dialog_content = "哇！怎麼回事？",
  ui_story_5031_50311301_88_dialog_content = "船體......在震動？",
  ui_story_5031_50311301_89_dialog_content = "......沒想到他真的會做到這種地步。",
  ui_story_5031_50311301_90_dialog_content = "等等！傑諾！",
  ui_story_5031_50311301_91_dialog_content = "傑......傑諾......呼......",
  ui_story_5031_50311301_92_dialog_content = "你能不能先解釋一下到底是怎麼回事？",
  ui_story_5031_50311301_93_dialog_content = "……",
  ui_story_5031_50311301_94_dialog_content = "沒辦法了。",
  ui_story_5031_50311301_95_dialog_content = "如果他真的成功把「那個東西」喚醒了，那我確實需要你們的力量。",
  ui_story_5031_50311301_96_dialog_content = "那個東西？",
  ui_story_5031_50311301_97_dialog_content = "是這樣的，我剛剛醒來後，發現我隨身攜帶的船艙核心室的鑰匙不見了。",
  ui_story_5031_50311301_98_dialog_content = "核心室裡有什麼重要的東西嗎？",
  ui_story_5031_50311301_99_dialog_content = "是「<color=#FFB400>能源核心</color>」。",
  ui_story_5031_50311301_100_dialog_content = "「能源核心」？！",
  ui_story_5031_50311301_101_dialog_content = "為什麼你們都是一副對它很熟悉的樣子？",
  ui_story_5031_50311301_102_dialog_content = "「能源核心」是一種舊文明造物，妳可以理解為一種很寶貴的資源。",
  ui_story_5031_50311301_103_dialog_content = "沒想到，這艘船上竟然也有......",
  ui_story_5031_50311301_104_dialog_content = "因為這艘船本身就來自遺跡。",
  ui_story_5031_50311301_105_dialog_content = "我剛剛說的「那個東西」，是守護「能源核心」的舊文明兵器——",
  ui_story_5031_50311301_106_dialog_content = "「<color=#FFB400>核心守護者</color>」。",
  ui_story_5031_50311301_107_dialog_content = "「核心守護者」一旦被啟動，就會無差別攻擊任何靠近「能源核心」的生命體。",
  ui_story_5031_50311301_108_dialog_content = "那樣的話，整艘船都會陷入危機之中。",
  ui_story_5031_50311301_109_dialog_content = "你的意思是，艾維斯閣下趁你昏迷時搶走了你的鑰匙。",
  ui_story_5031_50311301_110_dialog_content = "並且進入了核心室，打算奪取「能源核心」？",
  ui_story_5031_50311301_111_dialog_content = "應該是這樣，但是......",
  ui_story_5031_50311301_112_dialog_content = "傑諾！",
  ui_story_5031_50311301_113_dialog_content = "啊，是虹霞姐姐和琪爾姐姐！",
  ui_story_5031_50311301_114_dialog_content = "糟了傑諾，剛剛我和琪爾在機輪室看到顯示，核心室被打開了！",
  ui_story_5031_50311301_115_dialog_content = "知道，我們現在就在趕過去。",
  ui_story_5031_50311301_116_dialog_content = "路上發現我們請來巡邏把守船艙的傭兵也陷入了昏迷......",
  ui_story_5031_50311301_117_dialog_content = "虹霞小心！",
  ui_story_5031_50311301_118_dialog_content = "哇啊！好險好險，多謝琪爾。",
  ui_story_5031_50311301_119_dialog_content = "咦？這些是......好泊城的衛兵？",
  ui_story_5031_50311301_120_dialog_content = "是為了拖住我們而布下的防線嗎。",
  ui_story_5031_50311301_121_dialog_content = "……",
  ui_story_5031_50311301_122_dialog_content = "愚昧的僕從，別擋路！",
  ui_story_5031_50311302_1_dialog_content = "艾維斯這個傢伙......",
  ui_story_5031_50311302_2_dialog_content = "這些人，究竟是什麼時候進到船艙裡？",
  ui_story_5031_50311302_3_dialog_content = "又有新的光能感應在靠近！",
  ui_story_5031_50311302_4_dialog_content = "數量......只比現在這些更多。",
  ui_story_5031_50311302_5_dialog_content = "<color=#e8d9bb>轟——</color>",
  ui_story_5031_50311302_6_dialog_content = "哇！我的船！",
  ui_story_5031_50311302_7_dialog_content = "艾維斯這個混蛋到底在對我的船做什麼啊！！",
  ui_story_5031_50311302_8_dialog_content = "再這麼下去，我們恐怕真的會被拖住。",
  ui_story_5031_50311302_9_dialog_content = "大家正在困擾......",
  ui_story_5031_50311302_10_dialog_content = "這樣的話！",
  ui_story_5031_50311302_11_dialog_content = "「手部機甲狀態調整——Ⅲ型」。",
  ui_story_5031_50311302_12_dialog_content = "「腿部機甲狀態調整——Ⅲ型」。",
  ui_story_5031_50311302_13_dialog_content = "「能源釋放百分比提高70%」。",
  ui_story_5031_50311302_14_dialog_content = "欸？",
  ui_story_5031_50311302_15_dialog_content = "琪爾，妳在做什麼！妳的機甲還沒有調試完呢！",
  ui_story_5031_50311302_16_dialog_content = "我來拖住他們，虹霞你們快去核心室。",
  ui_story_5031_50311302_17_dialog_content = "可是……",
  ui_story_5031_50311302_18_dialog_content = "放心吧！",
  ui_story_5031_50311302_19_dialog_content = "有妳和我一起進行過調試優化，「斯提克斯」一定沒問題。",
  ui_story_5031_50311302_20_dialog_content = "琪爾說的對，虹霞。",
  ui_story_5031_50311302_21_dialog_content = "我們不能在這裡被拖住，已經耽誤太多時間了。",
  ui_story_5031_50311302_22_dialog_content = "我們......必須要相信同伴，這裡就交給琪爾吧。",
  ui_story_5031_50311302_23_dialog_content = "卡蓮……",
  ui_story_5031_50311302_24_dialog_content = "（卡蓮她，真的改變了。）",
  ui_story_5031_50311302_25_dialog_content = "……",
  ui_story_5031_50311302_26_dialog_content = "琪爾，妳可別玩太過，把機甲搞壞了！",
  ui_story_5031_50311302_27_dialog_content = "那妳欠我的債可就沒法輕易一筆勾銷了喔！",
  ui_story_5031_50311302_28_dialog_content = "欸，欸？",
  ui_story_5031_50311302_29_dialog_content = "好，放心吧。",
  ui_story_5031_50311302_30_dialog_content = "琪爾，拜託你了。",
  ui_story_5031_50311302_31_dialog_content = "琪爾，一定要小心啊！",
  ui_story_5031_50311302_32_dialog_content = "小姑娘，我不想以多欺少，勸妳快點讓開。",
  ui_story_5031_50311302_33_dialog_content = "只是攔住你們，我一個人綽綽有餘。",
  ui_story_5031_50311302_34_dialog_content = "......那就抱歉了。",
  ui_story_5031_50311302_35_dialog_content = "唔，比剛剛那群人要強，人數也有點多。",
  ui_story_5031_50311302_36_dialog_content = "這樣的話，只能......",
  ui_story_5031_50311302_37_dialog_content = "「能源釋放百分比提高80%」。",
  ui_story_5031_50311302_38_dialog_content = "嘶......她的火力又變強了？",
  ui_story_5031_50311302_39_dialog_content = "可惡，這身重甲，簡直像個怪物一樣。",
  ui_story_5031_50311302_40_dialog_content = "但是為了領主大人，我們絕對不能倒下。",
  ui_story_5031_50311302_41_dialog_content = "一隊！保持隊形，以光能盾陣型逼近過去！",
  ui_story_5031_50311302_42_dialog_content = "只要讓她離開了機甲，她就沒辦法了。",
  ui_story_5031_50311302_43_dialog_content = "是！",
  ui_story_5031_50311302_44_dialog_content = "這個盾組合到一起後竟然會增加硬度？",
  ui_story_5031_50311302_45_dialog_content = "趁現在，二隊光能槍準備，搭起！",
  ui_story_5031_50311302_46_dialog_content = "糟了，這個盾打不破的話，被他們逼近就完蛋了......",
  ui_story_5031_50311302_47_dialog_content = "不行，我要冷靜，呼——",
  ui_story_5031_50311302_48_dialog_content = "雖然硬度提升了，但只要是需要能源的東西，強度就一定和光能有關。",
  ui_story_5031_50311302_49_dialog_content = "那我只要釋放比它更強的光能就夠了。",
  ui_story_5031_50311302_50_dialog_content = "但是「斯提克斯」今天已經損壞過一次了......",
  ui_story_5031_50311302_51_dialog_content = "如果再提高釋放比的話......「斯提克斯」會......",
  ui_story_5031_50311302_52_dialog_content = "我都想好了啦，等我造出了動力裝甲，要幫大家做好多好多事！",
  ui_story_5031_50311302_53_dialog_content = "哦？等裝甲造出來了，琪爾最想做什麼事呢？",
  ui_story_5031_50311302_54_dialog_content = "我呀，我想......",
  ui_story_5031_50311302_55_dialog_content = "......我想......",
  ui_story_5031_50311302_56_dialog_content = "幫助朋友，保護同伴，成為一個值得依靠的人！",
  ui_story_5031_50311302_57_dialog_content = "抱歉了，虹霞，「斯提克斯」！",
  ui_story_5031_50311302_58_dialog_content = "<size=45>「能源釋放百分比提高100%」！</size>",
  ui_story_5031_50311302_59_dialog_content = "什，什麼？光能盾竟然被打破了？",
  ui_story_5031_50311302_60_dialog_content = "她是怪物吧？！",
  ui_story_5031_50311302_61_dialog_content = "呼……呼……",
  ui_story_5031_50311302_62_dialog_content = "看來，還是有點勉強......",
  ui_story_5031_50311302_63_dialog_content = "不僅腿部連接異常，光能也......",
  ui_story_5031_50311302_64_dialog_content = "不許退縮！",
  ui_story_5031_50311302_65_dialog_content = "盾破了也無所謂，她的能量也不是用之不竭的！",
  ui_story_5031_50311302_66_dialog_content = "難道我們這麼多人，要被一個小姑娘給攔下來嗎？！",
  ui_story_5031_50311302_67_dialog_content = "……是！",
  ui_story_5031_50311302_68_dialog_content = "呼......我不會讓你們......過去的......",
  ui_story_5031_50311302_69_dialog_content = "她的進攻變弱了，就是現在！",
  ui_story_5031_50311302_70_dialog_content = "人海戰術以多欺少，還打得這麼狼狽，這就是好泊城的衛兵嗎？",
  ui_story_5031_50311302_71_dialog_content = "這聲音是......？",
  ui_story_5031_50311302_72_dialog_content = "啊！",
  ui_story_5031_50311302_73_dialog_content = "是，是剛剛那個人！",
  ui_story_5031_50311302_74_dialog_content = "哇，我都說了讓妳別玩太過了，妳就是不聽！",
  ui_story_5031_50311302_75_dialog_content = "「斯提克斯」看起來狀態比之前還差，真是的，白給妳修了一下午！",
  ui_story_5031_50311302_76_dialog_content = "虹霞！妳為什麼回來了？",
  ui_story_5031_50311302_77_dialog_content = "因為我擔心妳嘛。",
  ui_story_5031_50311302_78_dialog_content = "那核心室那邊怎麼辦？",
  ui_story_5031_50311302_79_dialog_content = "交給傑諾他們囉。",
  ui_story_5031_50311302_80_dialog_content = "嘶，還搞偷襲？",
  ui_story_5031_50311302_81_dialog_content = "唔！",
  ui_story_5031_50311302_82_dialog_content = "……",
  ui_story_5031_50311302_83_dialog_content = "嗯？琪爾妳怎麼了？為什麼是這副表情。",
  ui_story_5031_50311302_84_dialog_content = "......也是啊。",
  ui_story_5031_50311302_85_dialog_content = "像我這樣把自己搞得這麼狼狽的人，確實沒資格談什麼信賴、依靠。",
  ui_story_5031_50311302_86_dialog_content = "如果不是虹霞回來，我可能......",
  ui_story_5031_50311302_87_dialog_content = "……",
  ui_story_5031_50311302_88_dialog_content = "琪爾有的時候真的是有點傻呢。",
  ui_story_5031_50311302_89_dialog_content = "欸？",
  ui_story_5031_50311302_90_dialog_content = "但是這樣傻傻的琪爾我也很喜歡喔～",
  ui_story_5031_50311302_91_dialog_content = "我呀，就是因為信任妳，所以才相信妳一定會用100%的力量來幫助我們攔截衛兵。",
  ui_story_5031_50311302_92_dialog_content = "但是「斯提克斯」的狀態只有妳我最清楚，所以我知道後果會是什麼樣。",
  ui_story_5031_50311302_93_dialog_content = "……",
  ui_story_5031_50311302_94_dialog_content = "我也相信傑諾，我相信他們一定可以保護好「綠榴石號」。",
  ui_story_5031_50311302_95_dialog_content = "所以放心吧。",
  ui_story_5031_50311302_96_dialog_content = "等事情告一段落，我會和妳一起改進「斯提克斯」的。",
  ui_story_5031_50311302_97_dialog_content = "一定讓它變得光溜溜強壯壯，用出300%的力量都不會壞！",
  ui_story_5031_50311302_98_dialog_content = "……好。",
  ui_story_5031_50311302_99_dialog_content = "不過眼下，我們先把這些沒完沒了的傢伙解決了吧。",
  ui_story_5031_50311302_100_dialog_content = "真是的，你們好泊城的衛兵又是搞偷襲又是以多欺少。",
  ui_story_5031_50311302_101_dialog_content = "怎麼這麼沒品啊？",
  ui_story_5031_50311302_102_dialog_content = "……",
  ui_story_5031_50311401_1_dialog_content = "咳......咳咳。",
  ui_story_5031_50311401_2_dialog_content = "這樣，一切就都準備好了。",
  ui_story_5031_50311401_3_dialog_content = "只需要等候最後的棋子們落盤了。",
  ui_story_5031_50311401_4_dialog_content = "領主大人，有腳步聲靠近。",
  ui_story_5031_50311401_5_dialog_content = "好，讓他們過來吧，你們也快按照計畫離開這艘船，阻止其他人靠近。",
  ui_story_5031_50311401_6_dialog_content = "……",
  ui_story_5031_50311401_7_dialog_content = "怎麼了？",
  ui_story_5031_50311401_8_dialog_content = "您確定嗎領主大人？",
  ui_story_5031_50311401_9_dialog_content = "我還是有些不放心您一個人......",
  ui_story_5031_50311401_10_dialog_content = "你已經完成了自己的職責，接下來必須我自己來面對。",
  ui_story_5031_50311401_11_dialog_content = "……",
  ui_story_5031_50311401_12_dialog_content = "還是說，帕托，你不相信我嗎？",
  ui_story_5031_50311401_13_dialog_content = "我當然相信您！您知道我不是這個意思。",
  ui_story_5031_50311401_14_dialog_content = "相信我，那就快離開，你們在這裡反而會阻礙到計畫的進行。",
  ui_story_5031_50311401_15_dialog_content = "放心，目前一切的情況都在我的掌控之中。",
  ui_story_5031_50311401_16_dialog_content = "記得我說過的話——無論聽到什麼都不許進來。",
  ui_story_5031_50311401_17_dialog_content = "……是。",
  ui_story_5031_50311401_18_dialog_content = "請您務必小心。",
  ui_story_5031_50311401_19_dialog_content = "艾維斯！",
  ui_story_5031_50311401_20_dialog_content = "哦？跟來的竟然不是虹霞和琪爾小姐，而是卡蓮殿下和各位友人嗎？",
  ui_story_5031_50311401_21_dialog_content = "不過也沒關係，只是比我想的慢了些許。",
  ui_story_5031_50311401_22_dialog_content = "我準備工作都做完了你們還沒出現，還在擔心是否那些兵力就把你們給難住了。",
  ui_story_5031_50311401_23_dialog_content = "他說的......像是在等我們來一樣？",
  ui_story_5031_50311401_24_dialog_content = "帕托也不在他身邊，不知道他有什麼打算。",
  ui_story_5031_50311401_25_dialog_content = "總之，大家都小心為上吧。",
  ui_story_5031_50311401_26_dialog_content = "嗯。",
  ui_story_5031_50311401_27_dialog_content = "他旁邊的......就是「能源核心」嗎？",
  ui_story_5031_50311401_28_dialog_content = "應該是，我能感應到極為強大的、不同尋常的能量。",
  ui_story_5031_50311401_29_dialog_content = "但是這個「能源核心」這麼巨大，他要怎麼取走呢？",
  ui_story_5031_50311401_30_dialog_content = "艾維斯，你先聽我說。",
  ui_story_5031_50311401_31_dialog_content = "我不知道你打算如何利用「能源核心」的力量。",
  ui_story_5031_50311401_32_dialog_content = "但是我明白你的最終目的，是為了好泊城的百姓免受「摩德利失能症」的困擾。",
  ui_story_5031_50311401_33_dialog_content = "可你現在在做的事，反而會給好泊城帶來危險。",
  ui_story_5031_50311401_34_dialog_content = "一旦「能源核心」進入非正常運轉狀態，就會喚醒......",
  ui_story_5031_50311401_35_dialog_content = "會喚醒它的「守護者」。",
  ui_story_5031_50311401_36_dialog_content = "……",
  ui_story_5031_50311401_37_dialog_content = "你都知道？",
  ui_story_5031_50311401_38_dialog_content = "如果你把這個大陸上所有的典籍都翻遍了，你也會找到任何你需要的資訊。",
  ui_story_5031_50311401_39_dialog_content = "機械兵器——「核心守護者」。",
  ui_story_5031_50311401_40_dialog_content = "舊文明製造的產物，其力量足以毀滅一座小型城池。",
  ui_story_5031_50311401_41_dialog_content = "只要「能源核心」有特殊狀況，「核心守護者」就會被啟動。",
  ui_story_5031_50311401_42_dialog_content = "如果貿然操作，不但會引起「核心守護者」攻擊，甚至可能會導致「能源核心」自毀。",
  ui_story_5031_50311401_43_dialog_content = "這也是你們「真理結社」一直沒能拿到這個「能源核心」的原因，對吧？",
  ui_story_5031_50311401_44_dialog_content = "……",
  ui_story_5031_50311401_45_dialog_content = "真，真理結社？",
  ui_story_5031_50311401_46_dialog_content = "傑諾你竟然是真理結社的人？！",
  ui_story_5031_50311401_47_dialog_content = "......說來話長，雖然我對能源核心的瞭解的確來自真理結社，但是這不重要。",
  ui_story_5031_50311401_48_dialog_content = "傑諾和真理結社的事先暫且放在一邊。",
  ui_story_5031_50311401_49_dialog_content = "既然艾維斯閣下如此清楚，那為什麼還要做這種可能危害到好泊城百姓的事？",
  ui_story_5031_50311401_50_dialog_content = "危害到好泊城百姓？",
  ui_story_5031_50311401_51_dialog_content = "不不，卡蓮殿下，我和白夜城那些養尊處優的元老貴族可不一樣。",
  ui_story_5031_50311401_52_dialog_content = "我絕不會拿我子民的性命開玩笑。",
  ui_story_5031_50311401_53_dialog_content = "我這麼做，自然有我的考量。",
  ui_story_5031_50311401_54_dialog_content = "不過你們，估計不會有機會知道了。",
  ui_story_5031_50311401_55_dialog_content = "<color=#e8d9bb>嗡——</color>",
  ui_story_5031_50311401_56_dialog_content = "唔，什麼聲音，好吵呀！",
  ui_story_5031_50311401_57_dialog_content = "嘶......艾維斯，你做了什麼？",
  ui_story_5031_50311401_58_dialog_content = "既然貴賓們都到齊了，我的計畫也可以開始了。",
  ui_story_5031_50311401_59_dialog_content = "卡蓮殿下，我雖然很仰慕您的品格，但我更願意為了好泊城的未來做任何事。",
  ui_story_5031_50311401_60_dialog_content = "想要怨恨，就怨恨我吧。",
  ui_story_5031_50311401_61_dialog_content = "但封印已然不再穩固，無論如何我都要拯救好泊城。",
  ui_story_5031_50311401_62_dialog_content = "你們看，他權杖上的寶石......亮起來了！",
  ui_story_5031_50311401_63_dialog_content = "......那顆寶石......",
  ui_story_5031_50311401_64_dialog_content = "那顆寶石，正在吸收「能源核心」的能量！",
  ui_story_5031_50311401_65_dialog_content = "哦？不愧是空裔，竟然連這個都能感知到。",
  ui_story_5031_50311401_66_dialog_content = "那還真是不能留你們活口呢。",
  ui_story_5031_50311401_67_dialog_content = "不過我原本也打算這麼做就是了。",
  ui_story_5031_50311401_68_dialog_content = "「......檢測到核心狀態異常。」",
  ui_story_5031_50311401_69_dialog_content = "「自動禦敵系統已啟動，現在進行系統判斷。」",
  ui_story_5031_50311401_70_dialog_content = "啊，大方塊上面吊著的那個大機器人動起來了！",
  ui_story_5031_50311401_71_dialog_content = "糟了，這是最麻煩的情況。",
  ui_story_5031_50311401_72_dialog_content = "那個就是「核心守護者」，它馬上就要甦醒了......",
  ui_story_5031_50311401_73_dialog_content = "你們都小心點。",
  ui_story_5031_50311401_74_dialog_content = "「能源類型識別：......光能。」",
  ui_story_5031_50311401_75_dialog_content = "「系統判斷：......敵對。」",
  ui_story_5031_50311401_76_dialog_content = "「結論：開啟攻擊模式。」",
  ui_story_5031_50311401_77_dialog_content = "它身上的能量在不斷變強！",
  ui_story_5031_50311401_78_dialog_content = "菲雅，快到我身後來！",
  ui_story_5031_50311401_79_dialog_content = "唔......嗯！",
  ui_story_5031_50311402_1_dialog_content = "薇絲，傑諾，我會從左側後方進攻。",
  ui_story_5031_50311402_2_dialog_content = "拜託你們牽制「核心守護者」的進攻路線了！",
  ui_story_5031_50311402_3_dialog_content = "明白了！",
  ui_story_5031_50311402_4_dialog_content = "薇絲小心，「核心守護者」的右手臂有能量聚集！",
  ui_story_5031_50311402_5_dialog_content = "它要攻擊了！",
  ui_story_5031_50311402_6_dialog_content = "好，知道了！",
  ui_story_5031_50311402_7_dialog_content = "冰花綻放！",
  ui_story_5031_50311402_8_dialog_content = "「機體遭受攻擊。」",
  ui_story_5031_50311402_9_dialog_content = "「開始檢測受損程度。」",
  ui_story_5031_50311402_10_dialog_content = "哇塞！成功了，大機器人不動了！",
  ui_story_5031_50311402_11_dialog_content = "卡蓮姐姐好帥啊！",
  ui_story_5031_50311402_12_dialog_content = "不......它的體內，能源還在照常運作。",
  ui_story_5031_50311402_13_dialog_content = "你們還真是能幹，有點出乎我的意料。",
  ui_story_5031_50311402_14_dialog_content = "雖然對PlayerName的能力早就有所耳聞，但是親眼所見還是覺得神奇。",
  ui_story_5031_50311402_15_dialog_content = "不過......很可惜。",
  ui_story_5031_50311402_16_dialog_content = "雖然你們很努力，但憑你們的力量是沒有勝算的。",
  ui_story_5031_50311402_17_dialog_content = "「檢測完畢，未受到嚴重損傷。」",
  ui_story_5031_50311402_18_dialog_content = "「敵人攻擊力資料更新，調整攻擊輸出。」",
  ui_story_5031_50311402_19_dialog_content = "這、這是？",
  ui_story_5031_50311402_20_dialog_content = "卡蓮！它的胸口在聚集大量能量，快躲開！",
  ui_story_5031_50311402_21_dialog_content = "唔！",
  ui_story_5031_50311402_22_dialog_content = "好險。",
  ui_story_5031_50311402_23_dialog_content = "卡蓮，你沒事吧？！",
  ui_story_5031_50311402_24_dialog_content = "沒事，多虧了PlayerName的提醒，只是小擦傷而已，不必擔心。",
  ui_story_5031_50311402_25_dialog_content = "那就好，剛剛它放出的能量簡直太可怕了......",
  ui_story_5031_50311402_26_dialog_content = "房間的半面牆都被融化了。",
  ui_story_5031_50311402_27_dialog_content = "舊文明兵器的力量確實可怕。",
  ui_story_5031_50311402_28_dialog_content = "大家先小心與它周旋，尋找弱點吧。",
  ui_story_5031_50311402_29_dialog_content = "嗯，妳也小心。",
  ui_story_5031_50311402_30_dialog_content = "不過說起來，你們有沒有發現一個問題？",
  ui_story_5031_50311402_31_dialog_content = "什麼問題？",
  ui_story_5031_50311402_32_dialog_content = "為什麼「核心守護者」它只攻擊我們呢？",
  ui_story_5031_50311402_33_dialog_content = "明明站在「能源核心」旁邊的是艾維斯，在吸取「能源核心」力量的也是艾維斯。",
  ui_story_5031_50311402_34_dialog_content = "這麼說來確實是這樣。",
  ui_story_5031_50311402_35_dialog_content = "因為「核心守護者」它......",
  ui_story_5031_50311402_36_dialog_content = "……",
  ui_story_5031_50311402_37_dialog_content = "你知道原因嗎，傑諾？",
  ui_story_5031_50311402_38_dialog_content = "沒什麼。",
  ui_story_5031_50311402_39_dialog_content = "你怎麼講話只講一半呀！",
  ui_story_5031_50311402_40_dialog_content = "事到如今還要顧及我的感受嗎？",
  ui_story_5031_50311402_41_dialog_content = "你還真是一點沒變呢，傑諾。",
  ui_story_5031_50311402_42_dialog_content = "沒關係，我早就已經習慣了，你可以直接講出來告訴他們。",
  ui_story_5031_50311402_43_dialog_content = "艾維斯......",
  ui_story_5031_50311402_44_dialog_content = "告訴他們，因為「核心守護者」是透過光能來判斷敵人的。",
  ui_story_5031_50311402_45_dialog_content = "而我這個被吸走了幾乎全部光能的廢人，在它眼裡......",
  ui_story_5031_50311402_46_dialog_content = "只不過是個「死人」罷了。",
  ui_story_5031_50311402_47_dialog_content = "被，被吸走光能？",
  ui_story_5031_50311402_48_dialog_content = "這麼說起來，我在艾維斯的身上確實幾乎感覺不到光能。",
  ui_story_5031_50311402_49_dialog_content = "我一直以為這是他的病症所導致的。",
  ui_story_5031_50311402_50_dialog_content = "因果關係反了，是光能的流失，導致了他的病症。",
  ui_story_5031_50311402_51_dialog_content = "「摩德利失能症」其實是長期被吸收體內光能後，所導致的光能匱乏病症。",
  ui_story_5031_50311402_52_dialog_content = "患病的光靈會一直忍受被抽離光能的痛苦，嚴重的甚至會......",
  ui_story_5031_50311402_53_dialog_content = "那麼，如果能得到「能源核心」，就能解決「摩德利失能症」嗎？",
  ui_story_5031_50311402_54_dialog_content = "我並不清楚他的具體計畫，但應該是這樣。",
  ui_story_5031_50311402_55_dialog_content = "但是艾維斯，你聽我說。",
  ui_story_5031_50311402_56_dialog_content = "就算你得到了「能源核心」，也沒有辦法控制「核心守護者」。",
  ui_story_5031_50311402_57_dialog_content = "等我們倒下，它的目標就會指向你和好泊城。",
  ui_story_5031_50311402_58_dialog_content = "一定還有其他辦法，我們一起......",
  ui_story_5031_50311402_59_dialog_content = "沒有其他辦法了，傑諾。",
  ui_story_5031_50311402_60_dialog_content = "自從我第一次見證了有子民因為這種病症離世後，就一直在尋找解決的辦法。",
  ui_story_5031_50311402_61_dialog_content = "這幾年，每一個有可能的方案我都嘗試過，哪怕成功的希望再渺小我也沒有放棄。",
  ui_story_5031_50311402_62_dialog_content = "但我留給我的只有一次次的失望，和這副日趨無用的身體。",
  ui_story_5031_50311402_63_dialog_content = "我必須親手完成這一切，但我已經沒有時間了。",
  ui_story_5031_50311402_64_dialog_content = "但是……",
  ui_story_5031_50311402_65_dialog_content = "傑諾你不要再聊天啦，「核心守護者」朝你那邊過去了啊！",
  ui_story_5031_50311402_66_dialog_content = "<color=#e8d9bb>轟——</color>",
  ui_story_5031_50311402_67_dialog_content = "傑諾！",
  ui_story_5031_50311402_68_dialog_content = "咳、咳咳。",
  ui_story_5031_50311402_69_dialog_content = "我沒事……",
  ui_story_5031_50311402_70_dialog_content = "太好了，剛剛嚇死我了......",
  ui_story_5031_50311402_71_dialog_content = "艾維斯，你太卑鄙了！",
  ui_story_5031_50311402_72_dialog_content = "竟然引誘傑諾和你聊天，來讓他分心！",
  ui_story_5031_50311402_73_dialog_content = "呵，妳誤會我了，菲雅小姐。",
  ui_story_5031_50311402_74_dialog_content = "這並非我本意，我反而還需要你們......",
  ui_story_5031_50311402_75_dialog_content = "需要我們在你吸收「能源核心」的時候，幫你拖住「核心守護者」對吧？",
  ui_story_5031_50311402_76_dialog_content = "卡蓮殿下很聰明。",
  ui_story_5031_50311402_77_dialog_content = "至於「核心守護者」的事，看在你們擔心好泊城的居民的份上，我可以向你們透露一些。",
  ui_story_5031_50311402_78_dialog_content = "「真理結社」與我的差別在於，我擁有一樣他們所沒有的東西。",
  ui_story_5031_50311402_79_dialog_content = "我可以將「能源核心」的力量與我的血脈締結契約，讓它為我所用。",
  ui_story_5031_50311402_80_dialog_content = "等我吸收完「能源核心」，「核心守護者」也會聽我的指令。",
  ui_story_5031_50311402_81_dialog_content = "所以你們大可以放心地和這艘船一起沉睡於海底，無需替我的子民擔憂。",
  ui_story_5031_50311402_82_dialog_content = "看來，艾維斯閣下是打定主意要取我們的性命了。",
  ui_story_5031_50311402_83_dialog_content = "我很抱歉，但是我不能冒任何讓元老院那群貴族知曉的風險。",
  ui_story_5031_50311402_84_dialog_content = "既然這樣，也沒什麼好談的了。",
  ui_story_5031_50311402_85_dialog_content = "但是，不論你的出發點是否是好的，我都不會讓你傷害我的朋友。",
  ui_story_5031_50311402_86_dialog_content = "傑諾，你所召喚的幻象身上，也會有你的光能對吧？",
  ui_story_5031_50311402_87_dialog_content = "對。",
  ui_story_5031_50311402_88_dialog_content = "像剛剛那些衛兵實力水準的幻象，你能召喚多少？",
  ui_story_5031_50311402_89_dialog_content = "如果是要同時操控的話，大概十餘人。",
  ui_story_5031_50311402_90_dialog_content = "卡蓮，妳是有什麼計畫嗎？",
  ui_story_5031_50311402_91_dialog_content = "薇絲，傑諾，我想請你們幫我拖住「核心守護者」。",
  ui_story_5031_50311402_92_dialog_content = "無論怎樣，讓「能源核心」處於正常狀態，是「核心守護者」沉睡的前提。",
  ui_story_5031_50311402_93_dialog_content = "這樣的話，目標就很明確了。",
  ui_story_5031_50311402_94_dialog_content = "我去阻止艾維斯繼續吸收「能源核心」。",
  ui_story_5031_50311501_1_dialog_content = "速射感知！",
  ui_story_5031_50311501_2_dialog_content = "好，「核心守護者」被吸引過來了。",
  ui_story_5031_50311501_3_dialog_content = "卡蓮，就趁現在！",
  ui_story_5031_50311501_4_dialog_content = "儘快，召喚這麼多衛兵幻象，我撐不了太久。",
  ui_story_5031_50311501_5_dialog_content = "好，拜託你們了。",
  ui_story_5031_50311501_6_dialog_content = "咳咳、咳咳......",
  ui_story_5031_50311501_7_dialog_content = "不愧是卡蓮殿下。",
  ui_story_5031_50311501_8_dialog_content = "認識傑諾不到一天，就懂得利用他的能力形成包圍圈拖住「核心守護者」。",
  ui_story_5031_50311501_9_dialog_content = "對戰局的觀察也很清晰，再配合PlayerName的能力......",
  ui_story_5031_50311501_10_dialog_content = "我很慶幸，我從一開始就沒有輕視妳。",
  ui_story_5031_50311501_11_dialog_content = "唔？！",
  ui_story_5031_50311501_12_dialog_content = "卡蓮，妳怎麼了？！",
  ui_story_5031_50311501_13_dialog_content = "身體......使不出......力氣......",
  ui_story_5031_50311501_14_dialog_content = "力量在消逝......",
  ui_story_5031_50311501_15_dialog_content = "菲雅，妳在這躲著不要動！",
  ui_story_5031_50311501_16_dialog_content = "唔哇，PlayerName你這麼衝過去會被機器人幹掉的！",
  ui_story_5031_50311501_17_dialog_content = "......欸？大機器人竟然沒有反應？",
  ui_story_5031_50311501_18_dialog_content = "卡蓮！",
  ui_story_5031_50311501_19_dialog_content = "PlayerName......唔。",
  ui_story_5031_50311501_20_dialog_content = "（怎麼回事，卡蓮體內的光能在快速減弱？）",
  ui_story_5031_50311501_21_dialog_content = "可惡——",
  ui_story_5031_50311501_22_dialog_content = "<size=45>艾維斯，你做了什麼？！</size>",
  ui_story_5031_50311501_23_dialog_content = "很難受吧，這種光能被快速吸走的感覺。",
  ui_story_5031_50311501_24_dialog_content = "早先我為了以防萬一，在卡蓮殿下身上設下了「<color=#FFB400>保險措施</color>」。",
  ui_story_5031_50311501_25_dialog_content = "保險措施？什麼時候？",
  ui_story_5031_50311501_26_dialog_content = "等等，難道是這身衣服？",
  ui_story_5031_50311501_27_dialog_content = "你猜的沒錯。",
  ui_story_5031_50311501_28_dialog_content = "從你們詢問我進入船艙深處的方法時，我就覺得會有這麼一刻了。",
  ui_story_5031_50311501_29_dialog_content = "卡蓮殿下身上的服飾，是經過特殊加工處理的。",
  ui_story_5031_50311501_30_dialog_content = "「<color=#FFB400>光絲</color>」這種材料被催動後，會穩固地吸附在穿戴者的身上，並且快速吸收光能。",
  ui_story_5031_50311501_31_dialog_content = "所以，我建議卡蓮殿下不要再使用光能了，這樣會好受一些。",
  ui_story_5031_50311501_32_dialog_content = "妳這傢伙！",
  ui_story_5031_50311501_33_dialog_content = "抱歉......都是因為我的輕敵。",
  ui_story_5031_50311501_34_dialog_content = "不是妳的錯，卡蓮妳先......",
  ui_story_5031_50311501_35_dialog_content = "傑諾！小心！",
  ui_story_5031_50311501_36_dialog_content = "呃！",
  ui_story_5031_50311501_37_dialog_content = "傑諾，你怎麼樣？",
  ui_story_5031_50311501_38_dialog_content = "嘶，我的手臂......",
  ui_story_5031_50311501_39_dialog_content = "好像動不了了。",
  ui_story_5031_50311501_40_dialog_content = "你在流血，先不要動！",
  ui_story_5031_50311501_41_dialog_content = "「敵人負傷，啟動追擊。」",
  ui_story_5031_50311501_42_dialog_content = "啊啊！薇絲姐姐，「核心守護者」朝你們衝過去了！",
  ui_story_5031_50311501_43_dialog_content = "啊！糟，糟了！速度好快！",
  ui_story_5031_50311501_44_dialog_content = "射程......已經太近了，來不及了！",
  ui_story_5031_50311501_45_dialog_content = "住手，唔！",
  ui_story_5031_50311501_46_dialog_content = "傑，傑諾？！",
  ui_story_5031_50311501_47_dialog_content = "……",
  ui_story_5031_50311501_48_dialog_content = "昏......昏過去了？",
  ui_story_5031_50311501_49_dialog_content = "啊啊啊，怎麼辦怎麼辦怎麼辦？！",
  ui_story_5031_50311501_50_dialog_content = "咦對了，我還有這個！",
  ui_story_5031_50311501_51_dialog_content = "<color=#e8d9bb>嘭嘭——</color>",
  ui_story_5031_50311501_52_dialog_content = "「？」",
  ui_story_5031_50311501_53_dialog_content = "射中了！幸好我還帶著師父給我防身用的槍！",
  ui_story_5031_50311501_54_dialog_content = "怎，怎麼樣啊，大機器人！",
  ui_story_5031_50311501_55_dialog_content = "「遭受不明攻擊，受損程度：0。」",
  ui_story_5031_50311501_56_dialog_content = "「檢測到目標光能無消耗，判斷：優先清除。」",
  ui_story_5031_50311501_57_dialog_content = "哇啊啊！它怎麼朝我衝過來了！",
  ui_story_5031_50311501_58_dialog_content = "啊！！",
  ui_story_5031_50311501_59_dialog_content = "菲雅！",
  ui_story_5031_50311501_60_dialog_content = "……",
  ui_story_5031_50311501_61_dialog_content = "可惡，再這麼下去，真的就完了。",
  ui_story_5031_50311501_62_dialog_content = "不行，現在只有我還能戰鬥，我不能亂了陣腳。",
  ui_story_5031_50311501_63_dialog_content = "當務之急，一定要先阻止艾維斯，才能阻止「核心守護者」。",
  ui_story_5031_50311501_64_dialog_content = "……",
  ui_story_5031_50311501_65_dialog_content = "卡蓮，妳先在這裡躺一下，不要再用光能了。",
  ui_story_5031_50311501_66_dialog_content = "PlayerName......你要做什麼？",
  ui_story_5031_50311501_67_dialog_content = "我去阻止艾維斯。",
  ui_story_5031_50311501_68_dialog_content = "各位長官和醒山平日裡對我的特訓，總算能派上用場了。",
  ui_story_5031_50311501_69_dialog_content = "可是……",
  ui_story_5031_50311501_70_dialog_content = "放心吧，卡蓮。",
  ui_story_5031_50311501_71_dialog_content = "雖然我沒有光能，但面對艾維斯那個病秧子......",
  ui_story_5031_50311501_72_dialog_content = "我不會輸。",
  ui_story_5031_50311501_73_dialog_content = "......一定要小心。",
  ui_story_5031_50311501_74_dialog_content = "非常有英雄氣概的發言，令人印象深刻。",
  ui_story_5031_50311501_75_dialog_content = "但是，稱呼一個人為「病秧子」，是很沒有禮貌的。",
  ui_story_5031_50311501_76_dialog_content = "少廢話。",
  ui_story_5031_50311501_77_dialog_content = "你就閉上嘴給我——",
  ui_story_5031_50311501_78_dialog_content = "老實趴下！",
  ui_story_5031_50311501_79_dialog_content = "呵。",
  ui_story_5031_50311501_80_dialog_content = "<size=45>PlayerName！小心！！</size>",
  ui_story_5031_50311501_81_dialog_content = "「最高指令覆蓋預設指令，目標更新。」",
  ui_story_5031_50311501_82_dialog_content = "唔啊！！",
  ui_story_5031_50311501_83_dialog_content = "PlayerName！",
  ui_story_5031_50311501_84_dialog_content = "不......不......",
  ui_story_5031_50311501_85_dialog_content = "怎麼會這樣？",
  ui_story_5031_50311501_86_dialog_content = "很遺憾，就差一點呢，PlayerName。",
  ui_story_5031_50311501_87_dialog_content = "可惜「能源核心」的能量已經吸收完成了。",
  ui_story_5031_50311501_88_dialog_content = "現在，我就是「核心守護者」的主人。",
  ui_story_5031_50311501_89_dialog_content = "不然像你這種沒有光能的存在，還真的是條漏網之魚。",
  ui_story_5031_50311501_90_dialog_content = "「最高指揮權已更新，由人工接管作戰。」",
  ui_story_5031_50311501_91_dialog_content = "「自動禦敵系統已關閉。」",
  ui_story_5031_50311501_92_dialog_content = "（好疼！）",
  ui_story_5031_50311501_93_dialog_content = "（雙腿好像沒知覺了。）",
  ui_story_5031_50311501_94_dialog_content = "我看看，現在還有行動能力的——",
  ui_story_5031_50311501_95_dialog_content = "只有薇絲小姐了嗎？",
  ui_story_5031_50311501_96_dialog_content = "去吧，把她解決掉，然後我們去下一個地方。",
  ui_story_5031_50311501_97_dialog_content = "「收到最新指示，目標變更。」",
  ui_story_5031_50311501_98_dialog_content = "（糟了，薇絲！）",
  ui_story_5031_50311501_99_dialog_content = "<size=33>薇絲......快逃......</size>",
  ui_story_5031_50311501_100_dialog_content = "哦？竟然還能站起來？",
  ui_story_5031_50311501_101_dialog_content = "<size=33>什麼？</size>",
  ui_story_5031_50311501_102_dialog_content = "卡蓮殿下，雖然您此刻還能爆發出這樣的能量，屬實令人欽佩。",
  ui_story_5031_50311501_103_dialog_content = "但恕我直言，這樣只會加速您的死亡。",
  ui_story_5031_50311501_104_dialog_content = "<size=33>卡，卡蓮？</size>",
  ui_story_5031_50311501_105_dialog_content = "都是因為我......",
  ui_story_5031_50311501_106_dialog_content = "卡蓮殿下？",
  ui_story_5031_50311501_107_dialog_content = "都是......因為我......",
  ui_story_5031_50311501_108_dialog_content = "啊，因為光能盡失，已經快要失去意識了嗎？",
  ui_story_5031_50311501_109_dialog_content = "真是可敬，自己都這副樣子了，竟然無意識還想著要保護同伴。",
  ui_story_5031_50311501_110_dialog_content = "「發現新活動目標，是否進行攻擊？」",
  ui_story_5031_50311501_111_dialog_content = "不用，她造成不了威脅。",
  ui_story_5031_50311501_112_dialog_content = "<size=45>卡蓮，快停下......！</size>",
  ui_story_5031_50311501_113_dialog_content = "（可惡，發不出聲音來。）",
  ui_story_5031_50311501_114_dialog_content = "（這樣的話——）",
  ui_story_5031_50311501_115_option_content = "強制感應！",
  ui_story_5031_50311501_116_dialog_content = "如果妳治理的城市被暗鬼進攻了，妳準備怎麼辦？",
  ui_story_5031_50311501_117_dialog_content = "（欸？舒瓦茲的聲音？）",
  ui_story_5031_50311501_118_dialog_content = "（這是......夢境？是因為卡蓮快失去意識了嗎？）",
  ui_story_5031_50311501_119_dialog_content = "我會馬上組織部隊，進行禦敵。",
  ui_story_5031_50311501_120_dialog_content = "這時另一支暗鬼從妳的防禦薄弱處進攻。",
  ui_story_5031_50311501_121_dialog_content = "我會率領預備軍趕去。",
  ui_story_5031_50311501_122_dialog_content = "此時會鑽地挖掘的暗鬼從城市中心出現了。",
  ui_story_5031_50311501_123_dialog_content = "讓將士守住陣地，我......",
  ui_story_5031_50311501_124_dialog_content = "暗鬼一開始進攻的城牆再次遇到了危機。",
  ui_story_5031_50311501_125_dialog_content = "……",
  ui_story_5031_50311501_126_dialog_content = "我，我會打敗所有暗鬼。",
  ui_story_5031_50311501_127_dialog_content = "妳我都知道暗鬼是殺不完的。",
  ui_story_5031_50311501_128_dialog_content = "……",
  ui_story_5031_50311501_129_dialog_content = "看來妳離成為一名優秀的君主，還很遠啊......",
  ui_story_5031_50311501_130_dialog_content = "白夜城還遠遠無法仰仗妳。",
  ui_story_5031_50311501_131_dialog_content = "父，父親？",
  ui_story_5031_50311501_132_dialog_content = "明明我將妳送往北境，師從伯利恆，妳卻沒有長進。",
  ui_story_5031_50311501_133_dialog_content = "力量不夠，謀略不足。",
  ui_story_5031_50311501_134_dialog_content = "因此妳才失去了你的朋友們。",
  ui_story_5031_50311501_135_dialog_content = "他們受傷、失去生命，都是因為妳啊，卡蓮殿下。",
  ui_story_5031_50311501_136_dialog_content = "我……我……",
  ui_story_5031_50311501_137_dialog_content = "卡蓮，我是那麼相信妳，聽妳的作戰安排。",
  ui_story_5031_50311501_138_dialog_content = "但是結果呢？",
  ui_story_5031_50311501_139_dialog_content = "我和PlayerName因為妳，都要喪命於此了。",
  ui_story_5031_50311501_140_dialog_content = "薇絲，對不起......我......",
  ui_story_5031_50311501_141_dialog_content = "卡蓮！妳看清楚，那不是薇絲！",
  ui_story_5031_50311501_142_dialog_content = "這聲音是……",
  ui_story_5031_50311501_143_dialog_content = "PlayerName？",
  ui_story_5031_50311501_144_dialog_content = "對，是我！",
  ui_story_5031_50311501_145_dialog_content = "對不起......我竟然沒有意識到卡蓮妳的內心一直都如此煎熬。",
  ui_story_5031_50311501_146_dialog_content = "但是，薇絲絕對不會說出這種話，妳眼前的都是幻影不是真的！",
  ui_story_5031_50311501_147_dialog_content = "妳還想要逃避嗎？逃避自己的責任？",
  ui_story_5031_50311501_148_dialog_content = "真可悲啊，明明嘴上一直叫喊著要保護別人，卻如此弱小。",
  ui_story_5031_50311501_149_dialog_content = "一位君主，不該是妳這副樣子。",
  ui_story_5031_50311501_150_dialog_content = "我......",
  ui_story_5031_50311501_151_dialog_content = "卡蓮，妳聽我說。",
  ui_story_5031_50311501_152_dialog_content = "妳並不需要時時刻刻扛起身為君主的重擔和責任！",
  ui_story_5031_50311501_153_dialog_content = "在我和薇絲面前，妳就是卡蓮，只是卡蓮！",
  ui_story_5031_50311501_154_dialog_content = "欸？",
  ui_story_5031_50311501_154X1_dialog_content = "卡蓮妳還記得嗎？薇絲曾經說過的那句話！",
  ui_story_5031_50311501_154X2_dialog_content = "妳絕對不可以在自己的執念中沉淪下去！",
  ui_story_5031_50311501_154X3_dialog_content = "我的，執念......",
  ui_story_5031_50311501_154X4_dialog_content = "因為在那個過程中，我像是墜入深淵般沉睡，一度以為自己永遠醒不過來了。",
  ui_story_5031_50311501_154X5_dialog_content = "我不斷努力思考和回想曾經時的自己，生怕稍微放鬆就會失去自我。",
  ui_story_5031_50311501_154X6_dialog_content = "我也看到了很多神奇的場景，就像是真的身臨其境一樣。",
  ui_story_5031_50311501_154X7_dialog_content = "那些幻覺就像是真的一樣，就像是對我的考驗。",
  ui_story_5031_50311501_154X8_dialog_content = "幸好，我最後抓住了意識之海中的一縷光芒，堅持到了最後。",
  ui_story_5031_50311501_154X9_dialog_content = "光芒？我記得妳之前也提到過，它究竟是什麼？",
  ui_story_5031_50311501_154X10_dialog_content = "唔，就是我會想到和妳，還有PlayerName的一些有趣的經歷。",
  ui_story_5031_50311501_154X11_dialog_content = "然後不知不覺地，內心就會變得平和下來。",
  ui_story_5031_50311501_154X12_dialog_content = "是的，卡蓮，不要放棄，不要失去自我！",
  ui_story_5031_50311501_155_dialog_content = "我們是並肩作戰，共同進退的同伴。",
  ui_story_5031_50311501_156_dialog_content = "是託付後背給彼此的戰友。",
  ui_story_5031_50311501_157_dialog_content = "遇到任何困難，我們不需要妳去承擔什麼君王的責任。",
  ui_story_5031_50311501_158_dialog_content = "妳不需要一個人硬抗一切，保護我們。",
  ui_story_5031_50311501_159_dialog_content = "我們應該一同進退，一起去想辦法，一起面對才對啊！",
  ui_story_5031_50311501_160_dialog_content = "PlayerName......",
  ui_story_5031_50311501_161_dialog_content = "無論發生什麼，我和薇絲，絕——對——！不會對妳有怪罪的想法！",
  ui_story_5031_50311501_162_dialog_content = "所以，振作起來，卡蓮！不要被眼前的假象蒙蔽內心！",
  ui_story_5031_50311501_163_dialog_content = "真正的薇絲還在為了守護我們而戰鬥，她還沒有放棄。",
  ui_story_5031_50311501_164_dialog_content = "她需要妳！",
  ui_story_5031_50311501_165_dialog_content = "……",
  ui_story_5031_50311501_166_dialog_content = "你說得對，PlayerName。",
  ui_story_5031_50311501_167_dialog_content = "我的同伴還在堅持戰鬥，我怎麼可以自怨自艾。",
  ui_story_5031_50311501_168_dialog_content = "那麼，妳要選擇忽視妳犯下的錯誤？",
  ui_story_5031_50311501_169_dialog_content = "明明是妳的輕敵和無能——",
  ui_story_5031_50311501_170_dialog_content = "導致了現在的局面。",
  ui_story_5031_50311501_171_dialog_content = "是的，但是我不會再執著於自己的正確與錯誤。",
  ui_story_5031_50311501_172_dialog_content = "……",
  ui_story_5031_50311501_173_dialog_content = "因為這沒有意義，如果犯下了錯......",
  ui_story_5031_50311501_174_dialog_content = "那我就努力將它變為正確的。",
  ui_story_5031_50311501_175_dialog_content = "......如果這就是妳所認定的「王道」。",
  ui_story_5031_50311501_176_dialog_content = "那麼希望妳能，一直堅守這份信念。",
  ui_story_5031_50311501_176X1_dialog_content = "我會的。",
  ui_story_5031_50311501_176X2_dialog_content = "因為我......",
  ui_story_5031_50311501_176X3_dialog_content = "找到屬於我的那縷光了。",
  ui_story_5031_50311501_177_dialog_content = "欸，場景——",
  ui_story_5031_50311501_178_dialog_content = "薇絲，抱歉讓妳久等了。",
  ui_story_5031_50311501_179_dialog_content = "卡蓮！",
  ui_story_5031_50311501_180_dialog_content = "「警報：檢測到大量光能出現，判斷危險等級高。」",
  ui_story_5031_50311501_181_dialog_content = "「立即對目標執行清除。」",
  ui_story_5031_50311501_182_dialog_content = "光芒！暉映！",
  ui_story_5031_50311501_183_dialog_content = "怎，怎麼可能？",
  ui_story_5031_50311501_184_dialog_content = "明明「<color=#FFB400>光絲</color>」還在吸收她的光能！",
  ui_story_5031_50311501_185_dialog_content = "卡蓮身上......在源源不斷湧現著光能？",
  ui_story_5031_50311501_186_dialog_content = "這是怎麼回事？",
  ui_story_5031_50311501_187_dialog_content = "無謂的自我質疑、焦慮，只會徒增煩惱，擾亂思緒。",
  ui_story_5031_50311501_188_dialog_content = "戰局瞬息萬變，無論是何種身分，都應當著眼於當下時局，而不是內心的恐懼。",
  ui_story_5031_50311501_189_dialog_content = "薇絲，接下來的戰鬥，就由我來和妳一同面對。",
  ui_story_5031_50311501_190_dialog_content = "卡蓮，妳的身體沒事嗎？",
  ui_story_5031_50311501_191_dialog_content = "不知道為什麼，我的體內此刻正不停地出現新的能量。",
  ui_story_5031_50311501_192_dialog_content = "但是不論是什麼原因，眼下我的目標只有一個——",
  ui_story_5031_50311501_193_dialog_content = "那就是和妳一起，擊潰面前的敵人。",
  ui_story_5031_50311501_194_dialog_content = "嗯！",
  ui_story_5031_50311501_195_dialog_content = "「警報：檢測到大量光能出現，判斷危險等級為極高。」",
  ui_story_5031_50311501_196_dialog_content = "「啟動決戰模式。」",
  ui_story_5031_50311502_1_dialog_content = "「警告......機體受損程度大於70%。」",
  ui_story_5031_50311502_2_dialog_content = "「右臂失去連結，無法自動修復。」",
  ui_story_5031_50311502_3_dialog_content = "薇絲，妳還好嗎？",
  ui_story_5031_50311502_4_dialog_content = "還好，只是遠程牽制敵人，不會消耗太多力量！",
  ui_story_5031_50311502_5_dialog_content = "好，那接下來我們集中進攻它的右側。",
  ui_story_5031_50311502_6_dialog_content = "它的右手臂已經癱瘓，無論攻擊還是防禦都會受到影響。",
  ui_story_5031_50311502_7_dialog_content = "好！",
  ui_story_5031_50311502_8_dialog_content = "卡蓮殿下，不得不說，您確實是出乎我的意料。",
  ui_story_5031_50311502_9_dialog_content = "哪怕站在不同立場，您也令我由衷感到欽佩。",
  ui_story_5031_50311502_10_dialog_content = "但是，我也有著不能失敗的理由。",
  ui_story_5031_50311502_11_dialog_content = "因此請原諒我先行告退，不能欣賞各位在這場華麗演出當中的完美謝幕了。",
  ui_story_5031_50311502_12_dialog_content = "艾維斯，站住！",
  ui_story_5031_50311502_13_dialog_content = "攔住她們。",
  ui_story_5031_50311502_14_dialog_content = "薇絲小心！不要背對「核心守護者」！",
  ui_story_5031_50311502_15_dialog_content = "哇啊！",
  ui_story_5031_50311502_16_dialog_content = "……",
  ui_story_5031_50311502_17_dialog_content = "可惡，讓他逃掉了。",
  ui_story_5031_50311502_18_dialog_content = "沒關係，艾維斯的事等我們出去後再想辦法吧。",
  ui_story_5031_50311502_19_dialog_content = "嗯，也對。",
  ui_story_5031_50311502_20_dialog_content = "現在先解決「核心守護者」的問題。",
  ui_story_5031_50311502_21_dialog_content = "既然如此，我們......嗯？",
  ui_story_5031_50311502_22_dialog_content = "怎麼了，卡蓮？",
  ui_story_5031_50311502_23_dialog_content = "（卡蓮的光能忽然又變強了？）",
  ui_story_5031_50311502_24_dialog_content = "這件衣服好像不再吸收我的光能了。",
  ui_story_5031_50311502_25_dialog_content = "是因為艾維斯離開了嗎？",
  ui_story_5031_50311502_26_dialog_content = "這麼說來，之前妳穿著這件衣服也都沒事。",
  ui_story_5031_50311502_27_dialog_content = "看來這種功能必須要艾維斯來催動才能生效。",
  ui_story_5031_50311502_28_dialog_content = "既然如此，那我就無需保留了。",
  ui_story_5031_50311502_29_dialog_content = "在這台敵我不分的蠢機器毀了這艘船之前，讓我們先來給它最後一擊吧。",
  ui_story_5031_50311502_30_dialog_content = "嗯！傑諾醒來以後，得好好感謝我們才行呢。",
  ui_story_5031_50311502_31_dialog_content = "你們這是要造反嗎？",
  ui_story_5031_50311502_32_dialog_content = "領主正在和馬戲團團長敘舊，下令不許任何人上船。",
  ui_story_5031_50311502_33_dialog_content = "我們也是奉命行事，希望您能理解。",
  ui_story_5031_50311502_34_dialog_content = "你們這個架勢，看起來可不是單純在看家護院啊。",
  ui_story_5031_50311502_35_dialog_content = "而且船上從剛剛開始就傳來爆破的聲音。",
  ui_story_5031_50311502_36_dialog_content = "敘舊？這是有仇吧。",
  ui_story_5031_50311502_37_dialog_content = "不擔心你們主人嗎？他看起來那麼瘦，根本禁不住那個傑諾兩拳吧？",
  ui_story_5031_50311502_38_dialog_content = "......請您離開。",
  ui_story_5031_50311502_39_dialog_content = "哦？這是什麼意思，要動手嗎？",
  ui_story_5031_50311502_40_dialog_content = "那你們可得做好準備了，之後我會將一切如實上報給......",
  ui_story_5031_50311502_41_dialog_content = "帕托，不得無禮。",
  ui_story_5031_50311502_42_dialog_content = "領主大人！",
  ui_story_5031_50311502_43_dialog_content = "唷，這不是艾維斯閣下嗎，您敘完舊了？",
  ui_story_5031_50311502_44_dialog_content = "很抱歉讓馬太大人久等了，方才我和舊友有要事相談。",
  ui_story_5031_50311502_45_dialog_content = "帕托他們也是執行命令而已，請您別見怪。",
  ui_story_5031_50311502_46_dialog_content = "既然如此，我現在是不是能上船了？",
  ui_story_5031_50311502_47_dialog_content = "您請便。",
  ui_story_5031_50311502_48_dialog_content = "<size=33>領主大人，就這樣放他進去？</size>",
  ui_story_5031_50311502_49_dialog_content = "<size=33>無礙，馬上這艘船就會被炸毀了。</size>",
  ui_story_5031_50311502_50_dialog_content = "<size=33>比起這裡，我得馬上前往......</size>",
  ui_story_5031_50311502_51_dialog_content = "對了，艾維斯閣下。",
  ui_story_5031_50311502_52_dialog_content = "......什麼事？",
  ui_story_5031_50311502_53_dialog_content = "想問問您，剛剛在船上有見到我們卡蓮殿下嗎？",
  ui_story_5031_50311502_54_dialog_content = "沒有，卡蓮殿下他們也在船上嗎？",
  ui_story_5031_50311502_55_dialog_content = "那就怪了，剛剛慶典結束我就在這裡等，但一直沒有見到殿下的身影。",
  ui_story_5031_50311502_56_dialog_content = "她也沒下船，也沒找你們，那她留在船上幹什麼呢？",
  ui_story_5031_50311502_57_dialog_content = "興許是在與船上新結識的友人告別吧。",
  ui_story_5031_50311502_58_dialog_content = "畢竟這一天的活動下來，他們之間也較為熟識了。",
  ui_story_5031_50311502_59_dialog_content = "我這個保鏢做得像個保姆一樣，今天一整天都在盯著卡蓮殿下，生怕她受傷。",
  ui_story_5031_50311502_60_dialog_content = "所以，我觀察到她其實和這幾個馬戲團的人，好像沒什麼太多的交集吧？",
  ui_story_5031_50311502_61_dialog_content = "但是，薇絲小姐與琪爾小姐本就是舊識。",
  ui_story_5031_50311502_62_dialog_content = "PlayerName又與虹霞小姐相談甚歡......",
  ui_story_5031_50311502_63_dialog_content = "打斷您一下，艾維斯閣下。",
  ui_story_5031_50311502_64_dialog_content = "……嗯？",
  ui_story_5031_50311502_65_dialog_content = "我剛剛好像沒有提到其他人吧？",
  ui_story_5031_50311502_66_dialog_content = "艾維斯閣下又沒有見到殿下，怎麼能這麼確定卡蓮殿下與他們在一起呢？",
  ui_story_5031_50311502_67_dialog_content = "……",
  ui_story_5031_50311502_68_dialog_content = "那是因為他們四人關係很好，一直在一起行動。",
  ui_story_5031_50311502_69_dialog_content = "您也是第一天認識他們吧，怎麼知道的他們關係好不好啊？",
  ui_story_5031_50311502_70_dialog_content = "我跟我那位裹得嚴嚴實實的搭檔關係也很好，他現在不也不在這裡？",
  ui_story_5031_50311502_71_dialog_content = "……",
  ui_story_5031_50311502_72_dialog_content = "帕托。",
  ui_story_5031_50311502_73_dialog_content = "沒錯。",
  ui_story_5031_50311502_74_dialog_content = "啊哈，被戳穿了就要滅口嗎？",
  ui_story_5031_50311502_75_dialog_content = "不錯啊，這股陰狠勁。",
  ui_story_5031_50311502_76_dialog_content = "不過你可能不知道，我們那位城主殿下表面上看起來冷冰冰的，實際上可是個女兒控。",
  ui_story_5031_50311502_77_dialog_content = "所以你覺得，我們這些做保鏢的，會是那種你能輕易解決掉的角色嗎？",
  ui_story_5031_50311502_78_dialog_content = "洛維！是時候出場了！",
  ui_story_5031_50311502_79_dialog_content = "什麼？",
  ui_story_5031_50311502_80_dialog_content = "......廢話真多，馬太。",
  ui_story_5031_50311502_81_dialog_content = "呿，要你管？",
  ui_story_5031_50311502_82_dialog_content = "兩個人？",
  ui_story_5031_50311502_83_dialog_content = "你們打算憑藉兩個人的力量，對抗我的衛兵們？",
  ui_story_5031_50311502_84_dialog_content = "錯了，是一個人。",
  ui_story_5031_50311502_85_dialog_content = "那這裡交給你了啊洛維，我進去救人去了。",
  ui_story_5031_50311502_86_dialog_content = "……",
  ui_story_5031_50311502_87_dialog_content = "不必了。",
  ui_story_5031_50311502_88_dialog_content = "嗯？這聲音是......",
  ui_story_5031_50311502_89_dialog_content = "什......什麼？！",
  ui_story_5031_50311502_90_dialog_content = "多虧有二位閣下攔下了艾維斯。",
  ui_story_5031_50311502_91_dialog_content = "幫大忙了。",
  ui_story_5031_50311502_92_dialog_content = "卡蓮殿下！看見您還活著真是太美好了。",
  ui_story_5031_50311502_93_dialog_content = "不，不可能！",
  ui_story_5031_50311502_94_dialog_content = "「核心守護者」呢？為什麼船還沒有爆炸？",
  ui_story_5031_50311502_95_dialog_content = "抗不下卡蓮的全力一擊，現在已經成一堆破銅爛鐵了。",
  ui_story_5031_50311502_96_dialog_content = "不過說起來那個「核心守護者」的構造可真是不得了啊！",
  ui_story_5031_50311502_97_dialog_content = "可惜我們趕到的時候它已經動不了了。",
  ui_story_5031_50311502_98_dialog_content = "沒關係，現在這個樣子也很值得研究。",
  ui_story_5031_50311502_99_dialog_content = "說的也是～",
  ui_story_5031_50311502_100_dialog_content = "為什麼，為什麼明明有「光絲」的壓制，還能使用出這樣的力量？",
  ui_story_5031_50311502_101_dialog_content = "......不對，「光絲」竟然停止吸收了？",
  ui_story_5031_50311502_102_dialog_content = "「光絲」不是艾維斯操控的嗎？",
  ui_story_5031_50311502_103_dialog_content = "難道是......已經達到最大吸收負荷了？！",
  ui_story_5031_50311502_104_dialog_content = "不可能，這身衣服應該能吸收兩三個光靈的全部光能！",
  ui_story_5031_50311502_105_dialog_content = "什麼原因並不重要。",
  ui_story_5031_50311502_106_dialog_content = "重要的是，艾維斯，你的計畫失敗了。",
  ui_story_5031_50311502_107_dialog_content = "放棄抵抗吧，你已經逃不掉了。",
  ui_story_5031_50311502_108_dialog_content = "不，不行......我不能失敗！我絕不能失敗！",
  ui_story_5031_50311502_109_dialog_content = "「<color=#FFB400>封印</color>」馬上就要......",
  ui_story_5031_50311502_110_dialog_content = "......帕托！",
  ui_story_5031_50311502_111_dialog_content = "是！",
  ui_story_5031_50311502_112_dialog_content = "無謂的抵抗。",
  ui_story_5031_50311502_113_dialog_content = "可惡……",
  ui_story_5031_50311502_114_dialog_content = "領主大人，趁現在！",
  ui_story_5031_50311502_115_dialog_content = "這麼多人在場，要是讓你逃了，傳出去豈不讓人笑掉大牙？",
  ui_story_5031_50311502_116_dialog_content = "唔！",
  ui_story_5031_50311502_117_dialog_content = "......不是吧？我只是「輕輕碰了他一下」，他就倒下了？",
  ui_story_5031_50311502_118_dialog_content = "這人是有多弱啊？",
  ui_story_5031_50311502_119_dialog_content = "領主大人！",
  ui_story_5031_50311502_120_dialog_content = "妳的對手是我。",
  ui_story_5031_50311502_121_dialog_content = "唔......該死！",
  ui_story_5031_50311502_122_dialog_content = "你們，一個都跑不了。",
  ui_story_5031_50311601_1_dialog_content = "那虹霞，小琪爾就交給妳了喔！",
  ui_story_5031_50311601_2_dialog_content = "放心吧長官～我會照顧好琪爾的！",
  ui_story_5031_50311601_3_dialog_content = "菲爾姆也會一起照顧琪爾姐姐的喔！",
  ui_story_5031_50311601_4_dialog_content = "薩布莉也是！",
  ui_story_5031_50311601_5_dialog_content = "梅，梅爾特也是。",
  ui_story_5031_50311601_6_dialog_content = "喔！非常可靠呢！",
  ui_story_5031_50311601_7_dialog_content = "謝，謝謝貢露長官，允許我留下來。",
  ui_story_5031_50311601_8_dialog_content = "沒事沒事，最近又沒什麼任務。",
  ui_story_5031_50311601_9_dialog_content = "小琪爾就在這裡好好放鬆一下吧～",
  ui_story_5031_50311601_10_dialog_content = "真的可以嗎......放著那個能源核心不管？",
  ui_story_5031_50311601_11_dialog_content = "喔～那個只是「小型動力核心」喔，對啟光來說不算非常珍貴的東西。",
  ui_story_5031_50311601_12_dialog_content = "雖然和「能源核心」很相似，但各方面都要差很多，輸出的能源純度也完全不夠。",
  ui_story_5031_50311601_13_dialog_content = "再加上被那位領主一通胡亂操作，已經基本報廢啦。",
  ui_story_5031_50311601_14_dialog_content = "要說研究價值的話......說不定能給妳升級「斯提克斯」提供一些想法。",
  ui_story_5031_50311601_15_dialog_content = "可惡啊，其實我還沒研究夠這艘航船本身呢，為什麼要這個時候召回我嘛。",
  ui_story_5031_50311601_15X1_dialog_content = "琪爾，妳幫他們修理核心的時候，也要順便多看看傳動系統喔！",
  ui_story_5031_50311601_15X2_dialog_content = "好好整理成筆記，等妳回來之後我還要看的！",
  ui_story_5031_50311601_15X3_dialog_content = "我，我知道了......",
  ui_story_5031_50311601_16_dialog_content = "哇，妳們在說悄悄話！",
  ui_story_5031_50311601_17_dialog_content = "薩布莉也要聽！",
  ui_story_5031_50311601_18_dialog_content = "如，如果說給我們聽，就不叫悄悄話了......",
  ui_story_5031_50311601_19_dialog_content = "唔，好像也對呢？",
  ui_story_5031_50311601_20_dialog_content = "那就不聽了嘛～",
  ui_story_5031_50311601_21_dialog_content = "很好，這樣才是乖孩......",
  ui_story_5031_50311601_22_dialog_content = "您說什麼？！",
  ui_story_5031_50311601_23_dialog_content = "唔哇，是誰這麼吵？",
  ui_story_5031_50311601_24_dialog_content = "您是認真的嗎卡蓮殿下？",
  ui_story_5031_50311601_25_dialog_content = "您真的要留在這裡，代......代理執政？",
  ui_story_5031_50311601_26_dialog_content = "嗯。",
  ui_story_5031_50311601_27_dialog_content = "可是艾維斯竟然對您兵刃相向，這性質已經相當於謀反了！",
  ui_story_5031_50311601_28_dialog_content = "舒瓦茲殿下不會同意的！",
  ui_story_5031_50311601_29_dialog_content = "因此，我需要二位閣下的幫助。",
  ui_story_5031_50311601_30_dialog_content = "......我怎麼有一種非常糟糕的預感。",
  ui_story_5031_50311601_31_dialog_content = "我希望您和洛維閣下，能在報告中隱瞞這部分內容。",
  ui_story_5031_50311601_32_dialog_content = "並且，希望二位閣下，也能陪我留在好泊城一段時日。",
  ui_story_5031_50311601_33_dialog_content = "不行。",
  ui_story_5031_50311601_34_dialog_content = "抱歉，卡蓮閣下，這是來自伊倫汀大人的命令。",
  ui_story_5031_50311601_35_dialog_content = "我有義務對她保持絕對的忠誠。",
  ui_story_5031_50311601_36_dialog_content = "……",
  ui_story_5031_50311601_37_dialog_content = "我明白，馬太閣下，我對您的忠心沒有任何的懷疑。",
  ui_story_5031_50311601_38_dialog_content = "但是我也不想給您和洛維閣下惹麻煩。",
  ui_story_5031_50311601_39_dialog_content = "畢竟我身上的傷口共縫了十七針，還因為之前過度消耗導致暫時無法使用光能。",
  ui_story_5031_50311601_40_dialog_content = "如果被伊倫汀殿下或舒瓦茲殿下知道了，應該會很麻煩吧。",
  ui_story_5031_50311601_41_dialog_content = "呃，這個……",
  ui_story_5031_50311601_42_dialog_content = "當然，這是我自己的疏忽所致，與二位無關，我現在也並無大礙。",
  ui_story_5031_50311601_43_dialog_content = "醫生們也說，只要修養一段時日，我的身體就能完全恢復。",
  ui_story_5031_50311601_44_dialog_content = "所以如果二位想要避免一些不必要的責難，我是非常願意配合的。",
  ui_story_5031_50311601_45_dialog_content = "……",
  ui_story_5031_50311601_46_dialog_content = "為什麼？",
  ui_story_5031_50311601_47_dialog_content = "什麼？",
  ui_story_5031_50311601_48_dialog_content = "為什麼卡蓮殿下您執意留在這裡？",
  ui_story_5031_50311601_49_dialog_content = "為什麼要替艾維斯隱瞞罪行？",
  ui_story_5031_50311601_50_dialog_content = "因為首先我判斷，他所做的這一切，都是為了好泊城的子民。",
  ui_story_5031_50311601_51_dialog_content = "其次，歷年來好泊城都是白夜城的附庸，領主艾維斯也曾在白夜城學習過。",
  ui_story_5031_50311601_52_dialog_content = "但是遇到了問題他卻不向白夜城求助，而是自己調查，甚至提防著白夜城。",
  ui_story_5031_50311601_53_dialog_content = "二位閣下認為，這意味著什麼？",
  ui_story_5031_50311601_54_dialog_content = "……",
  ui_story_5031_50311601_55_dialog_content = "這是因為，他認為這件事我們白夜城並不能，或者不會幫他解決。",
  ui_story_5031_50311601_56_dialog_content = "身為附庸城的領主，卻不相信我們，這才是反叛的種子。",
  ui_story_5031_50311601_57_dialog_content = "我們不能保證下一任領主在面對這個問題時，不會做出和艾維斯一樣的選擇。",
  ui_story_5031_50311601_58_dialog_content = "如果這件事的真相一直不去查明，問題懸而未決，只會變成一根永遠紮在肉裡的刺。",
  ui_story_5031_50311601_59_dialog_content = "所以，我想要調查清楚，艾維斯的真正目的到底是什麼。",
  ui_story_5031_50311601_60_dialog_content = "然後在種子發芽前，由我們來親手將這根刺拔除。",
  ui_story_5031_50311601_61_dialog_content = "……",
  ui_story_5031_50311601_62_dialog_content = "呵呵，在我看來，您一直就是個天真的，被保護得太好的小公主而已。",
  ui_story_5031_50311601_63_dialog_content = "......？",
  ui_story_5031_50311601_64_dialog_content = "但是——",
  ui_story_5031_50311601_65_dialog_content = "剛剛這段發言，不得不說還像點樣子。",
  ui_story_5031_50311601_66_dialog_content = "是吧，洛維？",
  ui_story_5031_50311601_67_dialog_content = "嗯。",
  ui_story_5031_50311601_68_dialog_content = "那……",
  ui_story_5031_50311601_69_dialog_content = "不過！",
  ui_story_5031_50311601_70_dialog_content = "……",
  ui_story_5031_50311601_71_dialog_content = "欺瞞伊倫汀大人這種事，我們是絕對不會做的。",
  ui_story_5031_50311601_72_dialog_content = "所以今晚用餐時，我們還是會透過信使公會向伊倫汀大人如實匯報。",
  ui_story_5031_50311601_73_dialog_content = "對了，那家信使公會在哪來著？",
  ui_story_5031_50311601_74_dialog_content = "白......白什麼來著？洛維？",
  ui_story_5031_50311601_75_dialog_content = "……",
  ui_story_5031_50311601_76_dialog_content = "「白珍珠街道」上，「幸福花園餐廳」旁邊。",
  ui_story_5031_50311601_77_dialog_content = "啊對，就是這個地址。",
  ui_story_5031_50311601_78_dialog_content = "那今晚就你去送吧，就這麼說定了。",
  ui_story_5031_50311601_79_dialog_content = "……",
  ui_story_5031_50311601_80_dialog_content = "為什麼不是你去送？",
  ui_story_5031_50311601_81_dialog_content = "因為我還要在附近巡視。",
  ui_story_5031_50311601_82_dialog_content = "這麼危險的情況，肯定需要綜合實力更強的人來負責保衛卡蓮殿下的安全。",
  ui_story_5031_50311601_83_dialog_content = "……",
  ui_story_5031_50311601_84_dialog_content = "幹嘛？要打架？",
  ui_story_5031_50311601_85_dialog_content = "哼，奉陪。",
  ui_story_5031_50311601_86_dialog_content = "走走走，去那邊空地上去練，今天一定要讓你服氣。",
  ui_story_5031_50311601_87_dialog_content = "做夢。",
  ui_story_5031_50311601_88_dialog_content = "……",
  ui_story_5031_50311601_89_dialog_content = "卡蓮，你們談妥了嗎？",
  ui_story_5031_50311601_90_dialog_content = "這兩個人怎麼邊走邊吵起來了？",
  ui_story_5031_50311601_91_dialog_content = "他們從前就是這樣的關係，打打鬧鬧，卻從未分開。",
  ui_story_5031_50311601_92_dialog_content = "至於報告這邊......",
  ui_story_5031_50311601_93_dialog_content = "應該是談妥了。",
  ui_story_5031_50311601_94_dialog_content = "那就好~",
  ui_story_5031_50311601_95_dialog_content = "這兩個人雖然看起來奇奇怪怪的，但是意外的是很好的人呢。",
  ui_story_5031_50311601_96_dialog_content = "不過你們兩個的身體真的沒問題嗎？",
  ui_story_5031_50311601_97_dialog_content = "可以不用陪我留在這裡的。",
  ui_story_5031_50311601_98_dialog_content = "妳現在的狀況，讓妳一人留在這裡調查我們怎麼可能放心啊。",
  ui_story_5031_50311601_98X1_dialog_content = "之前妳的光能就像不受控制一樣不停外溢，我們逃出去後沒多久妳就昏倒了......",
  ui_story_5031_50311601_98X2_dialog_content = "真是把我們嚇了一大跳！",
  ui_story_5031_50311601_98X3_dialog_content = "抱歉，讓你們擔心了。",
  ui_story_5031_50311601_98X4_dialog_content = "不過卡蓮是如何做到突然間覺醒新力量呢？簡直太神奇了。",
  ui_story_5031_50311601_98X5_dialog_content = "當時......我感覺就像薇絲妳之前所描述的一樣。",
  ui_story_5031_50311601_98X6_dialog_content = "我見到了那些內心中困擾我許久的顧慮。",
  ui_story_5031_50311601_98X7_dialog_content = "它們是那麼真實，那麼令人難過、窒息。",
  ui_story_5031_50311601_98X8_dialog_content = "卡蓮......",
  ui_story_5031_50311601_98X9_dialog_content = "幸好當時PlayerName連結了我的意識，把我從那個深淵拉了回來。",
  ui_story_5031_50311601_98X10_dialog_content = "讓我意識到，你們就是我的那縷光芒。",
  ui_story_5031_50311601_98X11_dialog_content = "謝謝你，PlayerName。也謝謝妳，薇絲。",
  ui_story_5031_50311601_98X12_dialog_content = "是卡蓮妳自己做到的喔，妳克服了執念，掌控了自己的全部心神與意志。",
  ui_story_5031_50311601_98X13_dialog_content = "是呢，不過PlayerName每次的話語都能給人帶來療癒心靈的能量。",
  ui_story_5031_50311601_98X14_dialog_content = "確實也很神奇呢～",
  ui_story_5031_50311601_98X15_dialog_content = "這，這樣嗎？",
  ui_story_5031_50311601_98X16_dialog_content = "我只是把我內心的真實想法說出來罷了。",
  ui_story_5031_50311601_98X17_dialog_content = "就是這一點，已經非常了不起了喔。",
  ui_story_5031_50311601_98X18_dialog_content = "是的。",
  ui_story_5031_50311601_98X19_dialog_content = "不過，卡蓮最近還是要多注意休息才行呢，光能恢復的事情不要著急。",
  ui_story_5031_50311601_98X20_dialog_content = "掌握不熟練，就會有光能外溢導致昏迷的情況。",
  ui_story_5031_50311601_98X21_dialog_content = "一定不可以在恢復期間強迫自己練習運用新力量喔！",
  ui_story_5031_50311601_98X22_dialog_content = "聽起來確實是卡蓮會做的事情呢。",
  ui_story_5031_50311601_98X23_dialog_content = "好的，我知道了。",
  ui_story_5031_50311601_98X24_dialog_content = "我會照顧好自己，不讓你們擔心的。",
  ui_story_5031_50311601_98X25_dialog_content = "覺醒這件事，等到我身體徹底恢復後，再和薇絲一起好好尋找規律訣竅吧。",
  ui_story_5031_50311601_98X26_dialog_content = "沒問題～",
  ui_story_5031_50311601_99_dialog_content = "妳就不用擔心啦，我和PlayerName的身體可是很強壯的，對吧？",
  ui_story_5031_50311601_100_dialog_content = "嗯，卡蓮偶爾也可以依賴一下我們。",
  ui_story_5031_50311601_101_dialog_content = "也讓我們照顧照顧妳吧！",
  ui_story_5031_50311601_102_dialog_content = "呵，那就拜託你們二位多關照了。",
  ui_story_5031_50311601_103_dialog_content = "沒問題！",
  ui_story_5031_50311601_104_dialog_content = "那麼接下來我們去做什麼呢？",
  ui_story_5031_50311601_105_dialog_content = "出了這麼大的亂子，感覺好泊城現在也是有一堆事情要處理。",
  ui_story_5031_50311601_106_dialog_content = "如果要代理執政，卡蓮應該會很忙吧？",
  ui_story_5031_50311601_107_dialog_content = "確實如此，不過在正式接手前，我想先去見一個人。",
  ui_story_5031_50311601_108_dialog_content = "見誰呀？",
  ui_story_5031_50311601_109_dialog_content = "艾維斯。",
  ui_story_5031_50311601_110_dialog_content = "<color=#e8d9bb>未完待續……</color>"
